// ========================================================
// Safe JSON Helpers
// ========================================================

function readJSON(fileName) {
  const filePath =
    path.join(
      DATA_DIR,
      fileName
    );

  if (!fs.existsSync(filePath)) {
    return null;
  }

  try {
    return JSON.parse(
      fs.readFileSync(
        filePath,
        "utf8"
      )
    );
  } catch (err) {
    console.error(
      `Failed to parse ${fileName}:`,
      err.message
    );

    return null;
  }
}

function atomicWriteJSON(
  filePath,
  value
) {
  fs.mkdirSync(
    path.dirname(filePath),
    {
      recursive: true,
    }
  );

  const tempFile =
    `${filePath}.${process.pid}.${Date.now()}.tmp`;

  fs.writeFileSync(
    tempFile,
    JSON.stringify(
      value,
      null,
      2
    ),
    "utf8"
  );

  fs.renameSync(
    tempFile,
    filePath
  );
}

// ========================================================
// Shared Object Validation
// ========================================================

function isPlainObject(
  value
) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

// ========================================================
// AI Memory Safe Loading
// ========================================================

function createUnavailableAIMemoryState(
  reason
) {
  return {
    available: false,
    valid: false,

    enabled:
      AI_MEMORY_INTEGRATION.enabled,

    mode:
      AI_MEMORY_INTEGRATION.mode,

    reason:
      reason ||
      "AI Memory is unavailable",

    generatedAt: null,
    engineName: null,
    engineVersion: null,
    data: null,
  };
}

function validateAIMemoryDocument(
  document
) {
  if (!isPlainObject(document)) {
    return {
      valid: false,

      reason:
        "AI Memory root must be an object",
    };
  }

  if (
    document.version !==
      AI_MEMORY_SCHEMA_VERSION
  ) {
    return {
      valid: false,

      reason:
        `AI Memory schema version ${String(
          document.version
        )} is unsupported; expected ${AI_MEMORY_SCHEMA_VERSION}`,
    };
  }

  if (
    document.engineName !==
      AI_MEMORY_ENGINE_NAME
  ) {
    return {
      valid: false,

      reason:
        "AI Memory engine name is missing or unsupported",
    };
  }

  if (
    document.engineVersion !==
      AI_MEMORY_ENGINE_VERSION
  ) {
    return {
      valid: false,

      reason:
        `AI Memory engine version ${String(
          document.engineVersion
        )} is unsupported; expected ${AI_MEMORY_ENGINE_VERSION}`,
    };
  }

  if (
    typeof document.generatedAt !==
      "string" ||
    Number.isNaN(
      Date.parse(
        document.generatedAt
      )
    )
  ) {
    return {
      valid: false,

      reason:
        "AI Memory generatedAt timestamp is invalid",
    };
  }

  if (
    !isPlainObject(
      document.memory
    )
  ) {
    return {
      valid: false,

      reason:
        "AI Memory memory section is missing",
    };
  }

  if (
    !isPlainObject(
      document.memory.pairs
    ) ||
    !isPlainObject(
      document.memory.engines
    ) ||
    !isPlainObject(
      document.memory.directions
    ) ||
    !isPlainObject(
      document.memory.timeframes
    )
  ) {
    return {
      valid: false,

      reason:
        "AI Memory core metric sections are incomplete",
    };
  }

  if (
    !isPlainObject(
      document.combinations
    )
  ) {
    return {
      valid: false,

      reason:
        "AI Memory combinations section is missing",
    };
  }

  return {
    valid: true,
    reason: null,
  };
}

function loadAIMemory() {
  if (
    !AI_MEMORY_INTEGRATION.enabled
  ) {
    return createUnavailableAIMemoryState(
      "AI Memory integration is disabled"
    );
  }

  if (
    !fs.existsSync(
      AI_MEMORY_PATH
    )
  ) {
    return createUnavailableAIMemoryState(
      "data/ai-memory.json is missing"
    );
  }

  let document;

  try {
    document =
      JSON.parse(
        fs.readFileSync(
          AI_MEMORY_PATH,
          "utf8"
        )
      );
  } catch (err) {
    console.error(
      "Failed to read AI Memory:",
      err.message
    );

    return createUnavailableAIMemoryState(
      "data/ai-memory.json is unreadable or contains invalid JSON"
    );
  }

  const validation =
    validateAIMemoryDocument(
      document
    );

  if (!validation.valid) {
    console.warn(
      "AI Memory validation failed:",
      validation.reason
    );

    return createUnavailableAIMemoryState(
      validation.reason
    );
  }

  return {
    available: true,
    valid: true,
    enabled: true,

    mode:
      AI_MEMORY_INTEGRATION.mode,

    reason: null,

    generatedAt:
      document.generatedAt,

    engineName:
      document.engineName,

    engineVersion:
      document.engineVersion,

    data:
      document,
  };
}

// ========================================================
// AI Memory Metric Matching
// ========================================================
function normalizeAIMemoryEngine(
  value
) {
  if (
    typeof value !== "string" ||
    !value.trim()
  ) {
    return null;
  }

  const normalized =
    value
      .trim()
      .toLowerCase()
      .replace(
        /[^a-z0-9]/g,
        ""
      );

  if (
    normalized === "scalp" ||
    normalized === "scalping"
  ) {
    return "scalp";
  }

  if (
    normalized === "intraday" ||
    normalized === "daily" ||
    normalized === "day"
  ) {
    return "daily";
  }

  if (
    normalized === "swing" ||
    normalized === "weekly" ||
    normalized === "week"
  ) {
    return "weekly";
  }

  if (
    normalized === "master"
  ) {
    return "master";
  }

  return null;
}

function normalizeAIMemoryTimeframe(
  value
) {
  if (
    typeof value !== "string" ||
    !value.trim()
  ) {
    return null;
  }

  const normalized =
    value
      .trim()
      .toUpperCase()
      .replace(
        /\s+/g,
        ""
      );

  const aliases = {
    "5M": "5m",
    "M5": "5m",
    "5MIN": "5m",
    "5MINUTE": "5m",

    "15M": "15m",
    "M15": "15m",
    "15MIN": "15m",
    "15MINUTE": "15m",

    "30M": "30m",
    "M30": "30m",
    "30MIN": "30m",
    "30MINUTE": "30m",

    "1H": "1H",
    "H1": "1H",
    "60M": "1H",
    "60MIN": "1H",

    "4H": "4H",
    "H4": "4H",

    "1D": "D1",
    "D1": "D1",
    "DAILY": "D1",

    "1W": "W1",
    "W1": "W1",
    "WEEKLY": "W1",
  };

  return aliases[normalized] || null;
}

function normalizeAIMemoryDirection(
  value
) {
  const decision =
    normalizeSignalDecision(
      value
    );

  return (
    decision === "BUY" ||
    decision === "SELL"
  )
    ? decision
    : null;
}

function normalizeAIMemoryMetric(
  metric
) {
  if (!isPlainObject(metric)) {
    return null;
  }

  const rawTotalTrades =
    firstFiniteNumber(
      metric.totalTrades,
      metric.total,
      metric.resolved,
      metric.samples
    );

  const rawWins =
    firstFiniteNumber(
      metric.wins,
      metric.learningConfidence &&
        metric.learningConfidence.wins
    );

  const rawLosses =
    firstFiniteNumber(
      metric.losses,
      metric.learningConfidence &&
        metric.learningConfidence.losses
    );

  const rawWinRate =
    firstFiniteNumber(
      metric.winRate,
      metric.learningConfidence &&
        metric.learningConfidence.winRate
    );

  const rawProfitFactor =
    firstFiniteNumber(
      metric.profitFactor,
      metric.learningConfidence &&
        metric.learningConfidence.profitFactor
    );

  const averageProfitPoints =
    firstFiniteNumber(
      metric.averageProfitPoints,
      metric.learningConfidence &&
        metric.learningConfidence.averageProfitPoints
    );

  const averageResultPercentage =
    firstFiniteNumber(
      metric.averageResultPercentage
    );

  if (
    rawTotalTrades == null ||
    rawTotalTrades < 0
  ) {
    return null;
  }

  const totalTrades =
    Math.max(
      0,
      Math.trunc(rawTotalTrades)
    );

  const wins =
    rawWins == null
      ? null
      : Math.max(
          0,
          Math.trunc(rawWins)
        );

  const losses =
    rawLosses == null
      ? null
      : Math.max(
          0,
          Math.trunc(rawLosses)
        );

  if (
    wins !== null &&
    losses !== null &&
    wins + losses > totalTrades
  ) {
    return null;
  }

  if (
    rawWinRate !== null &&
    (rawWinRate < 0 || rawWinRate > 100)
  ) {
    return null;
  }

  if (
    rawProfitFactor !== null &&
    rawProfitFactor < 0
  ) {
    return null;
  }

  /*
   * Confidence reliability is based on decisive WIN/LOSS evidence.
   * BREAKEVEN trades remain part of totalTrades but cannot make a weak
   * directional sample look statistically mature.
   */
  const decisiveTrades =
    wins !== null &&
    losses !== null
      ? wins + losses
      : totalTrades;

  return {
    totalTrades,
    decisiveTrades,
    wins,
    losses,

    winRate:
      rawWinRate == null
        ? null
        : Number(
            rawWinRate.toFixed(2)
          ),

    profitFactor:
      rawProfitFactor == null
        ? null
        : Number(
            rawProfitFactor.toFixed(4)
          ),

    averageProfitPoints:
      averageProfitPoints == null
        ? null
        : Number(
            averageProfitPoints.toFixed(
              8
            )
          ),

    averageResultPercentage:
      averageResultPercentage == null
        ? null
        : Number(
            averageResultPercentage.toFixed(
              8
            )
          ),
  };
}

function getAIMemoryMetricByKey(
  container,
  key
) {
  if (
    !isPlainObject(container) ||
    typeof key !== "string" ||
    !key
  ) {
    return null;
  }

  if (
    !Object.prototype
      .hasOwnProperty.call(
        container,
        key
      )
  ) {
    return null;
  }

  return normalizeAIMemoryMetric(
    container[key]
  );
}

function resolveAIMemoryMetric(
  aiMemoryState,
  context = {}
) {
  if (
    !aiMemoryState ||
    !aiMemoryState.available ||
    !aiMemoryState.valid ||
    !isPlainObject(
      aiMemoryState.data
    )
  ) {
    return {
      matched: false,
      matchedBy: null,
      matchedKey: null,
      metric: null,

      reason:
        aiMemoryState &&
        aiMemoryState.reason
          ? aiMemoryState.reason
          : "AI Memory is unavailable",
    };
  }

  const memory =
    aiMemoryState.data.memory;

  const combinations =
    aiMemoryState.data.combinations;

  const pairKey =
    normalizePairKey(
      firstString(
        context.pair,
        context.pairKey,
        context.symbol,
        context.instrument
      )
    );

  const engine =
    normalizeAIMemoryEngine(
      firstString(
        context.engine,
        context.engineName,
        context.mode,
        context.strategy
      )
    );

  const direction =
    normalizeAIMemoryDirection(
      firstString(
        context.direction,
        context.decision,
        context.signal,
        context.action
      )
    );

  const timeframe =
    normalizeAIMemoryTimeframe(
      firstString(
        context.timeframe,
        context.tf,
        context.interval
      )
    );

  const candidates = [];

  if (
    pairKey &&
    engine &&
    direction
  ) {
    candidates.push({
      matchedBy:
        "pairEngineDirection",

      matchedKey:
        `${pairKey}::${engine}::${direction}`,

      container:
        combinations
          .pairEngineDirection,
    });
  }

  if (
    pairKey &&
    engine
  ) {
    candidates.push({
      matchedBy:
        "pairEngine",

      matchedKey:
        `${pairKey}::${engine}`,

      container:
        combinations
          .pairEngine,
    });
  }

  if (
    engine &&
    direction
  ) {
    candidates.push({
      matchedBy:
        "engineDirection",

      matchedKey:
        `${engine}::${direction}`,

      container:
        combinations
          .engineDirection,
    });
  }

  if (
    pairKey &&
    direction
  ) {
    candidates.push({
      matchedBy:
        "pairDirection",

      matchedKey:
        `${pairKey}::${direction}`,

      container:
        combinations
          .pairDirection,
    });
  }

  if (timeframe) {
    candidates.push({
      matchedBy:
        "timeframe",

      matchedKey:
        timeframe,

      container:
        memory.timeframes,
    });
  }

  if (pairKey) {
    candidates.push({
      matchedBy:
        "pair",

      matchedKey:
        pairKey,

      container:
        memory.pairs,
    });
  }

  if (
    engine &&
    engine !== "master"
  ) {
    candidates.push({
      matchedBy:
        "engine",

      matchedKey:
        engine,

      container:
        memory.engines,
    });
  }

  if (direction) {
    candidates.push({
      matchedBy:
        "direction",

      matchedKey:
        direction,

      container:
        memory.directions,
    });
  }

  for (
    const candidate of candidates
  ) {
    const metric =
      getAIMemoryMetricByKey(
        candidate.container,
        candidate.matchedKey
      );

    if (
      metric &&
      metric.totalTrades > 0
    ) {
      return {
        matched: true,

        matchedBy:
          candidate.matchedBy,

        matchedKey:
          candidate.matchedKey,

        metric,

        reason: null,
      };
    }
  }

  return {
    matched: false,
    matchedBy: null,
    matchedKey: null,
    metric: null,

    reason:
      "No usable AI Memory metric matched the signal context",
  };
}

// ========================================================
// AI Memory Shadow Assessment
// ========================================================
function clampAIMemoryNumber(
  value,
  minimum,
  maximum
) {
  if (!Number.isFinite(value)) {
    return minimum;
  }

  return Math.min(
    maximum,
    Math.max(
      minimum,
      value
    )
  );
}

function calculateAIMemoryReliability(
  sampleSize
) {
  if (
    !Number.isFinite(sampleSize) ||
    sampleSize <= 0
  ) {
    return 0;
  }

  if (
    sampleSize >=
    AI_MEMORY_INTEGRATION
      .strongMinimumSamples
  ) {
    return 1;
  }

  if (
    sampleSize <
    AI_MEMORY_INTEGRATION
      .minimumSamples
  ) {
    return Number(
      (
        sampleSize /
        AI_MEMORY_INTEGRATION
          .minimumSamples *
        0.5
      ).toFixed(4)
    );
  }

  const range =
    AI_MEMORY_INTEGRATION
      .strongMinimumSamples -
    AI_MEMORY_INTEGRATION
      .minimumSamples;

  const position =
    sampleSize -
    AI_MEMORY_INTEGRATION
      .minimumSamples;

  return Number(
    (
      0.5 +
      (
        range > 0
          ? position / range
          : 1
      ) *
        0.5
    ).toFixed(4)
  );
}

function classifyAIMemoryStatus(
  metric
) {
  if (
    !metric ||
    !Number.isFinite(
      metric.totalTrades
    ) ||
    (
      Number.isFinite(metric.decisiveTrades)
        ? metric.decisiveTrades
        : metric.totalTrades
    ) <
      AI_MEMORY_INTEGRATION
        .minimumSamples
  ) {
    return "INSUFFICIENT_DATA";
  }

  const profitFactor =
    Number.isFinite(
      metric.profitFactor
    )
      ? metric.profitFactor
      : null;

  const winRate =
    Number.isFinite(
      metric.winRate
    )
      ? metric.winRate
      : null;

  const averageProfitPoints =
    Number.isFinite(
      metric.averageProfitPoints
    )
      ? metric.averageProfitPoints
      : null;

  const strongProfitFactor =
    profitFactor !== null &&
    profitFactor >=
      AI_MEMORY_INTEGRATION
        .strongProfitFactor;

  const strongWinRate =
    winRate !== null &&
    winRate >=
      AI_MEMORY_INTEGRATION
        .strongWinRate;

  const positiveAverage =
    averageProfitPoints !== null &&
    averageProfitPoints > 0;

  if (
    strongProfitFactor &&
    strongWinRate &&
    positiveAverage
  ) {
    return "STRONGLY_SUPPORTIVE";
  }

  const supportiveProfitFactor =
    profitFactor !== null &&
    profitFactor >=
      AI_MEMORY_INTEGRATION
        .supportiveProfitFactor;

  const supportiveWinRate =
    winRate !== null &&
    winRate >=
      AI_MEMORY_INTEGRATION
        .supportiveWinRate;

  if (
    positiveAverage &&
    (
      supportiveProfitFactor ||
      supportiveWinRate
    )
  ) {
    return "SUPPORTIVE";
  }

  const cautionProfitFactor =
    profitFactor !== null &&
    profitFactor <
      AI_MEMORY_INTEGRATION
        .cautionProfitFactor;

  const cautionWinRate =
    winRate !== null &&
    winRate <
      AI_MEMORY_INTEGRATION
        .cautionWinRate;

  const negativeAverage =
    averageProfitPoints !== null &&
    averageProfitPoints < 0;

  if (
    negativeAverage &&
    (
      cautionProfitFactor ||
      cautionWinRate
    )
  ) {
    return "CAUTION";
  }

  return "NEUTRAL";
}

function calculateAIMemoryRawAdjustment(
  metric,
  status
) {
  if (
    !metric ||
    status === "INSUFFICIENT_DATA"
  ) {
    return 0;
  }

  let adjustment = 0;

  if (
    Number.isFinite(
      metric.profitFactor
    )
  ) {
    if (
      metric.profitFactor >=
      AI_MEMORY_INTEGRATION
        .strongProfitFactor
    ) {
      adjustment += 4;
    } else if (
      metric.profitFactor >=
      AI_MEMORY_INTEGRATION
        .supportiveProfitFactor
    ) {
      adjustment += 2;
    } else if (
      metric.profitFactor <
      AI_MEMORY_INTEGRATION
        .cautionProfitFactor
    ) {
      adjustment -= 4;
    } else if (
      metric.profitFactor < 1
    ) {
      adjustment -= 2;
    }
  }

  if (
    Number.isFinite(
      metric.winRate
    )
  ) {
    if (
      metric.winRate >=
      AI_MEMORY_INTEGRATION
        .strongWinRate
    ) {
      adjustment += 3;
    } else if (
      metric.winRate >=
      AI_MEMORY_INTEGRATION
        .supportiveWinRate
    ) {
      adjustment += 1;
    } else if (
      metric.winRate <
      AI_MEMORY_INTEGRATION
        .cautionWinRate
    ) {
      adjustment -= 3;
    }
  }

  if (
    Number.isFinite(
      metric.averageProfitPoints
    )
  ) {
    if (
      metric.averageProfitPoints > 0
    ) {
      adjustment += 1;
    } else if (
      metric.averageProfitPoints < 0
    ) {
      adjustment -= 1;
    }
  }

  if (
    status ===
    "STRONGLY_SUPPORTIVE"
  ) {
    adjustment =
      Math.max(
        adjustment,
        5
      );
  }

  if (
    status === "SUPPORTIVE"
  ) {
    adjustment =
      Math.max(
        adjustment,
        1
      );
  }

  if (
    status === "CAUTION"
  ) {
    adjustment =
      Math.min(
        adjustment,
        -1
      );
  }

  return clampAIMemoryNumber(
    adjustment,
    -AI_MEMORY_INTEGRATION
      .maximumSuggestedAdjustment,
    AI_MEMORY_INTEGRATION
      .maximumSuggestedAdjustment
  );
}

function buildAIMemoryReason(
  status,
  metric,
  matchedBy
) {
  const sampleSize =
    metric &&
    Number.isFinite(
      metric.decisiveTrades
    )
      ? metric.decisiveTrades
      : metric &&
        Number.isFinite(metric.totalTrades)
        ? metric.totalTrades
        : 0;

  const sourceLabel =
    matchedBy ||
    "no matching dimension";

  if (
    status === "INSUFFICIENT_DATA"
  ) {
    return (
      `AI Memory matched ${sourceLabel}, ` +
      `but only ${sampleSize} historical trade` +
      `${sampleSize === 1 ? "" : "s"} are available`
    );
  }

  if (
    status ===
    "STRONGLY_SUPPORTIVE"
  ) {
    return (
      `Historical ${sourceLabel} performance ` +
      `strongly supports this signal`
    );
  }

  if (
    status === "SUPPORTIVE"
  ) {
    return (
      `Historical ${sourceLabel} performance ` +
      `supports this signal`
    );
  }

  if (
    status === "CAUTION"
  ) {
    return (
      `Historical ${sourceLabel} performance ` +
      `suggests caution for this signal`
    );
  }

  return (
    `Historical ${sourceLabel} performance ` +
    `is mixed or neutral`
  );
}

function createUnavailableAIMemoryAssessment(
  aiMemoryState,
  reason
) {
  return {
    enabled:
      Boolean(
        AI_MEMORY_INTEGRATION.enabled
      ),

    available:
      Boolean(
        aiMemoryState &&
        aiMemoryState.available
      ),

    valid:
      Boolean(
        aiMemoryState &&
        aiMemoryState.valid
      ),

    mode:
      AI_MEMORY_INTEGRATION.mode,

    applied: false,

    status: "UNAVAILABLE",

    reason:
      reason ||
      (
        aiMemoryState &&
        aiMemoryState.reason
      ) ||
      "AI Memory is unavailable",

    matchedBy: null,
    matchedKey: null,

    sampleSize: 0,
    wins: null,
    losses: null,
    winRate: null,
    profitFactor: null,
    averageProfitPoints: null,
    averageResultPercentage: null,

    reliability: 0,

    confidenceAdjustment: 0,
    suggestedConfidenceAdjustment: 0,

    generatedAt:
      aiMemoryState &&
      aiMemoryState.generatedAt
        ? aiMemoryState.generatedAt
        : null,

    engineName:
      aiMemoryState &&
      aiMemoryState.engineName
        ? aiMemoryState.engineName
        : null,

    engineVersion:
      aiMemoryState &&
      aiMemoryState.engineVersion
        ? aiMemoryState.engineVersion
        : null,
  };
}

function createAIMemoryAssessment(
  aiMemoryState,
  context = {}
) {
  if (
    !AI_MEMORY_INTEGRATION.enabled
  ) {
    return createUnavailableAIMemoryAssessment(
      aiMemoryState,
      "AI Memory integration is disabled"
    );
  }

  if (
    !aiMemoryState ||
    !aiMemoryState.available ||
    !aiMemoryState.valid
  ) {
    return createUnavailableAIMemoryAssessment(
      aiMemoryState
    );
  }

  const direction =
    normalizeAIMemoryDirection(
      firstString(
        context.direction,
        context.decision,
        context.signal,
        context.action
      )
    );

  if (!direction) {
    return {
      ...createUnavailableAIMemoryAssessment(
        aiMemoryState,
        "AI Memory assessment requires a BUY or SELL decision"
      ),

      available: true,
      valid: true,
      status: "NOT_APPLICABLE",
    };
  }

  const match =
    resolveAIMemoryMetric(
      aiMemoryState,
      {
        ...context,
        direction,
      }
    );

  if (
    !match.matched ||
    !match.metric
  ) {
    return {
      ...createUnavailableAIMemoryAssessment(
        aiMemoryState,
        match.reason
      ),

      available: true,
      valid: true,
      status: "NO_MATCH",
    };
  }

  const metric =
    match.metric;

  const status =
    classifyAIMemoryStatus(
      metric
    );

  const reliability =
    calculateAIMemoryReliability(
      Number.isFinite(metric.decisiveTrades)
        ? metric.decisiveTrades
        : metric.totalTrades
    );

  const rawAdjustment =
    calculateAIMemoryRawAdjustment(
      metric,
      status
    );

  const suggestedAdjustment =
    Math.round(
      rawAdjustment *
      reliability
    );

  return {
    enabled: true,
    available: true,
    valid: true,

    mode:
      AI_MEMORY_INTEGRATION.mode,

    applied: false,

    status,

    reason:
      buildAIMemoryReason(
        status,
        metric,
        match.matchedBy
      ),

    matchedBy:
      match.matchedBy,

    matchedKey:
      match.matchedKey,

    sampleSize:
      Number.isFinite(metric.decisiveTrades)
        ? metric.decisiveTrades
        : metric.totalTrades,

    totalTrades:
      metric.totalTrades,

    wins:
      metric.wins,

    losses:
      metric.losses,

    winRate:
      metric.winRate,

    profitFactor:
      metric.profitFactor,

    averageProfitPoints:
      metric.averageProfitPoints,

    averageResultPercentage:
      metric.averageResultPercentage,

    reliability,

    confidenceAdjustment: 0,

    suggestedConfidenceAdjustment:
      suggestedAdjustment,

    generatedAt:
      aiMemoryState.generatedAt,

    engineName:
      aiMemoryState.engineName,

    engineVersion:
      aiMemoryState.engineVersion,
  };
}

function hasUpstreamAIMemoryConfidenceStep(
  engineResult
) {
  if (
    !engineResult ||
    typeof engineResult !== "object" ||
    Array.isArray(engineResult)
  ) {
    return false;
  }

  const steps =
    Array.isArray(
      engineResult.steps
    )
      ? engineResult.steps
      : Array.isArray(
          engineResult.pipeline
        )
        ? engineResult.pipeline
        : [];

  const hasPipelineStep =
    steps.some((step) => {
      if (
        !step ||
        typeof step !== "object" ||
        Array.isArray(step)
      ) {
        return false;
      }

      const name =
        typeof step.name === "string"
          ? step.name
              .trim()
              .toLowerCase()
              .replace(
                /[^a-z0-9]/g,
                ""
              )
          : "";

      return (
        name ===
        "aimemoryconfidence"
      );
    });

  if (hasPipelineStep) {
    return true;
  }

  const memoryMetadata =
    isPlainObject(engineResult.aiMemory)
      ? engineResult.aiMemory
      : null;

  if (
    memoryMetadata &&
    (
      memoryMetadata.applied === true ||
      Number.isFinite(
        Number(
          memoryMetadata
            .appliedConfidenceAdjustment
        )
      ) &&
      Number(
        memoryMetadata
          .appliedConfidenceAdjustment
      ) !== 0
    )
  ) {
    return true;
  }

  const explainability =
    isPlainObject(
      engineResult.confidenceExplainability
    )
      ? engineResult.confidenceExplainability
      : null;

  return Boolean(
    explainability &&
    explainability.applied === true
  );
}

// ========================================================
// Confidence Explainability Helpers
// ========================================================

function normalizeConfidenceExplainabilityStatus(
  memoryAssessment,
  appliedAdjustment
) {
  if (appliedAdjustment > 0) {
    return "SUPPORTIVE";
  }

  if (appliedAdjustment < 0) {
    return "CAUTION";
  }

  const status =
    memoryAssessment &&
    typeof memoryAssessment.status === "string"
      ? memoryAssessment.status
          .trim()
          .toUpperCase()
      : "NEUTRAL";

  if (
    status === "STRONGLY_SUPPORTIVE" ||
    status === "SUPPORTIVE"
  ) {
    return "SUPPORTIVE";
  }

  if (status === "CAUTION") {
    return "CAUTION";
  }

  if (
    status === "INSUFFICIENT_DATA" ||
    status === "NO_MATCH" ||
    status === "NOT_APPLICABLE" ||
    status === "UNAVAILABLE"
  ) {
    return status;
  }

  return "NEUTRAL";
}

function buildConfidenceExplainability(
  engineResult,
  memoryAssessment,
  options = {}
) {
  /*
   * Preserve Scalp Engine provenance exactly.
   *
   * This also ensures the duplicate-adjustment guard does not replace
   * the original Scalp explanation with a downstream version.
   */
  if (
    engineResult &&
    typeof engineResult === "object" &&
    !Array.isArray(engineResult) &&
    engineResult.confidenceExplainability &&
    typeof engineResult.confidenceExplainability === "object" &&
    !Array.isArray(
      engineResult.confidenceExplainability
    )
  ) {
    return liveCloneValue(
      engineResult.confidenceExplainability
    );
  }

  const baseConfidenceValue =
    firstFiniteNumber(
      options.baseConfidence
    );

  const baseConfidence =
    baseConfidenceValue === null
      ? 0
      : clampAIMemoryNumber(
          baseConfidenceValue,
          0,
          100
        );

  const aiAdjustmentValue =
    firstFiniteNumber(
      options.aiAdjustment
    );

  const aiAdjustment =
    aiAdjustmentValue === null
      ? 0
      : Math.round(
          aiAdjustmentValue
        );

  const finalConfidenceValue =
    firstFiniteNumber(
      options.finalConfidence
    );

  const finalConfidence =
    finalConfidenceValue === null
      ? baseConfidence
      : clampAIMemoryNumber(
          finalConfidenceValue,
          0,
          100
        );

  const sampleSizeValue =
    firstFiniteNumber(
      memoryAssessment &&
        memoryAssessment.sampleSize
    );

  const sampleSize =
    sampleSizeValue === null
      ? 0
      : Math.max(
          0,
          Math.trunc(sampleSizeValue)
        );

  /*
   * Missing statistical metadata remains null.
   * Zero is never invented for missing win rate, profit factor or
   * reliability.
   */
  const winRate =
    firstFiniteNumber(
      memoryAssessment &&
        memoryAssessment.winRate
    );

  const profitFactor =
    firstFiniteNumber(
      memoryAssessment &&
        memoryAssessment.profitFactor
    );

  const reliability =
    firstFiniteNumber(
      memoryAssessment &&
        memoryAssessment.reliability
    );

  return {
    version: 1,

    adjustmentOwner:
      "live-analysis",

    baseConfidence,

    aiAdjustment,

    finalConfidence,

    evaluated:
      Boolean(
        memoryAssessment &&
        memoryAssessment.enabled === true &&
        memoryAssessment.available === true &&
        memoryAssessment.valid === true
      ),

    matched:
      Boolean(
        memoryAssessment &&
        memoryAssessment.matchedBy &&
        memoryAssessment.matchedKey
      ),

    applied:
      options.applied === true,

    status:
      normalizeConfidenceExplainabilityStatus(
        memoryAssessment,
        aiAdjustment
      ),

    source:
      memoryAssessment &&
      typeof memoryAssessment.matchedBy ===
        "string"
        ? memoryAssessment.matchedBy
        : null,

    key:
      memoryAssessment &&
      typeof memoryAssessment.matchedKey ===
        "string"
        ? memoryAssessment.matchedKey
        : null,

    sampleSize,

    winRate,

    profitFactor,

    reliability,

    reason:
      options.applicationReason ||
      (
        memoryAssessment &&
        typeof memoryAssessment.reason ===
          "string"
          ? memoryAssessment.reason
          : "AI Memory confidence evaluation did not provide a reason"
      ),
  };
}

// ========================================================
// AI Memory Controlled Confidence Application
// ========================================================
function applyAIMemoryConfidenceAdjustment(
  engineResult,
  assessment
) {
  if (
    !engineResult ||
    typeof engineResult !== "object" ||
    Array.isArray(engineResult)
  ) {
    return engineResult;
  }

  const memoryAssessment =
    assessment &&
    typeof assessment === "object" &&
    !Array.isArray(assessment)
      ? assessment
      : createUnavailableAIMemoryAssessment(
          null,
          "AI Memory assessment is unavailable"
        );

  const rawConfidence =
    Number(
      engineResult.confidence
    );

  const originalConfidence =
    Number.isFinite(rawConfidence)
      ? clampAIMemoryNumber(
          rawConfidence,
          0,
          100
        )
      : 0;

  const decision =
    normalizeSignalDecision(
      firstString(
        engineResult.decision,
        engineResult.signal,
        engineResult.action,
        engineResult.direction
      )
    ) ||
    "HOLD";

  function buildUnappliedResult(
    applicationReason
  ) {
    return {
      ...engineResult,

      confidence:
        originalConfidence,

      confidencePct:
        originalConfidence,

      originalConfidence,

      aiMemoryAdjustedConfidence:
        originalConfidence,

      confidenceExplainability:
        buildConfidenceExplainability(
          engineResult,
          memoryAssessment,
          {
            baseConfidence:
              originalConfidence,

            aiAdjustment: 0,

            finalConfidence:
              originalConfidence,

            applied: false,

            applicationReason,
          }
        ),

      aiMemory: {
        ...memoryAssessment,

        applied: false,

        confidenceAdjustment: 0,

        appliedConfidenceAdjustment: 0,

        originalConfidence,

        adjustedConfidence:
          originalConfidence,

        applicationReason:
          applicationReason ||
          "AI Memory confidence adjustment was not applied",
      },
    };
  }

  const normalizedMode =
    liveNormalizeMode(
      firstString(
        engineResult.mode,
        engineResult.engine,
        engineResult.engineName
      ),
      "unknown"
    );

  /*
   * Scalp confidence is always owned by the Scalp Engine. Live Analysis may
   * attach the assessment for explainability, but it must never become a
   * second Scalp confidence owner when an upstream step is absent or renamed.
   */
  if (normalizedMode === "scalp") {
    return buildUnappliedResult(
      "Scalp confidence is owned by the Scalp Signal Engine; Live Analysis preserved the upstream confidence without applying an additional adjustment"
    );
  }

  /*
   * The dedicated Scalp Signal Engine is the canonical owner of Scalp
   * confidence adjustment.
   *
   * Its existing "AI Memory Confidence" pipeline step proves that
   * AI Memory was already evaluated upstream, including cases where
   * the bounded adjustment was zero.
   *
   * Preserve that confidence and never apply a second Live Analysis
   * adjustment.
   */
  if (
    hasUpstreamAIMemoryConfidenceStep(
      engineResult
    )
  ) {
    return buildUnappliedResult(
      "AI Memory confidence was already evaluated by the Scalp Signal Engine; Live Analysis preserved the upstream confidence without applying a second adjustment"
    );
  }

  if (
    !AI_MEMORY_INTEGRATION.enabled
  ) {
    return buildUnappliedResult(
      "AI Memory integration is disabled"
    );
  }

  if (
    AI_MEMORY_INTEGRATION.mode !==
    "CONTROLLED"
  ) {
    return buildUnappliedResult(
      "AI Memory is not running in CONTROLLED mode"
    );
  }

  if (
    AI_MEMORY_INTEGRATION
      .applyConfidenceAdjustment !==
    true
  ) {
    return buildUnappliedResult(
      "AI Memory confidence adjustment is disabled"
    );
  }

  if (
    decision !== "BUY" &&
    decision !== "SELL"
  ) {
    return buildUnappliedResult(
      "Confidence adjustment requires a BUY or SELL decision"
    );
  }

  if (
    memoryAssessment.available !==
      true ||
    memoryAssessment.valid !==
      true
  ) {
    return buildUnappliedResult(
      memoryAssessment.reason ||
      "AI Memory is unavailable or invalid"
    );
  }

  if (
    memoryAssessment.status ===
      "INSUFFICIENT_DATA" ||
    memoryAssessment.status ===
      "UNAVAILABLE" ||
    memoryAssessment.status ===
      "NO_MATCH" ||
    memoryAssessment.status ===
      "NOT_APPLICABLE"
  ) {
    return buildUnappliedResult(
      memoryAssessment.reason ||
      "AI Memory assessment is not eligible for confidence adjustment"
    );
  }

  const sampleSize =
    Number(
      memoryAssessment.sampleSize
    );

  if (
    !Number.isFinite(sampleSize) ||
    sampleSize <
      AI_MEMORY_INTEGRATION
        .minimumSamplesToApply
  ) {
    return buildUnappliedResult(
      `AI Memory requires at least ${
        AI_MEMORY_INTEGRATION
          .minimumSamplesToApply
      } historical trades before applying confidence`
    );
  }

  const reliability =
    Number(
      memoryAssessment.reliability
    );

  if (
    !Number.isFinite(reliability) ||
    reliability <
      AI_MEMORY_INTEGRATION
        .minimumReliabilityToApply
  ) {
    return buildUnappliedResult(
      `AI Memory reliability must be at least ${
        AI_MEMORY_INTEGRATION
          .minimumReliabilityToApply
      } before applying confidence`
    );
  }

  const suggestedAdjustment =
    Number(
      memoryAssessment
        .suggestedConfidenceAdjustment
    );

  if (
    !Number.isFinite(
      suggestedAdjustment
    ) ||
    suggestedAdjustment === 0
  ) {
    return buildUnappliedResult(
      "AI Memory suggested no confidence adjustment"
    );
  }

  const maximumAdjustment =
    Math.abs(
      Number(
        AI_MEMORY_INTEGRATION
          .maximumAppliedAdjustment
      )
    );

  const safeMaximumAdjustment =
    Number.isFinite(
      maximumAdjustment
    )
      ? maximumAdjustment
      : 0;

  const appliedAdjustment =
    Math.round(
      clampAIMemoryNumber(
        suggestedAdjustment,
        -safeMaximumAdjustment,
        safeMaximumAdjustment
      )
    );

  if (
    appliedAdjustment === 0
  ) {
    return buildUnappliedResult(
      "AI Memory adjustment was reduced to zero by safety limits"
    );
  }

  const adjustedConfidence =
    clampAIMemoryNumber(
      originalConfidence +
        appliedAdjustment,
      0,
      100
    );

  return {
    ...engineResult,

    confidence:
      adjustedConfidence,

    confidencePct:
      adjustedConfidence,

    originalConfidence,

    aiMemoryAdjustedConfidence:
      adjustedConfidence,

    confidenceExplainability:
      buildConfidenceExplainability(
        engineResult,
        memoryAssessment,
        {
          baseConfidence:
            originalConfidence,

          aiAdjustment:
            appliedAdjustment,

          finalConfidence:
            adjustedConfidence,

          applied: true,

          applicationReason:
            `AI Memory applied a bounded confidence adjustment of ${
              appliedAdjustment > 0
                ? "+"
                : ""
            }${appliedAdjustment}`,
        }
      ),

    aiMemory: {
      ...memoryAssessment,

      mode:
        AI_MEMORY_INTEGRATION.mode,

      applied: true,

      confidenceAdjustment:
        appliedAdjustment,

      appliedConfidenceAdjustment:
        appliedAdjustment,

      originalConfidence,

      adjustedConfidence,

      applicationReason:
        `AI Memory applied a bounded confidence adjustment of ${
          appliedAdjustment > 0
            ? "+"
            : ""
        }${appliedAdjustment}`,
    },
  };
}

// ========================================================
// Generic Helpers
// ========================================================
function isFiniteNumber(value) {
  return (
    typeof value === "number" &&
    Number.isFinite(value)
  );
}

function firstFiniteNumber(
  ...values
) {
  for (const value of values) {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      continue;
    }

    const numeric =
      Number(value);

    if (
      Number.isFinite(numeric)
    ) {
      return numeric;
    }
  }

  return null;
}

function firstString(
  ...values
) {
  for (const value of values) {
    if (
      typeof value === "string" &&
      value.trim()
    ) {
      return value.trim();
    }
  }

  return null;
}

function normalizeTime(value) {
  if (
    typeof value !== "string"
  ) {
    return null;
  }

  const trimmed =
    value.trim();

  const parsed =
    Date.parse(trimmed);

  return Number.isNaN(parsed)
    ? null
    : trimmed;
}

function normalizePairKey(value) {
  if (
    typeof value !== "string"
  ) {
    return null;
  }

  const normalized =
    value
      .trim()
      .toUpperCase()
      .replace(
        /[^A-Z0-9]/g,
        ""
      );

  return PAIR_KEYS.includes(
    normalized
  )
    ? normalized
    : null;
}

function normalizeSignalDecision(
  value
) {
  if (
    typeof value !== "string"
  ) {
    return null;
  }

  const normalized =
    value
      .trim()
      .toUpperCase()
      .replace(
        /\s+/g,
        " "
      );

  if (
    normalized === "WAIT" ||
    normalized === "NEUTRAL" ||
    normalized === "NO TRADE" ||
    normalized === "NO_TRADE"
  ) {
    return "HOLD";
  }

  if (
    normalized === "BUY" ||
    normalized === "SELL" ||
    normalized === "HOLD"
  ) {
    return normalized;
  }

  return null;
}

function roundPrice(
  value,
  decimals
) {
  if (
    !isFiniteNumber(value)
  ) {
    return null;
  }

  return Number(
    value.toFixed(decimals)
  );
}

// ========================================================
// Candle Validation
// ========================================================

function normalizeCandle(
  row,
  timeField
) {
  if (
    !row ||
    typeof row !== "object"
  ) {
    return null;
  }

  const timeValue =
    normalizeTime(
      row[timeField]
    );

  const open =
    Number(row.open);

  const high =
    Number(row.high);

  const low =
    Number(row.low);

  const close =
    Number(row.close);

  const prices = [
    open,
    high,
    low,
    close,
  ];

  if (
    !timeValue ||
    !prices.every(
      Number.isFinite
    ) ||
    prices.some(
      value => value <= 0
    ) ||
    high < low ||
    high < open ||
    high < close ||
    low > open ||
    low > close
  ) {
    return null;
  }

  return {
    ...row,

    [timeField]:
      timeValue,

    open,
    high,
    low,
    close,
  };
}

function validateCandles(
  rows,
  timeField
) {
  if (!Array.isArray(rows)) {
    return {
      rows: [],

      meta: {
        sourceRows: 0,
        validRows: 0,
        invalidRows: 0,
        duplicateRows: 0,
        latest: null,
        stale: true,
      },
    };
  }

  const rowsByTime =
    new Map();

  let invalidRows = 0;
  let duplicateRows = 0;

  for (const row of rows) {
    const normalized =
      normalizeCandle(
        row,
        timeField
      );

    if (!normalized) {
      invalidRows += 1;
      continue;
    }

    const key =
      normalized[timeField];

    if (
      rowsByTime.has(key)
    ) {
      duplicateRows += 1;
    }

    rowsByTime.set(
      key,
      normalized
    );
  }

  const cleanRows =
    [
      ...rowsByTime.values(),
    ].sort(
      (a, b) =>
        a[timeField]
          .localeCompare(
            b[timeField]
          )
    );

  const latest =
    cleanRows.length
      ? cleanRows[
          cleanRows.length - 1
        ][timeField]
      : null;

  return {
    rows:
      cleanRows,

    meta: {
      sourceRows:
        rows.length,

      validRows:
        cleanRows.length,

      invalidRows,

      duplicateRows,

      latest,

      stale:
        latest
          ? (
              Date.now() -
              Date.parse(latest)
            ) >
            7 * DAY_MS
          : true,
    },
  };
}

// ========================================================
// Dedicated Scalp Signal Helpers
// ========================================================
function extractDecisionFromRecord(
  record
) {
  if (
    !record ||
    typeof record !== "object"
  ) {
    return null;
  }

  return normalizeSignalDecision(
    firstString(
      record.decision,
      record.signal,
      record.verdict,
      record.action,
      record.recommendation,
      record.side
    )
  );
}

function unwrapScalpRecord(
  record
) {
  if (
    !record ||
    typeof record !== "object"
  ) {
    return null;
  }

  const candidates = [
    record.scalp,
    record.signalData,
    record.analysis,
    record.result,
    record.latest,
    record.current,
    record,
  ];

  for (
    const candidate of candidates
  ) {
    if (
      candidate &&
      typeof candidate ===
        "object" &&
      extractDecisionFromRecord(
        candidate
      )
    ) {
      return candidate;
    }
  }

  return record;
}

function normalizeScalpMode(
  value
) {
  if (
    typeof value !== "string"
  ) {
    return null;
  }

  const normalized =
    value
      .trim()
      .toUpperCase()
      .replace(
        /[^A-Z0-9]/g,
        ""
      );

  if (
    normalized === "M5" ||
    normalized === "5M" ||
    normalized === "5MIN" ||
    normalized === "5MINUTE"
  ) {
    return "M5";
  }

  if (
    normalized === "M15" ||
    normalized === "15M" ||
    normalized === "15MIN" ||
    normalized === "15MINUTE"
  ) {
    return "M15";
  }

  if (
    normalized === "M30" ||
    normalized === "30M" ||
    normalized === "30MIN" ||
    normalized === "30MINUTE"
  ) {
    return "M30";
  }

  return null;
}

function collectDedicatedScalpPairRecords(
  rawScalpSignals,
  pairKey
) {
  if (
    !rawScalpSignals ||
    typeof rawScalpSignals !==
      "object"
  ) {
    return [];
  }

  const records = [];

  const seenRecords =
    new Set();

  function addRecord(
    candidate
  ) {
    if (
      !candidate ||
      typeof candidate !==
        "object" ||
      Array.isArray(candidate)
    ) {
      return;
    }

    if (
      seenRecords.has(candidate)
    ) {
      return;
    }

    const rawPair =
      firstString(
        candidate.pair,
        candidate.symbol,
        candidate.pairKey,
        candidate.instrument,
        candidate.market
      );

    if (
      rawPair &&
      normalizePairKey(rawPair) !==
        pairKey
    ) {
      return;
    }

    const unwrapped =
      unwrapScalpRecord(
        candidate
      );

    const decision =
      extractDecisionFromRecord(
        unwrapped
      );

    if (!decision) {
      return;
    }

    seenRecords.add(candidate);

    records.push(candidate);
  }

  function inspectPairValue(
    value
  ) {
    if (!value) {
      return;
    }

    if (Array.isArray(value)) {
      for (
        const candidate of value
      ) {
        addRecord(candidate);
      }

      return;
    }

    addRecord(value);
  }

  function inspectContainer(
    container
  ) {
    if (!container) {
      return;
    }

    if (
      Array.isArray(container)
    ) {
      for (
        const candidate of
        container
      ) {
        addRecord(candidate);
      }

      return;
    }

    if (
      typeof container !==
        "object"
    ) {
      return;
    }

    const aliases =
      PAIR_ALIASES[pairKey] ||
      [pairKey];

    for (
      const alias of aliases
    ) {
      if (
        Object.prototype
          .hasOwnProperty.call(
            container,
            alias
          )
      ) {
        inspectPairValue(
          container[alias]
        );
      }
    }

    for (
      const [rawKey, value] of
      Object.entries(container)
    ) {
      if (
        normalizePairKey(
          rawKey
        ) === pairKey
      ) {
        inspectPairValue(value);
      }
    }
  }

  inspectContainer(
    rawScalpSignals.signals
  );

  inspectContainer(
    rawScalpSignals.pairs
  );

  inspectContainer(
    rawScalpSignals.results
  );

  inspectContainer(
    rawScalpSignals.data
  );

  inspectContainer(
    rawScalpSignals.latest
  );

  inspectContainer(
    rawScalpSignals
  );

  return records;
}

function parseDedicatedScalpRecord(
  pairRecord,
  rawScalpSignals,
  decimals
) {
  const record =
    unwrapScalpRecord(
      pairRecord
    );

  if (!record) {
    return null;
  }

  const decision =
    extractDecisionFromRecord(
      record
    );

  if (!decision) {
    return null;
  }

  const tradePlan =
    record.tradePlan &&
    typeof record.tradePlan ===
      "object"
      ? record.tradePlan
      : {};

  const entry =
    firstFiniteNumber(
      record.entry,
      record.entryPrice,
      record.price,
      record.currentPrice,
      tradePlan.entry,
      tradePlan.entryPrice
    );

  const stopLoss =
    firstFiniteNumber(
      record.sl,
      record.stop,
      record.stopLoss,
      record.stop_loss,
      tradePlan.sl,
      tradePlan.stop,
      tradePlan.stopLoss
    );

  const takeProfit =
    firstFiniteNumber(
      record.tp,
      record.target,
      record.target1,
      record.takeProfit,
      record.take_profit,
      tradePlan.tp,
      tradePlan.target,
      tradePlan.target1,
      tradePlan.takeProfit
    );

  let riskReward =
    firstFiniteNumber(
      record.rr,
      record.riskReward,
      record.risk_reward,
      tradePlan.rr,
      tradePlan.riskReward
    );

  if (
    riskReward == null &&
    entry != null &&
    stopLoss != null &&
    takeProfit != null
  ) {
    const risk =
      Math.abs(
        entry - stopLoss
      );

    const reward =
      Math.abs(
        takeProfit - entry
      );

    riskReward =
      risk > 0
        ? reward / risk
        : null;
  }

  const mode =
    normalizeScalpMode(
      firstString(
        record.mode,
        record.timeframe,
        record.tf,
        pairRecord.mode,
        pairRecord.timeframe,
        pairRecord.tf
      )
    );

  const updatedAt =
    normalizeTime(
      firstString(
        record.analyzedCandleAt,
        record.updatedAt,
        record.timestamp,
        record.time,
        record.generatedAt,

        pairRecord.analyzedCandleAt,
        pairRecord.updatedAt,
        pairRecord.timestamp,
        pairRecord.time,
        pairRecord.generatedAt,

        rawScalpSignals.updatedAt,
        rawScalpSignals.timestamp,
        rawScalpSignals.time,
        rawScalpSignals.generatedAt
      )
    );

  const reason =
    firstString(
      record.reason,
      record.explanation,
      record.suppressionReason,
      record.message
    );

  return {
    sourceRecord: {
      ...pairRecord,
      ...record,
    },

    mode,
    decision,

    entry:
      roundPrice(
        entry,
        decimals
      ),

    sl:
      roundPrice(
        stopLoss,
        decimals
      ),

    tp:
      roundPrice(
        takeProfit,
        decimals
      ),

    rr:
      riskReward == null
        ? null
        : Number(
            riskReward.toFixed(2)
          ),

    reason,
    updatedAt,
  };
}

function resolveDedicatedScalpSignal(
  rawScalpSignals,
  pairKey,
  decimals
) {
  if (
    !rawScalpSignals ||
    typeof rawScalpSignals !==
      "object"
  ) {
    return {
      valid: false,

      reason:
        "data/scalp-signals.json is missing or unreadable",

      signal: null,

      meta: {
        available: false,
        pairFound: false,
        valid: false,
        decision: null,
        updatedAt: null,
        stale: null,
        recordCount: 0,
        timeframeCount: 0,
      },
    };
  }

  const rawRecords =
    collectDedicatedScalpPairRecords(
      rawScalpSignals,
      pairKey
    );

  if (
    rawRecords.length === 0
  ) {
    const sourceUpdatedAt =
      normalizeTime(
        firstString(
          rawScalpSignals.updatedAt,
          rawScalpSignals.generatedAt,
          rawScalpSignals.timestamp,
          rawScalpSignals.time
        )
      );

    return {
      valid: false,

      reason:
        `No dedicated scalp record found for ${pairKey}`,

      signal: null,

      meta: {
        available: true,
        pairFound: false,
        valid: false,
        decision: null,

        updatedAt:
          sourceUpdatedAt,

        stale:
          sourceUpdatedAt
            ? (
                Date.now() -
                Date.parse(
                  sourceUpdatedAt
                )
              ) >
              DAY_MS
            : null,

        recordCount: 0,
        timeframeCount: 0,
      },
    };
  }

  const parsedRecords =
    rawRecords
      .map(
        record =>
          parseDedicatedScalpRecord(
            record,
            rawScalpSignals,
            decimals
          )
      )
      .filter(Boolean);

  if (
    parsedRecords.length === 0
  ) {
    return {
      valid: false,

      reason:
        `Dedicated scalp records for ${pairKey} contain no valid decisions`,

      signal: null,

      meta: {
        available: true,
        pairFound: true,
        valid: false,
        decision: null,
        updatedAt: null,
        stale: null,
        recordCount: 0,
        timeframeCount: 0,
      },
    };
  }

  const recordsByMode =
    new Map();

  for (
    const record of
    parsedRecords
  ) {
    if (record.mode) {
      recordsByMode.set(
        record.mode,
        record
      );
    }
  }

  const record5m =
    recordsByMode.get("M5") ||
    null;

  const record15m =
    recordsByMode.get("M15") ||
    null;

  const record30m =
    recordsByMode.get("M30") ||
    null;

  let decision = "HOLD";
  let selectedRecord = null;
  let reason = null;

  if (record15m) {
    selectedRecord =
      record15m;

    if (
      record15m.decision ===
      "HOLD"
    ) {
      reason =
        record15m.reason ||
        "15-min anchor timeframe is not aligned";
    } else {
      const confirmations =
        (
          record5m &&
          record5m.decision ===
            record15m.decision
            ? 1
            : 0
        ) +
        (
          record30m &&
          record30m.decision ===
            record15m.decision
            ? 1
            : 0
        );

      if (
        confirmations >= 1
      ) {
        decision =
          record15m.decision;

        reason =
          "Dedicated scalp timeframes confirmed the 15-min anchor";
      } else {
        reason =
          "5-min and 30-min do not confirm the 15-min anchor";
      }
    }
  } else if (
    parsedRecords.length === 1
  ) {
    selectedRecord =
      parsedRecords[0];

    decision =
      selectedRecord.decision;

    reason =
      selectedRecord.reason ||
      "Single dedicated scalp record used for backward compatibility";
  } else {
    const buyRecords =
      parsedRecords.filter(
        record =>
          record.decision ===
          "BUY"
      );

    const sellRecords =
      parsedRecords.filter(
        record =>
          record.decision ===
          "SELL"
      );

    if (
      buyRecords.length >= 2 &&
      buyRecords.length >
        sellRecords.length
    ) {
      decision = "BUY";

      selectedRecord =
        buyRecords[0];
    } else if (
      sellRecords.length >= 2 &&
      sellRecords.length >
        buyRecords.length
    ) {
      decision = "SELL";

      selectedRecord =
        sellRecords[0];
    } else {
      decision = "HOLD";

      selectedRecord =
        parsedRecords[0];
    }

    reason =
      decision === "HOLD"
        ? "Dedicated scalp timeframes are mixed"
        : "Dedicated scalp decision selected by timeframe majority";
  }

  if (!selectedRecord) {
    selectedRecord =
      parsedRecords[0];
  }

  const timestamps =
    parsedRecords
      .map(
        record =>
          record.updatedAt
      )
      .filter(Boolean)
      .sort(
        (a, b) =>
          Date.parse(a) -
          Date.parse(b)
      );

  const updatedAt =
    timestamps.length
      ? timestamps[
          timestamps.length - 1
        ]
      : normalizeTime(
          firstString(
            rawScalpSignals.updatedAt,
            rawScalpSignals.generatedAt,
            rawScalpSignals.timestamp,
            rawScalpSignals.time
          )
        );

  const perTF = [
    {
      tf: "5m",

      signal:
        record5m
          ? record5m.decision
          : "HOLD",
    },
    {
      tf: "15m",

      signal:
        record15m
          ? record15m.decision
          : "HOLD",
    },
    {
      tf: "30m",

      signal:
        record30m
          ? record30m.decision
          : "HOLD",
    },
  ];

  return {
    valid: true,
    reason: null,

    signal: {
      ...(
        selectedRecord
          .sourceRecord ||
        {}
      ),

      decision,
      signal:
        decision,

      confidence:
        decision === "HOLD"
          ? 0
          : firstFiniteNumber(
              selectedRecord
                .sourceRecord &&
                selectedRecord
                  .sourceRecord
                  .confidence,

              selectedRecord
                .sourceRecord &&
                selectedRecord
                  .sourceRecord
                  .confidencePct,

              0
            ),

      reason,
      perTF,

      tradePlan:
        decision === "HOLD"
          ? null
          : (
              selectedRecord
                .sourceRecord &&
              selectedRecord
                .sourceRecord
                .tradePlan
            ) ||
            null,

      entry:
        decision === "HOLD"
          ? null
          : selectedRecord.entry,

      sl:
        decision === "HOLD"
          ? null
          : selectedRecord.sl,

      tp:
        decision === "HOLD"
          ? null
          : selectedRecord.tp,

      rr:
        decision === "HOLD"
          ? null
          : selectedRecord.rr,

      source:
        "scalp-signals.json",

      sourceMode:
        "primary",

      updatedAt,
    },

    meta: {
      available: true,
      pairFound: true,
      valid: true,
      decision,
      updatedAt,

      stale:
        updatedAt
          ? (
              Date.now() -
              Date.parse(
                updatedAt
              )
            ) >
            DAY_MS
          : null,

      recordCount:
        parsedRecords.length,

      timeframeCount:
        recordsByMode.size,
    },
  };
}

// ========================================================
// Indicator Helpers
// ========================================================
function emaSeries(
  values,
  period
) {
  if (
    !Array.isArray(values) ||
    !Number.isInteger(period) ||
    period < 1
  ) {
    return [];
  }

  const output =
    new Array(
      values.length
    ).fill(null);

  if (
    values.length < period
  ) {
    return output;
  }

  const multiplier =
    2 / (period + 1);

  let previous =
    values
      .slice(0, period)
      .reduce(
        (sum, value) =>
          sum + value,
        0
      ) / period;

  output[
    period - 1
  ] = previous;

  for (
    let index = period;
    index < values.length;
    index += 1
  ) {
    previous =
      values[index] *
        multiplier +
      previous *
        (1 - multiplier);

    output[index] =
      previous;
  }

  return output;
}

function rsiSeries(
  values,
  period = 14
) {
  if (
    !Array.isArray(values)
  ) {
    return [];
  }

  const output =
    new Array(
      values.length
    ).fill(null);

  if (
    !Number.isInteger(period) ||
    period < 1 ||
    values.length <= period
  ) {
    return output;
  }

  let gainSum = 0;
  let lossSum = 0;

  for (
    let index = 1;
    index <= period;
    index += 1
  ) {
    const difference =
      values[index] -
      values[index - 1];

    if (
      difference >= 0
    ) {
      gainSum += difference;
    } else {
      lossSum -= difference;
    }
  }

  let averageGain =
    gainSum / period;

  let averageLoss =
    lossSum / period;

  output[period] =
    averageLoss === 0
      ? 100
      : 100 -
        100 /
          (
            1 +
            averageGain /
              averageLoss
          );

  for (
    let index =
      period + 1;
    index < values.length;
    index += 1
  ) {
    const difference =
      values[index] -
      values[index - 1];

    const gain =
      difference > 0
        ? difference
        : 0;

    const loss =
      difference < 0
        ? -difference
        : 0;

    averageGain =
      (
        averageGain *
          (period - 1) +
        gain
      ) / period;

    averageLoss =
      (
        averageLoss *
          (period - 1) +
        loss
      ) / period;

    output[index] =
      averageLoss === 0
        ? 100
        : 100 -
          100 /
            (
              1 +
              averageGain /
                averageLoss
            );
  }

  return output;
}

function computeVolatility(
  rows
) {
  if (
    !Array.isArray(rows) ||
    rows.length < 3
  ) {
    return 0.004;
  }

  let totalMove = 0;
  let count = 0;

  for (
    let index = 1;
    index < rows.length;
    index += 1
  ) {
    const previousClose =
      rows[index - 1]
        .close;

    const currentClose =
      rows[index].close;

    if (
      !isFiniteNumber(
        previousClose
      ) ||
      !isFiniteNumber(
        currentClose
      ) ||
      previousClose <= 0
    ) {
      continue;
    }

    totalMove +=
      Math.abs(
        currentClose -
          previousClose
      ) / previousClose;

    count += 1;
  }

  return count
    ? totalMove / count
    : 0.004;
}

function computeATR(
  ohlcRows,
  period = 14
) {
  if (
    !Array.isArray(
      ohlcRows
    ) ||
    !Number.isInteger(period) ||
    period < 1 ||
    ohlcRows.length <
      period + 1
  ) {
    return null;
  }

  const trueRanges = [];

  for (
    let index = 1;
    index <
      ohlcRows.length;
    index += 1
  ) {
    const current =
      ohlcRows[index];

    const previous =
      ohlcRows[
        index - 1
      ];

    trueRanges.push(
      Math.max(
        current.high -
          current.low,

        Math.abs(
          current.high -
            previous.close
        ),

        Math.abs(
          current.low -
            previous.close
        )
      )
    );
  }

  if (
    trueRanges.length <
    period
  ) {
    return null;
  }

  let atr =
    trueRanges
      .slice(0, period)
      .reduce(
        (sum, value) =>
          sum + value,
        0
      ) / period;

  for (
    let index = period;
    index <
      trueRanges.length;
    index += 1
  ) {
    atr =
      (
        atr *
          (period - 1) +
        trueRanges[index]
      ) / period;
  }

  return atr;
}

function computeADX(
  ohlcRows,
  period = 14
) {
  if (
    !Array.isArray(
      ohlcRows
    ) ||
    !Number.isInteger(period) ||
    period < 1 ||
    ohlcRows.length <
      period * 2 + 1
  ) {
    return null;
  }

  const trueRanges = [];
  const plusDM = [];
  const minusDM = [];

  for (
    let index = 1;
    index <
      ohlcRows.length;
    index += 1
  ) {
    const current =
      ohlcRows[index];

    const previous =
      ohlcRows[
        index - 1
      ];

    trueRanges.push(
      Math.max(
        current.high -
          current.low,

        Math.abs(
          current.high -
            previous.close
        ),

        Math.abs(
          current.low -
            previous.close
        )
      )
    );

    const upwardMove =
      current.high -
      previous.high;

    const downwardMove =
      previous.low -
      current.low;

    plusDM.push(
      upwardMove >
        downwardMove &&
      upwardMove > 0
        ? upwardMove
        : 0
    );

    minusDM.push(
      downwardMove >
        upwardMove &&
      downwardMove > 0
        ? downwardMove
        : 0
    );
  }

  let smoothedTR = 0;
  let smoothedPlusDM = 0;
  let smoothedMinusDM = 0;

  for (
    let index = 0;
    index < period;
    index += 1
  ) {
    smoothedTR +=
      trueRanges[index];

    smoothedPlusDM +=
      plusDM[index];

    smoothedMinusDM +=
      minusDM[index];
  }

  const dxSeries = [];

  for (
    let index = period;
    index <
      trueRanges.length;
    index += 1
  ) {
    smoothedTR =
      smoothedTR -
      smoothedTR /
        period +
      trueRanges[index];

    smoothedPlusDM =
      smoothedPlusDM -
      smoothedPlusDM /
        period +
      plusDM[index];

    smoothedMinusDM =
      smoothedMinusDM -
      smoothedMinusDM /
        period +
      minusDM[index];

    const plusDI =
      smoothedTR === 0
        ? 0
        : 100 *
          (
            smoothedPlusDM /
            smoothedTR
          );

    const minusDI =
      smoothedTR === 0
        ? 0
        : 100 *
          (
            smoothedMinusDM /
            smoothedTR
          );

    const denominator =
      plusDI + minusDI;

    const dx =
      denominator === 0
        ? 0
        : (
            100 *
            Math.abs(
              plusDI -
                minusDI
            )
          ) /
          denominator;

    dxSeries.push(dx);
  }

  if (
    dxSeries.length <
    period
  ) {
    return null;
  }

  let adx =
    dxSeries
      .slice(0, period)
      .reduce(
        (sum, value) =>
          sum + value,
        0
      ) / period;

  for (
    let index = period;
    index <
      dxSeries.length;
    index += 1
  ) {
    adx =
      (
        adx *
          (period - 1) +
        dxSeries[index]
      ) / period;
  }

  return adx;
}

function computeSR(
  rows,
  lastClose
) {
  if (
    !Array.isArray(rows) ||
    rows.length === 0 ||
    !isFiniteNumber(
      lastClose
    )
  ) {
    return {
      resistances: [],
      supports: [],
    };
  }

  const closes =
    rows
      .map(
        row =>
          row.close
      )
      .filter(
        isFiniteNumber
      );

  const count =
    closes.length;

  if (count === 0) {
    return {
      resistances: [],
      supports: [],
    };
  }

  const radius =
    count > 40
      ? 2
      : 1;

  const swingHighs = [];
  const swingLows = [];

  for (
    let index = radius;
    index <
      count - radius;
    index += 1
  ) {
    let isHigh = true;
    let isLow = true;

    for (
      let offset = 1;
      offset <= radius;
      offset += 1
    ) {
      if (
        closes[index] <
          closes[
            index - offset
          ] ||
        closes[index] <
          closes[
            index + offset
          ]
      ) {
        isHigh = false;
      }

      if (
        closes[index] >
          closes[
            index - offset
          ] ||
        closes[index] >
          closes[
            index + offset
          ]
      ) {
        isLow = false;
      }
    }

    if (isHigh) {
      swingHighs.push(
        closes[index]
      );
    }

    if (isLow) {
      swingLows.push(
        closes[index]
      );
    }
  }

  function dedupeLevels(
    levels
  ) {
    const sorted =
      [...levels].sort(
        (a, b) =>
          a - b
      );

    const output = [];

    for (
      const level of sorted
    ) {
      const previous =
        output[
          output.length - 1
        ];

      if (
        previous == null ||
        Math.abs(
          level - previous
        ) / level >
          0.0015
      ) {
        output.push(level);
      } else {
        output[
          output.length - 1
        ] =
          (
            previous +
            level
          ) / 2;
      }
    }

    return output;
  }

  let resistances =
    dedupeLevels(
      swingHighs
    )
      .filter(
        level =>
          level >
          lastClose
      )
      .sort(
        (a, b) =>
          a - b
      )
      .slice(0, 2);

  let supports =
    dedupeLevels(
      swingLows
    )
      .filter(
        level =>
          level <
          lastClose
      )
      .sort(
        (a, b) =>
          b - a
      )
      .slice(0, 2);

  if (
    resistances.length ===
      0 &&
    count >= 3
  ) {
    const maximumClose =
      Math.max(
        ...closes
      );

    if (
      maximumClose >
      lastClose *
        1.0005
    ) {
      resistances = [
        maximumClose,
      ];
    }
  }

  if (
    supports.length ===
      0 &&
    count >= 3
  ) {
    const minimumClose =
      Math.min(
        ...closes
      );

    if (
      minimumClose <
      lastClose *
        0.9995
    ) {
      supports = [
        minimumClose,
      ];
    }
  }

  return {
    resistances,
    supports,
  };
}

function detectCandlePattern(
  ohlcRows,
  leanDirection
) {
  if (
    !Array.isArray(
      ohlcRows
    ) ||
    ohlcRows.length < 2 ||
    !leanDirection
  ) {
    return {
      ok: false,

      detail:
        "Not enough candle history",
    };
  }

  const last =
    ohlcRows[
      ohlcRows.length - 1
    ];

  const previous =
    ohlcRows[
      ohlcRows.length - 2
    ];

  const range =
    last.high -
    last.low;

  const body =
    Math.abs(
      last.close -
      last.open
    );

  const bodyPercentage =
    range > 0
      ? body / range
      : 0;

  if (
    leanDirection ===
    "BUY"
  ) {
    const bullishEngulfing =
      previous.close <
        previous.open &&
      last.close >
        last.open &&
      last.open <=
        previous.close &&
      last.close >=
        previous.open;

    if (
      bullishEngulfing
    ) {
      return {
        ok: true,

        detail:
          "Bullish engulfing on the latest candle",
      };
    }

    if (
      last.close >
        last.open &&
      bodyPercentage > 0.6
    ) {
      return {
        ok: true,

        detail:
          `Strong bullish candle ` +
          `(body ${(
            bodyPercentage *
            100
          ).toFixed(
            0
          )}% of range)`,
      };
    }

    return {
      ok: false,

      detail:
        "Latest candle doesn't confirm a bullish pattern",
    };
  }

  const bearishEngulfing =
    previous.close >
      previous.open &&
    last.close <
      last.open &&
    last.open >=
      previous.close &&
    last.close <=
      previous.open;

  if (
    bearishEngulfing
  ) {
    return {
      ok: true,

      detail:
        "Bearish engulfing on the latest candle",
    };
  }

  if (
    last.close <
      last.open &&
    bodyPercentage > 0.6
  ) {
    return {
      ok: true,

      detail:
        `Strong bearish candle ` +
        `(body ${(
          bodyPercentage *
          100
        ).toFixed(
          0
        )}% of range)`,
    };
  }

  return {
    ok: false,

    detail:
      "Latest candle doesn't confirm a bearish pattern",
  };
}

// ========================================================
// Trend Helpers
// ========================================================
function adaptiveEmaPeriods(
  rowCount
) {
  if (
    !Number.isInteger(
      rowCount
    ) ||
    rowCount < 6
  ) {
    return null;
  }

  const cap =
    rowCount - 1;

  const p200 =
    Math.min(
      200,
      cap
    );

  const p100 =
    Math.min(
      100,
      Math.max(
        4,
        Math.floor(
          p200 * 0.5
        )
      )
    );

  const p50 =
    Math.min(
      50,
      Math.max(
        3,
        Math.floor(
          p100 * 0.6
        )
      )
    );

  const p20 =
    Math.min(
      20,
      Math.max(
        2,
        Math.floor(
          p50 * 0.5
        )
      )
    );

  return {
    p20,
    p50,
    p100,
    p200,

    fullStack:
      cap >= 200,
  };
}

function calculateTrendState(
  rows
) {
  if (
    !Array.isArray(rows) ||
    rows.length < 6
  ) {
    return {
      direction: null,

      label:
        "Building history — not enough sessions yet",

      values: null,
      periods: null,
    };
  }

  const closes =
    rows
      .map(
        row =>
          row.close
      )
      .filter(
        isFiniteNumber
      );

  if (
    closes.length < 6
  ) {
    return {
      direction: null,

      label:
        "Building history — valid close history is not ready",

      values: null,
      periods: null,
    };
  }

  const periods =
    adaptiveEmaPeriods(
      closes.length
    );

  if (!periods) {
    return {
      direction: null,

      label:
        "Building history — not enough sessions yet",

      values: null,
      periods: null,
    };
  }

  const {
    p20,
    p50,
    p100,
    p200,
    fullStack,
  } = periods;

  const ema20 =
    emaSeries(
      closes,
      p20
    );

  const ema50 =
    emaSeries(
      closes,
      p50
    );

  const ema100 =
    emaSeries(
      closes,
      p100
    );

  const ema200 =
    emaSeries(
      closes,
      p200
    );

  const lastIndex =
    closes.length - 1;

  const lastClose =
    closes[lastIndex];

  const values = {
    v20:
      ema20[lastIndex],

    v50:
      ema50[lastIndex],

    v100:
      ema100[lastIndex],

    v200:
      ema200[lastIndex],
  };

  const {
    v20,
    v50,
    v100,
    v200,
  } = values;

  if (
    v20 == null ||
    v50 == null ||
    v100 == null ||
    v200 == null
  ) {
    return {
      direction: null,

      label:
        "Building history — EMA values are not ready",

      values,
      periods,
    };
  }

  const bullishChecks = [
    v20 > v50,
    v50 > v100,
    v100 > v200,
    lastClose > v20,
  ];

  const bearishChecks = [
    v20 < v50,
    v50 < v100,
    v100 < v200,
    lastClose < v20,
  ];

  const bullishCount =
    bullishChecks
      .filter(Boolean)
      .length;

  const bearishCount =
    bearishChecks
      .filter(Boolean)
      .length;

  const note =
    fullStack
      ? ""
      : " (adaptive periods — full EMA200 needs more history)";

  if (
    bullishCount === 4
  ) {
    return {
      direction:
        "BUY",

      label:
        `Bullish — full EMA stack ` +
        `${p20}>${p50}>${p100}>${p200}` +
        note,

      values,
      periods,
    };
  }

  if (
    bearishCount === 4
  ) {
    return {
      direction:
        "SELL",

      label:
        `Bearish — full EMA stack ` +
        `${p20}<${p50}<${p100}<${p200}` +
        note,

      values,
      periods,
    };
  }

  if (
    bullishCount >= 3
  ) {
    return {
      direction: null,

      label:
        `Partial bullish lean only ` +
        `(${bullishCount}/4) — not enough to qualify` +
        note,

      values,
      periods,
    };
  }

  if (
    bearishCount >= 3
  ) {
    return {
      direction: null,

      label:
        `Partial bearish lean only ` +
        `(${bearishCount}/4) — not enough to qualify` +
        note,

      values,
      periods,
    };
  }

  return {
    direction: null,

    label:
      `Mixed EMA alignment — no clear trend` +
      note,

    values,
    periods,
  };
}

function trendDirectionOf(
  rows
) {
  return calculateTrendState(
    rows
  ).direction;
}

// ============================================================================
// PART 4 — CANDLE AGGREGATION + WEEKLY AGGREGATION
//          + LEGACY-COMPATIBLE ANALYSIS PIPELINE
// ============================================================================
//
// This section:
// - Normalizes mixed candle formats without changing upstream JSON files.
// - Aggregates lower-timeframe candles safely.
// - Builds UTC daily and Monday-based UTC weekly candles.
// - Preserves completed candles and optionally includes the active candle.
// - Provides indicator calculations required by the live analysis engines.
// - Produces a backward-compatible professional confluence result.
// - Keeps WAIT/NEUTRAL-style decisions normalized to HOLD.
// - Does not change Telegram, history, notification or output-writing logic.
//
// Expected integration:
// - Part 1: constants/configuration
// - Part 2: JSON safety, normalization and shared helpers
// - Part 3: input loading / signal-source preparation
// - Part 4: this section
// ============================================================================


// ---------------------------------------------------------------------------
// Candle field helpers
// ---------------------------------------------------------------------------
function candleNumber(
  value,
  fallback = null
) {
  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return fallback;
  }

  const parsed =
    Number(value);

  return Number.isFinite(parsed)
    ? parsed
    : fallback;
}

function candleInteger(
  value,
  fallback = null
) {
  const parsed =
    candleNumber(
      value,
      fallback
    );

  return Number.isFinite(parsed)
    ? Math.trunc(parsed)
    : fallback;
}

function firstDefinedValue(
  object,
  keys,
  fallback = undefined
) {
  if (
    !object ||
    typeof object !== "object"
  ) {
    return fallback;
  }

  for (const key of keys) {
    if (
      Object.prototype
        .hasOwnProperty.call(
          object,
          key
        ) &&
      object[key] !== null &&
      object[key] !== undefined &&
      object[key] !== ""
    ) {
      return object[key];
    }
  }

  return fallback;
}

function normalizeTimestampMs(
  value
) {
  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return null;
  }

  if (
    value instanceof Date
  ) {
    const time =
      value.getTime();

    return Number.isFinite(time)
      ? time
      : null;
  }

  if (
    typeof value === "number"
  ) {
    if (
      !Number.isFinite(value)
    ) {
      return null;
    }

    // Seconds timestamp.
    if (
      value > 0 &&
      value < 10_000_000_000
    ) {
      return Math.trunc(
        value * 1000
      );
    }

    // Microseconds timestamp.
    if (
      value >=
        10_000_000_000_000 &&
      value <
        10_000_000_000_000_000
    ) {
      return Math.trunc(
        value / 1000
      );
    }

    // Nanoseconds timestamp.
    if (
      value >=
      10_000_000_000_000_000
    ) {
      return Math.trunc(
        value / 1_000_000
      );
    }

    return Math.trunc(value);
  }

  const raw =
    String(value).trim();

  if (!raw) {
    return null;
  }

  if (
    /^-?\d+(\.\d+)?$/.test(
      raw
    )
  ) {
    return normalizeTimestampMs(
      Number(raw)
    );
  }

  const parsed =
    Date.parse(raw);

  return Number.isFinite(parsed)
    ? parsed
    : null;
}

function extractCandleTimestampMs(
  rawCandle
) {
  if (
    !rawCandle ||
    typeof rawCandle !== "object"
  ) {
    return null;
  }

  return normalizeTimestampMs(
    firstDefinedValue(
      rawCandle,
      [
        "timestamp",
        "timestampMs",
        "time",
        "datetime",
        "dateTime",
        "date",
        "openTime",
        "open_time",
        "startTime",
        "start_time",
        "t",
        "x",
      ]
    )
  );
}

function extractCandleCloseTimestampMs(
  rawCandle
) {
  if (
    !rawCandle ||
    typeof rawCandle !== "object"
  ) {
    return null;
  }

  return normalizeTimestampMs(
    firstDefinedValue(
      rawCandle,
      [
        "closeTimestamp",
        "closeTimestampMs",
        "closeTime",
        "close_time",
        "endTime",
        "end_time",
        "closedAt",
      ]
    )
  );
}

function normalizeBooleanValue(
  value,
  fallback = null
) {
  if (
    typeof value === "boolean"
  ) {
    return value;
  }

  if (
    typeof value === "number"
  ) {
    if (value === 1) {
      return true;
    }

    if (value === 0) {
      return false;
    }
  }

  if (
    typeof value === "string"
  ) {
    const normalized =
      value
        .trim()
        .toLowerCase();

    if (
      normalized === "true" ||
      normalized === "yes" ||
      normalized === "closed" ||
      normalized === "complete" ||
      normalized === "completed" ||
      normalized === "final"
    ) {
      return true;
    }

    if (
      normalized === "false" ||
      normalized === "no" ||
      normalized === "open" ||
      normalized === "active" ||
      normalized === "forming" ||
      normalized === "incomplete"
    ) {
      return false;
    }
  }

  return fallback;
}


// ---------------------------------------------------------------------------
// Canonical candle normalization
// ---------------------------------------------------------------------------

function normalizeLiveCandle(
  rawCandle,
  options = {}
) {
  if (
    !rawCandle ||
    typeof rawCandle !== "object"
  ) {
    return null;
  }

  const timestamp =
    extractCandleTimestampMs(
      rawCandle
    );

  if (
    !Number.isFinite(timestamp) ||
    timestamp <= 0
  ) {
    return null;
  }

  const rawOpen =
    firstDefinedValue(
      rawCandle,
      [
        "open",
        "Open",
        "o",
        "priceOpen",
        "openPrice",
      ]
    );

  const rawHigh =
    firstDefinedValue(
      rawCandle,
      [
        "high",
        "High",
        "h",
        "priceHigh",
        "highPrice",
      ]
    );

  const rawLow =
    firstDefinedValue(
      rawCandle,
      [
        "low",
        "Low",
        "l",
        "priceLow",
        "lowPrice",
      ]
    );

  const rawClose =
    firstDefinedValue(
      rawCandle,
      [
        "close",
        "Close",
        "c",
        "price",
        "last",
        "value",
        "priceClose",
        "closePrice",
      ]
    );

  let open =
    candleNumber(rawOpen);

  let high =
    candleNumber(rawHigh);

  let low =
    candleNumber(rawLow);

  let close =
    candleNumber(rawClose);

  // Legacy close-only rows remain supported.
  if (
    !Number.isFinite(close)
  ) {
    close =
      candleNumber(
        firstDefinedValue(
          rawCandle,
          [
            "mid",
            "bid",
            "ask",
          ]
        )
      );
  }

  if (
    !Number.isFinite(close) ||
    close <= 0
  ) {
    return null;
  }

  if (
    !Number.isFinite(open)
  ) {
    open = close;
  }

  if (
    !Number.isFinite(high)
  ) {
    high =
      Math.max(
        open,
        close
      );
  }

  if (
    !Number.isFinite(low)
  ) {
    low =
      Math.min(
        open,
        close
      );
  }

  /*
   * Repair malformed provider values without rejecting otherwise
   * usable data.
   */
  high =
    Math.max(
      high,
      open,
      close
    );

  low =
    Math.min(
      low,
      open,
      close
    );

  if (
    !Number.isFinite(open) ||
    !Number.isFinite(high) ||
    !Number.isFinite(low) ||
    !Number.isFinite(close) ||
    open <= 0 ||
    high <= 0 ||
    low <= 0 ||
    close <= 0 ||
    high < low
  ) {
    return null;
  }

  const volume =
    Math.max(
      0,
      candleNumber(
        firstDefinedValue(
          rawCandle,
          [
            "volume",
            "Volume",
            "v",
            "tickVolume",
            "tick_volume",
            "realVolume",
            "real_volume",
          ]
        ),
        0
      )
    );

  const closeTimestamp =
    extractCandleCloseTimestampMs(
      rawCandle
    ) ??
    candleNumber(
      options.defaultCloseTimestamp,
      null
    );

  const explicitClosed =
    normalizeBooleanValue(
      firstDefinedValue(
        rawCandle,
        [
          "closed",
          "isClosed",
          "is_closed",
          "complete",
          "completed",
          "isComplete",
          "is_complete",
          "final",
          "isFinal",
        ]
      ),
      null
    );

  const source =
    firstDefinedValue(
      rawCandle,
      [
        "source",
        "provider",
        "feed",
      ],
      options.source ||
        null
    );

  const normalized = {
    timestamp,

    time:
      new Date(
        timestamp
      ).toISOString(),

    open,
    high,
    low,
    close,
    volume,
  };

  if (
    Number.isFinite(
      closeTimestamp
    )
  ) {
    normalized.closeTimestamp =
      closeTimestamp;

    normalized.closeTime =
      new Date(
        closeTimestamp
      ).toISOString();
  }

  if (
    explicitClosed !== null
  ) {
    normalized.closed =
      explicitClosed;
  }

  if (source) {
    normalized.source =
      String(source);
  }

  return normalized;
}

function normalizeLiveCandleArray(
  rawRows,
  options = {}
) {
  const sourceRows =
    Array.isArray(rawRows)
      ? rawRows
      : [];

  const byTimestamp =
    new Map();

  for (
    const rawRow of sourceRows
  ) {
    const candle =
      normalizeLiveCandle(
        rawRow,
        options
      );

    if (!candle) {
      continue;
    }

    /*
     * Latest duplicate wins. This preserves provider corrections to a
     * candle.
     */
    byTimestamp.set(
      candle.timestamp,
      candle
    );
  }

  const rows =
    [
      ...byTimestamp.values(),
    ].sort(
      (left, right) =>
        left.timestamp -
        right.timestamp
    );

  const maxRows =
    Math.max(
      0,
      candleInteger(
        options.maxRows,
        0
      ) || 0
    );

  if (
    maxRows > 0 &&
    rows.length > maxRows
  ) {
    return rows.slice(
      -maxRows
    );
  }

  return rows;
}


// ---------------------------------------------------------------------------
// Timeframe parsing and bucket calculation
// ---------------------------------------------------------------------------

const LIVE_TIMEFRAME_MS =
  Object.freeze({
    M1:
      60 * 1000,

    M2:
      2 * 60 * 1000,

    M3:
      3 * 60 * 1000,

    M5:
      5 * 60 * 1000,

    M10:
      10 * 60 * 1000,

    M15:
      15 * 60 * 1000,

    M20:
      20 * 60 * 1000,

    M30:
      30 * 60 * 1000,

    M45:
      45 * 60 * 1000,

    H1:
      60 * 60 * 1000,

    H2:
      2 * 60 * 60 * 1000,

    H3:
      3 * 60 * 60 * 1000,

    H4:
      4 * 60 * 60 * 1000,

    H6:
      6 * 60 * 60 * 1000,

    H8:
      8 * 60 * 60 * 1000,

    H12:
      12 * 60 * 60 * 1000,

    D1:
      24 * 60 * 60 * 1000,

    W1:
      7 * 24 * 60 * 60 * 1000,
  });

function normalizeLiveTimeframe(
  value,
  fallback = "H1"
) {
  const raw =
    String(
      value ||
      fallback
    )
      .trim()
      .toUpperCase()
      .replace(
        /\s+/g,
        ""
      );

  const aliases = {
    "1M": "M1",
    "2M": "M2",
    "3M": "M3",
    "5M": "M5",
    "10M": "M10",
    "15M": "M15",
    "20M": "M20",
    "30M": "M30",
    "45M": "M45",

    "1H": "H1",
    "2H": "H2",
    "3H": "H3",
    "4H": "H4",
    "6H": "H6",
    "8H": "H8",
    "12H": "H12",

    "1D": "D1",
    DAY: "D1",
    DAILY: "D1",

    "1W": "W1",
    WEEK: "W1",
    WEEKLY: "W1",
  };

  const normalized =
    aliases[raw] ||
    raw;

  if (
    Object.prototype
      .hasOwnProperty.call(
        LIVE_TIMEFRAME_MS,
        normalized
      )
  ) {
    return normalized;
  }

  return fallback;
}

function liveTimeframeMs(
  value,
  fallback = "H1"
) {
  const timeframe =
    normalizeLiveTimeframe(
      value,
      fallback
    );

  return (
    LIVE_TIMEFRAME_MS[
      timeframe
    ] ||
    LIVE_TIMEFRAME_MS[
      fallback
    ]
  );
}

function utcDayBucketStart(
  timestamp
) {
  const date =
    new Date(timestamp);

  return Date.UTC(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate()
  );
}

function utcWeekBucketStart(
  timestamp
) {
  const date =
    new Date(timestamp);

  const dayStart =
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate()
    );

  /*
   * JavaScript UTC day:
   * Sunday = 0 ... Saturday = 6.
   *
   * Convert to ISO-style:
   * Monday = 0 ... Sunday = 6.
   */
  const mondayOffsetDays =
    (
      date.getUTCDay() +
      6
    ) % 7;

  return (
    dayStart -
    mondayOffsetDays *
      LIVE_TIMEFRAME_MS.D1
  );
}

function liveBucketStart(
  timestamp,
  timeframe
) {
  const normalizedTimeframe =
    normalizeLiveTimeframe(
      timeframe
    );

  if (
    normalizedTimeframe ===
    "D1"
  ) {
    return utcDayBucketStart(
      timestamp
    );
  }

  if (
    normalizedTimeframe ===
    "W1"
  ) {
    return utcWeekBucketStart(
      timestamp
    );
  }

  const intervalMs =
    liveTimeframeMs(
      normalizedTimeframe
    );

  return (
    Math.floor(
      timestamp /
      intervalMs
    ) *
    intervalMs
  );
}


// ---------------------------------------------------------------------------
// Generic OHLC aggregation
// ---------------------------------------------------------------------------

function aggregateLiveCandles(
  rawRows,
  timeframe,
  options = {}
) {
  const normalizedTimeframe =
    normalizeLiveTimeframe(
      timeframe
    );
  const intervalMs =
    liveTimeframeMs(
      normalizedTimeframe
    );
  const nowMs =
    candleNumber(
      options.nowMs,
      Date.now()
    );
  const includeActive =
    options.includeActive !== false;
  const rows =
    normalizeLiveCandleArray(
      rawRows,
      {
        source:
          options.source,
      }
    );

  if (rows.length === 0) {
    return [];
  }

  const sourceIntervalMs =
    candleNumber(
      options.sourceIntervalMs,
      professionalLiveInferSourceIntervalMs(
        rows
      )
    );
  const buckets =
    new Map();

  for (const row of rows) {
    const bucketTimestamp =
      liveBucketStart(
        row.timestamp,
        normalizedTimeframe
      );
    let bucket =
      buckets.get(
        bucketTimestamp
      );

    if (!bucket) {
      bucket = {
        timestamp:
          bucketTimestamp,
        time:
          new Date(
            bucketTimestamp
          ).toISOString(),
        open:
          row.open,
        high:
          row.high,
        low:
          row.low,
        close:
          row.close,
        volume:
          row.volume || 0,
        sourceCount: 0,
        sourceTimestamps: [],
        explicitOpenSourceCount: 0,
      };

      buckets.set(
        bucketTimestamp,
        bucket
      );
    }

    bucket.high =
      Math.max(
        bucket.high,
        row.high
      );
    bucket.low =
      Math.min(
        bucket.low,
        row.low
      );
    bucket.close =
      row.close;
    bucket.volume +=
      row.volume || 0;
    bucket.sourceCount += 1;
    bucket.sourceTimestamps.push(
      row.timestamp
    );

    if (row.closed === false) {
      bucket.explicitOpenSourceCount += 1;
    }
  }

  let aggregated =
    [...buckets.values()]
      .sort(
        (left, right) =>
          left.timestamp -
          right.timestamp
      )
      .map(
        bucket => {
          const closeTimestamp =
            bucket.timestamp +
            intervalMs;
          const closedByTime =
            closeTimestamp <=
            nowMs;
          const sortedTimestamps =
            [...bucket.sourceTimestamps]
              .sort(
                (left, right) =>
                  left - right
              );
          let continuous = true;

          if (
            Number.isFinite(
              sourceIntervalMs
            ) &&
            sourceIntervalMs > 0
          ) {
            for (
              let index = 1;
              index <
                sortedTimestamps.length;
              index += 1
            ) {
              if (
                sortedTimestamps[index] -
                sortedTimestamps[index - 1] !==
                sourceIntervalMs
              ) {
                continuous = false;
                break;
              }
            }
          }

          let expectedSourceCount = 1;
          let complete = true;
          let completenessReason =
            "Source interval matches target timeframe";

          if (
            Number.isFinite(
              sourceIntervalMs
            ) &&
            sourceIntervalMs > 0 &&
            sourceIntervalMs <
              intervalMs
          ) {
            if (
              normalizedTimeframe ===
                "W1" &&
              sourceIntervalMs ===
                LIVE_TIMEFRAME_MS.D1
            ) {
              expectedSourceCount = 5;
              complete =
                bucket.sourceCount >= 4;
              completenessReason =
                complete
                  ? "Completed trading week contains at least four closed daily candles"
                  : "Weekly bucket does not contain enough closed trading days";
            } else {
              const exactRatio =
                intervalMs /
                sourceIntervalMs;
              expectedSourceCount =
                Number.isInteger(
                  exactRatio
                )
                  ? exactRatio
                  : 0;
              const exactStart =
                sortedTimestamps[0] ===
                bucket.timestamp;
              const exactEnd =
                sortedTimestamps[
                  sortedTimestamps.length - 1
                ] +
                sourceIntervalMs ===
                closeTimestamp;

              complete =
                expectedSourceCount > 0 &&
                bucket.sourceCount ===
                  expectedSourceCount &&
                exactStart &&
                exactEnd &&
                continuous;
              completenessReason =
                complete
                  ? `Complete ${normalizedTimeframe} bucket from ${expectedSourceCount} continuous source candles`
                  : `Incomplete ${normalizedTimeframe} bucket: ${bucket.sourceCount}/${expectedSourceCount || "unknown"} source candles`;
            }
          }

          const closed =
            closedByTime &&
            bucket.explicitOpenSourceCount ===
              0 &&
            complete;

          return {
            timestamp:
              bucket.timestamp,
            time:
              bucket.time,
            open:
              bucket.open,
            high:
              bucket.high,
            low:
              bucket.low,
            close:
              bucket.close,
            volume:
              bucket.volume,
            closeTimestamp,
            closeTime:
              new Date(
                closeTimestamp
              ).toISOString(),
            closed,
            complete,
            timeframe:
              normalizedTimeframe,
            sourceCount:
              bucket.sourceCount,
            expectedSourceCount,
            sourceIntervalMs:
              Number.isFinite(
                sourceIntervalMs
              )
                ? sourceIntervalMs
                : null,
            firstSourceTimestamp:
              sortedTimestamps[0] ||
              null,
            lastSourceTimestamp:
              sortedTimestamps[
                sortedTimestamps.length - 1
              ] || null,
            continuous,
            completenessReason,
          };
        }
      );

  if (!includeActive) {
    aggregated =
      aggregated.filter(
        row =>
          row.closed === true &&
          row.complete === true
      );
  }

  const maxRows =
    Math.max(
      0,
      candleInteger(
        options.maxRows,
        0
      ) || 0
    );

  if (
    maxRows > 0 &&
    aggregated.length >
      maxRows
  ) {
    aggregated =
      aggregated.slice(-maxRows);
  }

  return aggregated;
}

function aggregateDailyCandles(
  rawRows,
  options = {}
) {
  return aggregateLiveCandles(
    rawRows,
    "D1",
    options
  );
}

function aggregateWeeklyCandles(
  rawRows,
  options = {}
) {
  return aggregateLiveCandles(
    rawRows,
    "W1",
    options
  );
}


// ---------------------------------------------------------------------------
// Weekly aggregation preserving legacy-compatible date fields
// ---------------------------------------------------------------------------

function buildLegacyWeeklyCandles(
  rawDailyRows,
  options = {}
) {
  const weeklyRows =
    aggregateWeeklyCandles(
      rawDailyRows,
      {
        ...options,

        includeActive:
          options.includeActive !==
          false,
      }
    );

  return weeklyRows.map(
    row => {
      const isoDate =
        row.time.slice(
          0,
          10
        );

      return {
        timestamp:
          row.timestamp,

        time:
          row.time,

        date:
          isoDate,

        open:
          row.open,

        high:
          row.high,

        low:
          row.low,

        close:
          row.close,

        volume:
          row.volume,

        closeTimestamp:
          row.closeTimestamp,

        closeTime:
          row.closeTime,

        closed:
          row.closed,

        timeframe:
          "W1",

        sourceCount:
          row.sourceCount,
      };
    }
  );
}


// ---------------------------------------------------------------------------
// Candle-frame preparation
// ---------------------------------------------------------------------------

function prepareLiveAnalysisFrames(
  input = {}
) {
  const nowMs =
    candleNumber(
      input.nowMs,
      Date.now()
    );
  const directScalp =
    professionalLiveClosedRows(
      input.scalpCandles ||
      input.scalpRows ||
      [],
      input.scalpTimeframe ||
      "M5",
      nowMs
    );
  const directIntraday =
    professionalLiveClosedRows(
      input.intradayCandles ||
      input.intradayRows ||
      input.h1Candles ||
      input.h1Rows ||
      [],
      "H1",
      nowMs
    );
  const directDaily =
    professionalLiveClosedRows(
      input.dailyCandles ||
      input.dailyRows ||
      input.dailyOhlc ||
      [],
      "D1",
      nowMs
    );
  const scalpRows =
    directScalp.rows.slice(
      -(
        input.maxScalpRows ||
        5000
      )
    );
  const suppliedIntradayRows =
    directIntraday.rows.slice(
      -(
        input.maxIntradayRows ||
        3000
      )
    );
  const suppliedDailyRows =
    directDaily.rows.slice(
      -(
        input.maxDailyRows ||
        1500
      )
    );
  const derivedH1Rows =
    suppliedIntradayRows.length > 0
      ? suppliedIntradayRows
      : aggregateLiveCandles(
          scalpRows,
          "H1",
          {
            includeActive: false,
            nowMs,
            maxRows:
              input.maxIntradayRows ||
              3000,
            source:
              "scalp-derived-h1",
            sourceIntervalMs:
              LIVE_TIMEFRAME_MS.M5,
          }
        );
  const derivedDailyRows =
    suppliedDailyRows.length > 0
      ? suppliedDailyRows
      : aggregateDailyCandles(
          derivedH1Rows,
          {
            includeActive: false,
            nowMs,
            maxRows:
              input.maxDailyRows ||
              1500,
            source:
              "h1-derived-d1",
            sourceIntervalMs:
              LIVE_TIMEFRAME_MS.H1,
          }
        );
  const weeklyRows =
    buildLegacyWeeklyCandles(
      derivedDailyRows,
      {
        includeActive: false,
        nowMs,
        maxRows:
          input.maxWeeklyRows ||
          500,
        source:
          "daily-derived-w1",
        sourceIntervalMs:
          LIVE_TIMEFRAME_MS.D1,
      }
    );

  return {
    scalp:
      scalpRows,
    intraday:
      derivedH1Rows,
    daily:
      derivedDailyRows,
    weekly:
      weeklyRows,
    metadata: {
      professionalPipelineVersion:
        PROFESSIONAL_LIVE_PIPELINE_VERSION,
      scalpCount:
        scalpRows.length,
      intradayCount:
        derivedH1Rows.length,
      dailyCount:
        derivedDailyRows.length,
      weeklyCount:
        weeklyRows.length,
      intradayDerived:
        suppliedIntradayRows.length === 0 &&
        scalpRows.length > 0,
      dailyDerived:
        suppliedDailyRows.length === 0 &&
        derivedH1Rows.length > 0,
      weeklyDerived:
        derivedDailyRows.length > 0,
      closedCandleDiagnostics: {
        scalp:
          directScalp.diagnostics,
        intraday:
          directIntraday.diagnostics,
        daily:
          directDaily.diagnostics,
      },
      scalpLatestClosedAt:
        p6AutonomousLatestClosedAt(
          scalpRows,
          "5m",
          nowMs
        ),
      intradayLatestClosedAt:
        p6AutonomousLatestClosedAt(
          derivedH1Rows,
          "1H",
          nowMs
        ),
      dailyLatestClosedAt:
        p6AutonomousLatestClosedAt(
          derivedDailyRows,
          "D1",
          nowMs
        ),
      weeklyLatestClosedAt:
        p6AutonomousLatestClosedAt(
          weeklyRows,
          "W1",
          nowMs
        ),
    },
  };
}


// ---------------------------------------------------------------------------
// Indicator helpers
// ---------------------------------------------------------------------------
function liveCloseValues(
  rows
) {
  return (
    Array.isArray(rows)
      ? rows
      : []
  )
    .map(
      row =>
        candleNumber(
          row &&
          row.close
        )
    )
    .filter(
      value =>
        Number.isFinite(
          value
        )
    );
}

function liveLastFinite(
  values
) {
  if (
    !Array.isArray(values)
  ) {
    return null;
  }

  for (
    let index =
      values.length - 1;

    index >= 0;

    index -= 1
  ) {
    if (
      Number.isFinite(
        values[index]
      )
    ) {
      return values[index];
    }
  }

  return null;
}

function liveSma(
  values,
  period
) {
  const source =
    Array.isArray(values)
      ? values
      : [];

  const safePeriod =
    Math.max(
      1,
      candleInteger(
        period,
        1
      )
    );

  const output =
    Array(
      source.length
    ).fill(null);

  if (
    source.length <
    safePeriod
  ) {
    return output;
  }

  let rollingSum = 0;
  let finiteCount = 0;

  for (
    let index = 0;

    index <
      source.length;

    index += 1
  ) {
    const value =
      source[index];

    if (
      Number.isFinite(value)
    ) {
      rollingSum += value;
      finiteCount += 1;
    }

    if (
      index >=
      safePeriod
    ) {
      const removed =
        source[
          index -
          safePeriod
        ];

      if (
        Number.isFinite(
          removed
        )
      ) {
        rollingSum -=
          removed;

        finiteCount -= 1;
      }
    }

    if (
      index >=
        safePeriod - 1 &&
      finiteCount ===
        safePeriod
    ) {
      output[index] =
        rollingSum /
        safePeriod;
    }
  }

  return output;
}

function liveEma(
  values,
  period
) {
  const source =
    Array.isArray(values)
      ? values
      : [];

  const safePeriod =
    Math.max(
      1,
      candleInteger(
        period,
        1
      )
    );

  const output =
    Array(
      source.length
    ).fill(null);

  if (
    source.length <
    safePeriod
  ) {
    return output;
  }

  let seedSum = 0;

  for (
    let index = 0;

    index <
      safePeriod;

    index += 1
  ) {
    if (
      !Number.isFinite(
        source[index]
      )
    ) {
      return output;
    }

    seedSum +=
      source[index];
  }

  const multiplier =
    2 /
    (
      safePeriod +
      1
    );

  let previous =
    seedSum /
    safePeriod;

  output[
    safePeriod - 1
  ] = previous;

  for (
    let index =
      safePeriod;

    index <
      source.length;

    index += 1
  ) {
    const value =
      source[index];

    if (
      !Number.isFinite(value)
    ) {
      output[index] =
        previous;

      continue;
    }

    previous =
      (
        value -
        previous
      ) *
        multiplier +
      previous;

    output[index] =
      previous;
  }

  return output;
}

function liveRsi(
  values,
  period = 14
) {
  const source =
    Array.isArray(values)
      ? values
      : [];

  const safePeriod =
    Math.max(
      2,
      candleInteger(
        period,
        14
      )
    );

  const output =
    Array(
      source.length
    ).fill(null);

  if (
    source.length <=
    safePeriod
  ) {
    return output;
  }

  let gainSum = 0;
  let lossSum = 0;

  for (
    let index = 1;

    index <=
      safePeriod;

    index += 1
  ) {
    const current =
      source[index];

    const previous =
      source[
        index - 1
      ];

    if (
      !Number.isFinite(
        current
      ) ||
      !Number.isFinite(
        previous
      )
    ) {
      return output;
    }

    const change =
      current -
      previous;

    if (
      change > 0
    ) {
      gainSum += change;
    } else {
      lossSum +=
        Math.abs(change);
    }
  }

  let averageGain =
    gainSum /
    safePeriod;

  let averageLoss =
    lossSum /
    safePeriod;

  if (
    averageLoss === 0
  ) {
    output[
      safePeriod
    ] =
      averageGain === 0
        ? 50
        : 100;
  } else {
    const relativeStrength =
      averageGain /
      averageLoss;

    output[
      safePeriod
    ] =
      100 -
      100 /
        (
          1 +
          relativeStrength
        );
  }

  for (
    let index =
      safePeriod + 1;

    index <
      source.length;

    index += 1
  ) {
    const current =
      source[index];

    const previous =
      source[
        index - 1
      ];

    if (
      !Number.isFinite(
        current
      ) ||
      !Number.isFinite(
        previous
      )
    ) {
      output[index] =
        output[
          index - 1
        ];

      continue;
    }

    const change =
      current -
      previous;

    const gain =
      change > 0
        ? change
        : 0;

    const loss =
      change < 0
        ? Math.abs(
            change
          )
        : 0;

    averageGain =
      (
        averageGain *
          (
            safePeriod -
            1
          ) +
        gain
      ) /
      safePeriod;

    averageLoss =
      (
        averageLoss *
          (
            safePeriod -
            1
          ) +
        loss
      ) /
      safePeriod;

    if (
      averageLoss === 0
    ) {
      output[index] =
        averageGain === 0
          ? 50
          : 100;
    } else {
      const relativeStrength =
        averageGain /
        averageLoss;

      output[index] =
        100 -
        100 /
          (
            1 +
            relativeStrength
          );
    }
  }

  return output;
}

function liveTrueRangeSeries(
  rows
) {
  const sourceRows =
    Array.isArray(rows)
      ? rows
      : [];

  const output =
    Array(
      sourceRows.length
    ).fill(null);

  for (
    let index = 0;

    index <
      sourceRows.length;

    index += 1
  ) {
    const row =
      sourceRows[index];

    const high =
      candleNumber(
        row &&
        row.high
      );

    const low =
      candleNumber(
        row &&
        row.low
      );

    if (
      !Number.isFinite(high) ||
      !Number.isFinite(low)
    ) {
      continue;
    }

    if (
      index === 0
    ) {
      output[index] =
        high - low;

      continue;
    }

    const previousClose =
      candleNumber(
        sourceRows[
          index - 1
        ] &&
        sourceRows[
          index - 1
        ].close
      );

    if (
      !Number.isFinite(
        previousClose
      )
    ) {
      output[index] =
        high - low;

      continue;
    }

    output[index] =
      Math.max(
        high - low,

        Math.abs(
          high -
          previousClose
        ),

        Math.abs(
          low -
          previousClose
        )
      );
  }

  return output;
}

function liveAtr(
  rows,
  period = 14
) {
  const trueRanges =
    liveTrueRangeSeries(
      rows
    );

  const safePeriod =
    Math.max(
      2,
      candleInteger(
        period,
        14
      )
    );

  const output =
    Array(
      trueRanges.length
    ).fill(null);

  if (
    trueRanges.length <
    safePeriod
  ) {
    return output;
  }

  let seedSum = 0;

  for (
    let index = 0;

    index <
      safePeriod;

    index += 1
  ) {
    if (
      !Number.isFinite(
        trueRanges[index]
      )
    ) {
      return output;
    }

    seedSum +=
      trueRanges[index];
  }

  let previousAtr =
    seedSum /
    safePeriod;

  output[
    safePeriod - 1
  ] = previousAtr;

  for (
    let index =
      safePeriod;

    index <
      trueRanges.length;

    index += 1
  ) {
    const currentTrueRange =
      trueRanges[index];

    if (
      !Number.isFinite(
        currentTrueRange
      )
    ) {
      output[index] =
        previousAtr;

      continue;
    }

    previousAtr =
      (
        previousAtr *
          (
            safePeriod -
            1
          ) +
        currentTrueRange
      ) /
      safePeriod;

    output[index] =
      previousAtr;
  }

  return output;
}

function liveMacd(
  values,
  fastPeriod = 12,
  slowPeriod = 26,
  signalPeriod = 9
) {
  const source =
    Array.isArray(values)
      ? values
      : [];

  const fast =
    liveEma(
      source,
      fastPeriod
    );

  const slow =
    liveEma(
      source,
      slowPeriod
    );

  const macdLine =
    source.map(
      (
        _,
        index
      ) => {
        if (
          !Number.isFinite(
            fast[index]
          ) ||
          !Number.isFinite(
            slow[index]
          )
        ) {
          return null;
        }

        return (
          fast[index] -
          slow[index]
        );
      }
    );

  const compactMacdValues =
    [];

  const compactIndexes =
    [];

  for (
    let index = 0;

    index <
      macdLine.length;

    index += 1
  ) {
    if (
      Number.isFinite(
        macdLine[index]
      )
    ) {
      compactMacdValues.push(
        macdLine[index]
      );

      compactIndexes.push(
        index
      );
    }
  }

  const compactSignal =
    liveEma(
      compactMacdValues,
      signalPeriod
    );

  const signalLine =
    Array(
      source.length
    ).fill(null);

  for (
    let index = 0;

    index <
      compactIndexes.length;

    index += 1
  ) {
    signalLine[
      compactIndexes[index]
    ] =
      compactSignal[index];
  }

  const histogram =
    source.map(
      (
        _,
        index
      ) => {
        if (
          !Number.isFinite(
            macdLine[index]
          ) ||
          !Number.isFinite(
            signalLine[index]
          )
        ) {
          return null;
        }

        return (
          macdLine[index] -
          signalLine[index]
        );
      }
    );

  return {
    macdLine,
    signalLine,
    histogram,
  };
}


// ---------------------------------------------------------------------------
// Market structure and support/resistance
// ---------------------------------------------------------------------------
function liveSwingPoints(
  rows,
  radius = 2
) {
  const sourceRows =
    Array.isArray(rows)
      ? rows
      : [];

  const safeRadius =
    Math.max(
      1,
      candleInteger(
        radius,
        2
      )
    );

  const highs = [];
  const lows = [];

  for (
    let index =
      safeRadius;

    index <
      sourceRows.length -
      safeRadius;

    index += 1
  ) {
    const candidateHigh =
      candleNumber(
        sourceRows[index].high
      );

    const candidateLow =
      candleNumber(
        sourceRows[index].low
      );

    if (
      !Number.isFinite(
        candidateHigh
      ) ||
      !Number.isFinite(
        candidateLow
      )
    ) {
      continue;
    }

    let isSwingHigh = true;
    let isSwingLow = true;

    for (
      let offset = 1;

      offset <=
        safeRadius;

      offset += 1
    ) {
      const previousHigh =
        candleNumber(
          sourceRows[
            index - offset
          ].high
        );

      const nextHigh =
        candleNumber(
          sourceRows[
            index + offset
          ].high
        );

      const previousLow =
        candleNumber(
          sourceRows[
            index - offset
          ].low
        );

      const nextLow =
        candleNumber(
          sourceRows[
            index + offset
          ].low
        );

      if (
        !Number.isFinite(
          previousHigh
        ) ||
        !Number.isFinite(
          nextHigh
        ) ||
        candidateHigh <=
          previousHigh ||
        candidateHigh <
          nextHigh
      ) {
        isSwingHigh = false;
      }

      if (
        !Number.isFinite(
          previousLow
        ) ||
        !Number.isFinite(
          nextLow
        ) ||
        candidateLow >=
          previousLow ||
        candidateLow >
          nextLow
      ) {
        isSwingLow = false;
      }
    }

    if (isSwingHigh) {
      highs.push({
        index,

        timestamp:
          sourceRows[
            index
          ].timestamp,

        price:
          candidateHigh,
      });
    }

    if (isSwingLow) {
      lows.push({
        index,

        timestamp:
          sourceRows[
            index
          ].timestamp,

        price:
          candidateLow,
      });
    }
  }

  return {
    highs,
    lows,
  };
}

function liveUniquePriceLevels(
  levels,
  thresholdRatio = 0.0015
) {
  const sorted =
    [...levels]
      .filter(
        value =>
          Number.isFinite(
            value
          ) &&
          value > 0
      )
      .sort(
        (left, right) =>
          left - right
      );

  const output = [];

  for (
    const level of sorted
  ) {
    const duplicate =
      output.some(
        existing => {
          const denominator =
            Math.max(
              Math.abs(
                existing
              ),

              Math.abs(
                level
              ),

              1
            );

          return (
            Math.abs(
              existing -
              level
            ) /
            denominator <=
            thresholdRatio
          );
        }
      );

    if (!duplicate) {
      output.push(level);
    }
  }

  return output;
}

function liveSupportResistance(
  rows,
  currentPrice
) {
  const sourceRows =
    Array.isArray(rows)
      ? rows
      : [];

  const price =
    candleNumber(
      currentPrice
    );

  if (
    !Number.isFinite(price) ||
    sourceRows.length === 0
  ) {
    return {
      supports: [],
      resistances: [],
      nearestSupport: null,
      nearestResistance: null,
    };
  }

  const radius =
    sourceRows.length > 80
      ? 3
      : sourceRows.length > 35
        ? 2
        : 1;

  const swings =
    liveSwingPoints(
      sourceRows,
      radius
    );

  let highLevels =
    liveUniquePriceLevels(
      swings.highs.map(
        point =>
          point.price
      )
    );

  let lowLevels =
    liveUniquePriceLevels(
      swings.lows.map(
        point =>
          point.price
      )
    );

  const allHighs =
    sourceRows
      .map(
        row =>
          candleNumber(
            row.high
          )
      )
      .filter(
        Number.isFinite
      );

  const allLows =
    sourceRows
      .map(
        row =>
          candleNumber(
            row.low
          )
      )
      .filter(
        Number.isFinite
      );

  const maximumHigh =
    allHighs.length > 0
      ? Math.max(
          ...allHighs
        )
      : null;

  const minimumLow =
    allLows.length > 0
      ? Math.min(
          ...allLows
        )
      : null;

  if (
    highLevels.every(
      level =>
        level <= price
    ) &&
    Number.isFinite(
      maximumHigh
    ) &&
    maximumHigh >
      price * 1.0005
  ) {
    highLevels.push(
      maximumHigh
    );
  }

  if (
    lowLevels.every(
      level =>
        level >= price
    ) &&
    Number.isFinite(
      minimumLow
    ) &&
    minimumLow <
      price * 0.9995
  ) {
    lowLevels.push(
      minimumLow
    );
  }

  const supports =
    liveUniquePriceLevels(
      lowLevels.filter(
        level =>
          level < price
      )
    )
      .sort(
        (left, right) =>
          right - left
      )
      .slice(
        0,
        3
      );

  const resistances =
    liveUniquePriceLevels(
      highLevels.filter(
        level =>
          level > price
      )
    )
      .sort(
        (left, right) =>
          left - right
      )
      .slice(
        0,
        3
      );

  return {
    supports,
    resistances,

    nearestSupport:
      supports[0] ??
      null,

    nearestResistance:
      resistances[0] ??
      null,
  };
}

function liveMarketStructure(
  rows
) {
  const sourceRows =
    Array.isArray(rows)
      ? rows
      : [];

  if (
    sourceRows.length < 8
  ) {
    return {
      direction:
        "NEUTRAL",

      label:
        "Not enough structure data",

      score: 0,

      latestHighs: [],
      latestLows: [],
    };
  }

  const radius =
    sourceRows.length > 60
      ? 3
      : sourceRows.length > 30
        ? 2
        : 1;

  const swings =
    liveSwingPoints(
      sourceRows,
      radius
    );

  const latestHighs =
    swings.highs.slice(-2);

  const latestLows =
    swings.lows.slice(-2);

  if (
    latestHighs.length < 2 ||
    latestLows.length < 2
  ) {
    return {
      direction:
        "NEUTRAL",

      label:
        "Mixed structure",

      score: 0,

      latestHighs,
      latestLows,
    };
  }

  const higherHigh =
    latestHighs[1].price >
    latestHighs[0].price;

  const lowerHigh =
    latestHighs[1].price <
    latestHighs[0].price;

  const higherLow =
    latestLows[1].price >
    latestLows[0].price;

  const lowerLow =
    latestLows[1].price <
    latestLows[0].price;

  if (
    higherHigh &&
    higherLow
  ) {
    return {
      direction:
        "BUY",

      label:
        "Bullish structure",

      score: 15,

      latestHighs,
      latestLows,
    };
  }

  if (
    lowerHigh &&
    lowerLow
  ) {
    return {
      direction:
        "SELL",

      label:
        "Bearish structure",

      score: -15,

      latestHighs,
      latestLows,
    };
  }

  return {
    direction:
      "NEUTRAL",

    label:
      "Mixed structure",

    score: 0,

    latestHighs,
    latestLows,
  };
}


// ---------------------------------------------------------------------------
// Adaptive EMA trend
// ---------------------------------------------------------------------------

function liveAdaptiveEmaPeriods(
  rowCount
) {
  const count =
    Math.max(
      2,
      candleInteger(
        rowCount,
        2
      )
    );

  const ema200 =
    Math.max(
      2,
      Math.min(
        200,
        count - 1
      )
    );

  const ema100 =
    Math.max(
      2,
      Math.min(
        100,
        Math.round(
          ema200 * 0.5
        )
      )
    );

  const ema50 =
    Math.max(
      2,
      Math.min(
        50,
        Math.round(
          ema100 * 0.6
        )
      )
    );

  const ema20 =
    Math.max(
      2,
      Math.min(
        20,
        Math.round(
          ema50 * 0.5
        )
      )
    );

  return {
    ema20,
    ema50,
    ema100,
    ema200,
  };
}

function liveTrendSnapshot(
  rows
) {
  const sourceRows =
    Array.isArray(rows)
      ? rows
      : [];

  const closes =
    liveCloseValues(
      sourceRows
    );

  if (
    closes.length < 5
  ) {
    return {
      direction:
        "NEUTRAL",

      legacyDirection:
        null,

      fullAlignment:
        false,

      partialAlignment:
        false,

      periods:
        liveAdaptiveEmaPeriods(
          closes.length
        ),

      values: {
        ema20: null,
        ema50: null,
        ema100: null,
        ema200: null,
      },

      reason:
        "Insufficient candle history",
    };
  }

  const periods =
    liveAdaptiveEmaPeriods(
      closes.length
    );

  const ema20Series =
    liveEma(
      closes,
      periods.ema20
    );

  const ema50Series =
    liveEma(
      closes,
      periods.ema50
    );

  const ema100Series =
    liveEma(
      closes,
      periods.ema100
    );

  const ema200Series =
    liveEma(
      closes,
      periods.ema200
    );

  const ema20 =
    liveLastFinite(
      ema20Series
    );

  const ema50 =
    liveLastFinite(
      ema50Series
    );

  const ema100 =
    liveLastFinite(
      ema100Series
    );

  const ema200 =
    liveLastFinite(
      ema200Series
    );

  const price =
    closes[
      closes.length - 1
    ];

  const valuesAvailable =
    [
      ema20,
      ema50,
      ema100,
      ema200,
      price,
    ].every(
      Number.isFinite
    );

  if (!valuesAvailable) {
    return {
      direction:
        "NEUTRAL",

      legacyDirection:
        null,

      fullAlignment:
        false,

      partialAlignment:
        false,

      periods,

      values: {
        ema20,
        ema50,
        ema100,
        ema200,
      },

      reason:
        "EMA values unavailable",
    };
  }

  const bullishComparisons = [
    price > ema20,
    ema20 > ema50,
    ema50 > ema100,
    ema100 > ema200,
  ];

  const bearishComparisons = [
    price < ema20,
    ema20 < ema50,
    ema50 < ema100,
    ema100 < ema200,
  ];

  const bullishCount =
    bullishComparisons
      .filter(Boolean)
      .length;

  const bearishCount =
    bearishComparisons
      .filter(Boolean)
      .length;

  const bullishFull =
    bullishCount === 4;

  const bearishFull =
    bearishCount === 4;

  let direction =
    "NEUTRAL";

  let legacyDirection =
    null;

  let reason =
    "EMA stack mixed";

  if (bullishFull) {
    direction =
      "BUY";

    legacyDirection =
      "BUY";

    reason =
      "Full bullish EMA alignment";
  } else if (
    bearishFull
  ) {
    direction =
      "SELL";

    legacyDirection =
      "SELL";

    reason =
      "Full bearish EMA alignment";
  } else if (
    bullishCount >= 3
  ) {
    reason =
      "Partial bullish EMA alignment";
  } else if (
    bearishCount >= 3
  ) {
    reason =
      "Partial bearish EMA alignment";
  }

  return {
    direction,
    legacyDirection,

    fullAlignment:
      bullishFull ||
      bearishFull,

    partialAlignment:
      !bullishFull &&
      !bearishFull &&
      Math.max(
        bullishCount,
        bearishCount
      ) >= 3,

    bullishCount,
    bearishCount,

    periods,

    values: {
      ema20,
      ema50,
      ema100,
      ema200,
    },

    reason,
  };
}


// ---------------------------------------------------------------------------
// Legacy-compatible step records
// ---------------------------------------------------------------------------

function livePipelineStep(
  name,
  status,
  detail,
  extra = {}
) {
  const normalizedStatus =
    String(
      status ||
      "na"
    ).toLowerCase();

  return {
    name,

    status:
      [
        "pass",
        "fail",
        "skip",
        "na",
        "info",
      ].includes(
        normalizedStatus
      )
        ? normalizedStatus
        : "na",

    passed:
      normalizedStatus ===
      "pass"
        ? true
        : normalizedStatus ===
            "fail"
          ? false
          : null,

    detail:
      String(
        detail ||
        ""
      ),

    ...extra,
  };
}

function normalizePipelineDecision(
  value
) {
  const normalized =
    String(
      value ||
      ""
    )
      .trim()
      .toUpperCase();

  if (
    normalized === "BUY" ||
    normalized === "LONG" ||
    normalized === "BULLISH"
  ) {
    return "BUY";
  }

  if (
    normalized === "SELL" ||
    normalized === "SHORT" ||
    normalized === "BEARISH"
  ) {
    return "SELL";
  }

  return "HOLD";
}

function liveRoundPrice(
  value,
  decimals = 5
) {
  const parsed =
    candleNumber(
      value
    );

  if (
    !Number.isFinite(
      parsed
    )
  ) {
    return null;
  }

  const safeDecimals =
    Math.max(
      0,
      Math.min(
        10,
        candleInteger(
          decimals,
          5
        )
      )
    );

  return Number(
    parsed.toFixed(
      safeDecimals
    )
  );
}

function livePairPriceDecimals(
  pair
) {
  const normalized =
    String(
      pair ||
      ""
    )
      .trim()
      .toUpperCase()
      .replace(
        /[^A-Z]/g,
        ""
      );

  if (
    normalized ===
    "XAUUSD"
  ) {
    return 2;
  }

  if (
    normalized.endsWith(
      "JPY"
    )
  ) {
    return 3;
  }

  return 5;
}


