// ---------------------------------------------------------------------------
// Professional confluence / volatility helpers (strategy extension 2.0.0)
// ---------------------------------------------------------------------------

const PROFESSIONAL_LIVE_PIPELINE_VERSION = "2.0.0";

const PROFESSIONAL_LIVE_CONFIG = Object.freeze({
  M5: Object.freeze({
    minimumCandles: 80,
    minimumScore: 64,
    minimumEdge: 12,
    baseStopAtr: 1.35,
    maximumStopAtr: 2.8,
    minimumRiskReward: 2.0,
    minimumBarrierR: 1.15,
  }),
  H1: Object.freeze({
    minimumCandles: 80,
    minimumScore: 62,
    minimumEdge: 12,
    baseStopAtr: 1.65,
    maximumStopAtr: 3.2,
    minimumRiskReward: 2.0,
    minimumBarrierR: 1.20,
  }),
  D1: Object.freeze({
    minimumCandles: 60,
    minimumScore: 60,
    minimumEdge: 12,
    baseStopAtr: 2.20,
    maximumStopAtr: 4.2,
    minimumRiskReward: 2.0,
    minimumBarrierR: 1.25,
  }),
  W1: Object.freeze({
    minimumCandles: 35,
    minimumScore: 58,
    minimumEdge: 14,
    baseStopAtr: 2.80,
    maximumStopAtr: 5.2,
    minimumRiskReward: 2.0,
    minimumBarrierR: 1.25,
  }),
});

const PROFESSIONAL_LIVE_WEIGHTS = Object.freeze({
  ema: 24,
  macd: 16,
  rsi: 16,
  dmiAdx: 16,
  structure: 12,
  candlePattern: 6,
  volatility: 4,
});

const PROFESSIONAL_LIVE_TOTAL_WEIGHT =
  Object.values(PROFESSIONAL_LIVE_WEIGHTS)
    .reduce((sum, value) => sum + value, 0);

const PROFESSIONAL_LIVE_PAIR_ATR_MODIFIER = Object.freeze({
  XAUUSD: 1.10,
  GBPJPY: 1.00,
});

function professionalLiveClamp(value, minimum, maximum) {
  return Math.max(minimum, Math.min(maximum, value));
}

function professionalLiveRound(value, decimals = 6) {
  if (!Number.isFinite(value)) {
    return null;
  }

  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function professionalLiveTimeframeKey(value) {
  const raw = String(value || "H1")
    .trim()
    .toUpperCase()
    .replace(/\s+/g, "");

  if (
    raw === "SCALP" ||
    raw === "M5" ||
    raw === "5M" ||
    raw === "5MIN"
  ) {
    return "M5";
  }

  if (
    raw === "H1" ||
    raw === "1H" ||
    raw === "60M" ||
    raw === "60MIN" ||
    raw === "INTRADAY"
  ) {
    return "H1";
  }

  if (
    raw === "D1" ||
    raw === "1D" ||
    raw === "DAILY" ||
    raw === "SWING"
  ) {
    return "D1";
  }

  if (
    raw === "W1" ||
    raw === "1W" ||
    raw === "WEEKLY"
  ) {
    return "W1";
  }

  const normalized = normalizeLiveTimeframe(raw, "H1");

  return Object.prototype.hasOwnProperty.call(
    PROFESSIONAL_LIVE_CONFIG,
    normalized
  )
    ? normalized
    : "H1";
}

function professionalLiveConfigFor(timeframe) {
  return PROFESSIONAL_LIVE_CONFIG[
    professionalLiveTimeframeKey(timeframe)
  ];
}

function professionalLivePairKey(value) {
  return String(value || "")
    .replace(/[^A-Za-z0-9]/g, "")
    .toUpperCase();
}

function professionalLivePairAtrModifier(pair) {
  return (
    PROFESSIONAL_LIVE_PAIR_ATR_MODIFIER[
      professionalLivePairKey(pair)
    ] || 1
  );
}

function professionalLiveLastFiniteIndex(values) {
  if (!Array.isArray(values)) {
    return -1;
  }

  for (let index = values.length - 1; index >= 0; index -= 1) {
    if (Number.isFinite(values[index])) {
      return index;
    }
  }

  return -1;
}

function professionalLivePreviousFinite(values, fromIndex) {
  if (!Array.isArray(values)) {
    return null;
  }

  const start = Number.isInteger(fromIndex)
    ? fromIndex - 1
    : values.length - 2;

  for (let index = start; index >= 0; index -= 1) {
    if (Number.isFinite(values[index])) {
      return values[index];
    }
  }

  return null;
}

function professionalLiveMedian(values) {
  const finite = (Array.isArray(values) ? values : [])
    .filter(Number.isFinite)
    .sort((left, right) => left - right);

  if (finite.length === 0) {
    return null;
  }

  const middle = Math.floor(finite.length / 2);

  return finite.length % 2 === 0
    ? (finite[middle - 1] + finite[middle]) / 2
    : finite[middle];
}

function professionalLivePercentileRank(values, current) {
  const finite = (Array.isArray(values) ? values : [])
    .filter(Number.isFinite);

  if (finite.length === 0 || !Number.isFinite(current)) {
    return null;
  }

  const lessOrEqual = finite.filter(value => value <= current).length;
  return (lessOrEqual / finite.length) * 100;
}

function professionalLiveInferSourceIntervalMs(rows) {
  const source = Array.isArray(rows) ? rows : [];
  const gaps = [];

  for (let index = 1; index < source.length; index += 1) {
    const gap = source[index].timestamp - source[index - 1].timestamp;

    if (Number.isFinite(gap) && gap > 0) {
      gaps.push(gap);
    }
  }

  const medianGap = professionalLiveMedian(gaps);

  return Number.isFinite(medianGap)
    ? Math.round(medianGap / 1000) * 1000
    : null;
}

function professionalLiveClosedRows(rawRows, timeframe, nowMs = Date.now()) {
  const timeframeKey = professionalLiveTimeframeKey(timeframe);
  const intervalMs = liveTimeframeMs(timeframeKey, timeframeKey);
  const normalized = normalizeLiveCandleArray(rawRows, { maxRows: 10000 });
  const rows = [];
  let explicitOpenRemoved = 0;
  let formingRemoved = 0;
  let invalidCloseRemoved = 0;

  for (const row of normalized) {
    if (row.closed === false) {
      explicitOpenRemoved += 1;
      continue;
    }

    const closeTimestamp = Number.isFinite(row.closeTimestamp)
      ? row.closeTimestamp
      : row.timestamp + intervalMs;

    if (!Number.isFinite(closeTimestamp)) {
      invalidCloseRemoved += 1;
      continue;
    }

    if (closeTimestamp > nowMs) {
      formingRemoved += 1;
      continue;
    }

    rows.push({
      ...row,
      closeTimestamp,
      closeTime: new Date(closeTimestamp).toISOString(),
      closed: true,
      timeframe: timeframeKey,
    });
  }

  const sourceIntervalMs = professionalLiveInferSourceIntervalMs(rows);
  let gapCount = 0;
  let expectedGapCount = 0;

  if (Number.isFinite(sourceIntervalMs) && sourceIntervalMs > 0) {
    for (let index = 1; index < rows.length; index += 1) {
      const gap = rows[index].timestamp - rows[index - 1].timestamp;

      if (gap > sourceIntervalMs * 1.5) {
        gapCount += 1;
        expectedGapCount += Math.max(
          1,
          Math.round(gap / sourceIntervalMs) - 1
        );
      }
    }
  }

  const continuityRatio = rows.length > 1
    ? professionalLiveClamp(
        1 - gapCount / (rows.length - 1),
        0,
        1
      )
    : 0;

  return {
    rows,
    diagnostics: {
      inputRows: Array.isArray(rawRows) ? rawRows.length : 0,
      normalizedRows: normalized.length,
      closedRows: rows.length,
      explicitOpenRemoved,
      formingRemoved,
      invalidCloseRemoved,
      sourceIntervalMs,
      gapCount,
      missingIntervalEstimate: expectedGapCount,
      continuityRatio: professionalLiveRound(continuityRatio, 4),
      latestClosedAt: rows.length
        ? rows[rows.length - 1].closeTime
        : null,
    },
  };
}

function professionalLiveEmaSnapshot(rows) {
  const closes = liveCloseValues(rows);
  const periods = liveAdaptiveEmaPeriods(closes.length);

  const empty = {
    available: false,
    direction: "NEUTRAL",
    fullAlignment: false,
    partialAlignment: false,
    bullishCount: 0,
    bearishCount: 0,
    periods,
    values: {
      ema20: null,
      ema50: null,
      ema100: null,
      ema200: null,
    },
    slopes: {
      ema20: null,
      ema50: null,
      ema100: null,
      ema200: null,
    },
    reason: "EMA values unavailable",
  };

  if (closes.length < 5 || !periods) {
    return empty;
  }

  const series = {
    ema20: liveEma(closes, periods.ema20),
    ema50: liveEma(closes, periods.ema50),
    ema100: liveEma(closes, periods.ema100),
    ema200: liveEma(closes, periods.ema200),
  };

  const values = {};
  const slopes = {};

  for (const key of Object.keys(series)) {
    const lastIndex = professionalLiveLastFiniteIndex(series[key]);
    const current = lastIndex >= 0 ? series[key][lastIndex] : null;
    const previous = professionalLivePreviousFinite(series[key], lastIndex);

    values[key] = current;
    slopes[key] = Number.isFinite(current) && Number.isFinite(previous)
      ? current - previous
      : null;
  }

  const price = closes[closes.length - 1];
  const available = [
    price,
    values.ema20,
    values.ema50,
    values.ema100,
    values.ema200,
  ].every(Number.isFinite);

  if (!available) {
    return {
      ...empty,
      periods,
      values,
      slopes,
    };
  }

  const bullishChecks = [
    price > values.ema20,
    values.ema20 > values.ema50,
    values.ema50 > values.ema100,
    values.ema100 > values.ema200,
  ];

  const bearishChecks = [
    price < values.ema20,
    values.ema20 < values.ema50,
    values.ema50 < values.ema100,
    values.ema100 < values.ema200,
  ];

  const bullishCount = bullishChecks.filter(Boolean).length;
  const bearishCount = bearishChecks.filter(Boolean).length;
  const bullishSlopeCount = [slopes.ema20, slopes.ema50]
    .filter(value => Number.isFinite(value) && value > 0).length;
  const bearishSlopeCount = [slopes.ema20, slopes.ema50]
    .filter(value => Number.isFinite(value) && value < 0).length;

  let direction = "NEUTRAL";

  if (
    bullishCount === 4 ||
    (bullishCount >= 3 && bullishSlopeCount === 2)
  ) {
    direction = "BUY";
  } else if (
    bearishCount === 4 ||
    (bearishCount >= 3 && bearishSlopeCount === 2)
  ) {
    direction = "SELL";
  }

  const fullAlignment = bullishCount === 4 || bearishCount === 4;
  const partialAlignment = !fullAlignment && Math.max(bullishCount, bearishCount) >= 3;

  return {
    available: true,
    direction,
    legacyDirection: fullAlignment ? direction : null,
    fullAlignment,
    partialAlignment,
    bullishCount,
    bearishCount,
    bullishSlopeCount,
    bearishSlopeCount,
    periods,
    values,
    slopes,
    price,
    reason: fullAlignment
      ? `Full ${direction === "BUY" ? "bullish" : "bearish"} EMA alignment`
      : partialAlignment
        ? `Partial ${direction === "BUY" ? "bullish" : direction === "SELL" ? "bearish" : "mixed"} EMA alignment with slope confirmation`
        : "EMA structure is mixed",
  };
}

function professionalLiveRsiSnapshot(closes, period = 14) {
  const series = liveRsi(closes, period);
  const lastIndex = professionalLiveLastFiniteIndex(series);
  const current = lastIndex >= 0 ? series[lastIndex] : null;
  const previous = professionalLivePreviousFinite(series, lastIndex);
  const thirdPrevious = professionalLivePreviousFinite(series, lastIndex - 1);
  const slope = Number.isFinite(current) && Number.isFinite(previous)
    ? current - previous
    : null;
  const momentum3 = Number.isFinite(current) && Number.isFinite(thirdPrevious)
    ? current - thirdPrevious
    : null;

  const crossedAbove50 =
    Number.isFinite(current) &&
    Number.isFinite(previous) &&
    previous <= 50 &&
    current > 50;

  const crossedBelow50 =
    Number.isFinite(current) &&
    Number.isFinite(previous) &&
    previous >= 50 &&
    current < 50;

  let regime = "UNAVAILABLE";

  if (Number.isFinite(current)) {
    if (current >= 75) {
      regime = "OVERBOUGHT_EXTREME";
    } else if (current >= 60) {
      regime = "BULLISH_MOMENTUM";
    } else if (current > 50) {
      regime = "BULLISH_CONTROL";
    } else if (current <= 25) {
      regime = "OVERSOLD_EXTREME";
    } else if (current <= 40) {
      regime = "BEARISH_MOMENTUM";
    } else if (current < 50) {
      regime = "BEARISH_CONTROL";
    } else {
      regime = "NEUTRAL";
    }
  }

  return {
    available: Number.isFinite(current),
    period,
    current,
    previous,
    slope,
    momentum3,
    crossedAbove50,
    crossedBelow50,
    regime,
    series,
  };
}

function professionalLiveMacdSnapshot(closes) {
  const calculated = liveMacd(closes, 12, 26, 9);
  const index = professionalLiveLastFiniteIndex(calculated.histogram);
  const macd = index >= 0 ? calculated.macdLine[index] : null;
  const signal = index >= 0 ? calculated.signalLine[index] : null;
  const histogram = index >= 0 ? calculated.histogram[index] : null;
  const previousHistogram = professionalLivePreviousFinite(
    calculated.histogram,
    index
  );
  const histogramSlope =
    Number.isFinite(histogram) && Number.isFinite(previousHistogram)
      ? histogram - previousHistogram
      : null;

  return {
    available: [macd, signal, histogram].every(Number.isFinite),
    macd,
    signal,
    histogram,
    previousHistogram,
    histogramSlope,
    crossedBullish:
      Number.isFinite(histogram) &&
      Number.isFinite(previousHistogram) &&
      previousHistogram <= 0 &&
      histogram > 0,
    crossedBearish:
      Number.isFinite(histogram) &&
      Number.isFinite(previousHistogram) &&
      previousHistogram >= 0 &&
      histogram < 0,
    series: calculated,
  };
}

function professionalLiveDmiAdx(rows, period = 14) {
  const source = Array.isArray(rows) ? rows : [];
  const length = source.length;
  const plusDiSeries = Array(length).fill(null);
  const minusDiSeries = Array(length).fill(null);
  const dxSeries = Array(length).fill(null);
  const adxSeries = Array(length).fill(null);

  if (length < period * 2 + 1) {
    return {
      available: false,
      period,
      adx: null,
      previousAdx: null,
      adxSlope: null,
      plusDI: null,
      minusDI: null,
      direction: "NEUTRAL",
      regime: "UNAVAILABLE",
      plusDiSeries,
      minusDiSeries,
      dxSeries,
      adxSeries,
    };
  }

  const trueRanges = Array(length).fill(null);
  const plusDm = Array(length).fill(0);
  const minusDm = Array(length).fill(0);

  for (let index = 1; index < length; index += 1) {
    const current = source[index];
    const previous = source[index - 1];
    const high = candleNumber(current.high);
    const low = candleNumber(current.low);
    const previousHigh = candleNumber(previous.high);
    const previousLow = candleNumber(previous.low);
    const previousClose = candleNumber(previous.close);

    if (![high, low, previousHigh, previousLow, previousClose].every(Number.isFinite)) {
      continue;
    }

    trueRanges[index] = Math.max(
      high - low,
      Math.abs(high - previousClose),
      Math.abs(low - previousClose)
    );

    const upwardMove = high - previousHigh;
    const downwardMove = previousLow - low;

    plusDm[index] = upwardMove > downwardMove && upwardMove > 0
      ? upwardMove
      : 0;

    minusDm[index] = downwardMove > upwardMove && downwardMove > 0
      ? downwardMove
      : 0;
  }

  let smoothedTr = 0;
  let smoothedPlusDm = 0;
  let smoothedMinusDm = 0;

  for (let index = 1; index <= period; index += 1) {
    if (!Number.isFinite(trueRanges[index])) {
      return {
        available: false,
        period,
        adx: null,
        previousAdx: null,
        adxSlope: null,
        plusDI: null,
        minusDI: null,
        direction: "NEUTRAL",
        regime: "UNAVAILABLE",
        plusDiSeries,
        minusDiSeries,
        dxSeries,
        adxSeries,
      };
    }

    smoothedTr += trueRanges[index];
    smoothedPlusDm += plusDm[index];
    smoothedMinusDm += minusDm[index];
  }

  let previousAdxValue = null;
  const dxSeed = [];

  for (let index = period; index < length; index += 1) {
    if (index > period) {
      if (!Number.isFinite(trueRanges[index])) {
        continue;
      }

      smoothedTr = smoothedTr - smoothedTr / period + trueRanges[index];
      smoothedPlusDm = smoothedPlusDm - smoothedPlusDm / period + plusDm[index];
      smoothedMinusDm = smoothedMinusDm - smoothedMinusDm / period + minusDm[index];
    }

    if (smoothedTr <= 0) {
      continue;
    }

    const plusDI = 100 * smoothedPlusDm / smoothedTr;
    const minusDI = 100 * smoothedMinusDm / smoothedTr;
    const denominator = plusDI + minusDI;
    const dx = denominator > 0
      ? 100 * Math.abs(plusDI - minusDI) / denominator
      : 0;

    plusDiSeries[index] = plusDI;
    minusDiSeries[index] = minusDI;
    dxSeries[index] = dx;

    if (dxSeed.length < period) {
      dxSeed.push(dx);

      if (dxSeed.length === period) {
        previousAdxValue = dxSeed.reduce((sum, value) => sum + value, 0) / period;
        adxSeries[index] = previousAdxValue;
      }
    } else if (Number.isFinite(previousAdxValue)) {
      previousAdxValue = ((previousAdxValue * (period - 1)) + dx) / period;
      adxSeries[index] = previousAdxValue;
    }
  }

  const lastIndex = professionalLiveLastFiniteIndex(adxSeries);
  const adx = lastIndex >= 0 ? adxSeries[lastIndex] : null;
  const previousAdx = professionalLivePreviousFinite(adxSeries, lastIndex);
  const plusDI = lastIndex >= 0 ? plusDiSeries[lastIndex] : null;
  const minusDI = lastIndex >= 0 ? minusDiSeries[lastIndex] : null;
  const adxSlope = Number.isFinite(adx) && Number.isFinite(previousAdx)
    ? adx - previousAdx
    : null;

  let direction = "NEUTRAL";

  if (Number.isFinite(plusDI) && Number.isFinite(minusDI)) {
    if (plusDI > minusDI) {
      direction = "BUY";
    } else if (minusDI > plusDI) {
      direction = "SELL";
    }
  }

  let regime = "UNAVAILABLE";

  if (Number.isFinite(adx)) {
    if (adx >= 40) {
      regime = "STRONG";
    } else if (adx >= 25) {
      regime = "TRENDING";
    } else if (adx >= 18) {
      regime = "DEVELOPING";
    } else {
      regime = "WEAK";
    }
  }

  return {
    available: [adx, plusDI, minusDI].every(Number.isFinite),
    period,
    adx,
    previousAdx,
    adxSlope,
    plusDI,
    minusDI,
    direction,
    regime,
    plusDiSeries,
    minusDiSeries,
    dxSeries,
    adxSeries,
  };
}

function professionalLiveAtrSnapshot(rows, period = 14, percentileWindow = 100) {
  const series = liveAtr(rows, period);
  const lastIndex = professionalLiveLastFiniteIndex(series);
  const current = lastIndex >= 0 ? series[lastIndex] : null;
  const previous = professionalLivePreviousFinite(series, lastIndex);
  const price = Array.isArray(rows) && rows.length
    ? candleNumber(rows[rows.length - 1].close)
    : null;
  const finiteWindow = series
    .filter(Number.isFinite)
    .slice(-Math.max(20, percentileWindow));
  const median = professionalLiveMedian(finiteWindow);
  const percentile = professionalLivePercentileRank(finiteWindow, current);
  const medianRatio =
    Number.isFinite(current) && Number.isFinite(median) && median > 0
      ? current / median
      : null;
  const atrPercent =
    Number.isFinite(current) && Number.isFinite(price) && price > 0
      ? current / price * 100
      : null;
  const slope =
    Number.isFinite(current) && Number.isFinite(previous)
      ? current - previous
      : null;

  let regime = "UNAVAILABLE";

  if (Number.isFinite(current)) {
    if (
      (Number.isFinite(percentile) && percentile >= 95) &&
      (Number.isFinite(medianRatio) && medianRatio >= 1.8)
    ) {
      regime = "EXTREME";
    } else if (
      (Number.isFinite(percentile) && percentile >= 75) ||
      (Number.isFinite(medianRatio) && medianRatio >= 1.25)
    ) {
      regime = "HIGH";
    } else if (
      (Number.isFinite(percentile) && percentile <= 20) ||
      (Number.isFinite(medianRatio) && medianRatio <= 0.70)
    ) {
      regime = "LOW";
    } else {
      regime = "NORMAL";
    }
  }

  const hardBlock =
    regime === "EXTREME" &&
    Number.isFinite(percentile) &&
    percentile >= 98 &&
    Number.isFinite(medianRatio) &&
    medianRatio >= 2.2;

  const regimeStopFactor = {
    LOW: 0.90,
    NORMAL: 1.00,
    HIGH: 1.15,
    EXTREME: 1.30,
  }[regime] || 1;

  return {
    available: Number.isFinite(current),
    period,
    current,
    previous,
    slope,
    atrPercent,
    percentile,
    median,
    medianRatio,
    regime,
    regimeStopFactor,
    hardBlock,
    series,
  };
}

function professionalLiveCandleSnapshot(rows) {
  const source = Array.isArray(rows) ? rows : [];
  const last = source[source.length - 1] || null;
  const previous = source[source.length - 2] || null;

  if (!last || !previous) {
    return {
      available: false,
      buy: { confirmed: false, detail: "Not enough candle history" },
      sell: { confirmed: false, detail: "Not enough candle history" },
      bodyRatio: null,
      candleDirection: "NEUTRAL",
    };
  }

  const buyPattern = detectCandlePattern(source, "BUY");
  const sellPattern = detectCandlePattern(source, "SELL");
  const range = candleNumber(last.high) - candleNumber(last.low);
  const body = Math.abs(candleNumber(last.close) - candleNumber(last.open));
  const bodyRatio = Number.isFinite(range) && range > 0 ? body / range : 0;
  const candleDirection = last.close > last.open
    ? "BUY"
    : last.close < last.open
      ? "SELL"
      : "NEUTRAL";

  return {
    available: true,
    buy: {
      confirmed: buyPattern.ok === true,
      detail: buyPattern.detail,
    },
    sell: {
      confirmed: sellPattern.ok === true,
      detail: sellPattern.detail,
    },
    bodyRatio,
    candleDirection,
  };
}

function professionalLiveScoreEma(snapshot, direction) {
  if (!snapshot || snapshot.available !== true) {
    return 0;
  }

  const bullish = direction === "BUY";
  const comparisonCount = bullish
    ? snapshot.bullishCount
    : snapshot.bearishCount;
  const slopeCount = bullish
    ? snapshot.bullishSlopeCount
    : snapshot.bearishSlopeCount;
  const comparisonScore = comparisonCount / 4 * 18;
  const slopeScore = slopeCount / 2 * 6;

  return professionalLiveClamp(
    comparisonScore + slopeScore,
    0,
    PROFESSIONAL_LIVE_WEIGHTS.ema
  );
}

function professionalLiveScoreMacd(snapshot, direction) {
  if (!snapshot || snapshot.available !== true) {
    return 0;
  }

  const bullish = direction === "BUY";
  let score = 0;

  if (bullish ? snapshot.macd > snapshot.signal : snapshot.macd < snapshot.signal) {
    score += 8;
  }

  if (bullish ? snapshot.histogram > 0 : snapshot.histogram < 0) {
    score += 5;
  }

  if (
    Number.isFinite(snapshot.histogramSlope) &&
    (bullish ? snapshot.histogramSlope > 0 : snapshot.histogramSlope < 0)
  ) {
    score += 3;
  }

  return professionalLiveClamp(score, 0, PROFESSIONAL_LIVE_WEIGHTS.macd);
}

function professionalLiveScoreRsi(snapshot, direction) {
  if (!snapshot || snapshot.available !== true) {
    return 0;
  }

  const bullish = direction === "BUY";
  let score = 0;

  if (bullish ? snapshot.current > 50 : snapshot.current < 50) {
    score += 8;
  }

  if (
    Number.isFinite(snapshot.slope) &&
    (bullish ? snapshot.slope > 0 : snapshot.slope < 0)
  ) {
    score += 4;
  }

  if (
    Number.isFinite(snapshot.momentum3) &&
    (bullish ? snapshot.momentum3 > 0 : snapshot.momentum3 < 0)
  ) {
    score += 2;
  }

  if (bullish ? snapshot.crossedAbove50 : snapshot.crossedBelow50) {
    score += 2;
  }

  if (
    (bullish && snapshot.current >= 78) ||
    (!bullish && snapshot.current <= 22)
  ) {
    score -= 4;
  }

  return professionalLiveClamp(score, 0, PROFESSIONAL_LIVE_WEIGHTS.rsi);
}

function professionalLiveScoreDmi(snapshot, direction) {
  if (!snapshot || snapshot.available !== true) {
    return 0;
  }

  const bullish = direction === "BUY";
  let score = 0;

  if (bullish ? snapshot.plusDI > snapshot.minusDI : snapshot.minusDI > snapshot.plusDI) {
    score += 8;
  }

  if (snapshot.adx >= 25) {
    score += 4;
  } else if (snapshot.adx >= 18) {
    score += 2;
  }

  if (Number.isFinite(snapshot.adxSlope) && snapshot.adxSlope > 0) {
    score += 2;
  }

  if (
    snapshot.regime === "STRONG" ||
    snapshot.regime === "TRENDING"
  ) {
    score += 2;
  }

  return professionalLiveClamp(score, 0, PROFESSIONAL_LIVE_WEIGHTS.dmiAdx);
}

function professionalLiveScoreStructure(snapshot, direction) {
  if (!snapshot || typeof snapshot !== "object") {
    return 0;
  }

  if (snapshot.direction === direction) {
    return PROFESSIONAL_LIVE_WEIGHTS.structure;
  }

  if (snapshot.direction === "NEUTRAL") {
    return 4;
  }

  return 0;
}

function professionalLiveScoreCandle(snapshot, direction) {
  if (!snapshot || snapshot.available !== true) {
    return 0;
  }

  const directional = direction === "BUY" ? snapshot.buy : snapshot.sell;

  if (directional && directional.confirmed) {
    return PROFESSIONAL_LIVE_WEIGHTS.candlePattern;
  }

  if (
    snapshot.candleDirection === direction &&
    Number.isFinite(snapshot.bodyRatio) &&
    snapshot.bodyRatio >= 0.55
  ) {
    return 2;
  }

  return 0;
}

function professionalLiveScoreVolatility(snapshot) {
  if (!snapshot || snapshot.available !== true) {
    return 0;
  }

  return {
    NORMAL: 4,
    HIGH: 3,
    LOW: 1,
    EXTREME: 0,
  }[snapshot.regime] || 0;
}

function professionalLiveScoreDirection({
  direction,
  ema,
  macd,
  rsi,
  dmiAdx,
  structure,
  candlePattern,
  atr,
}) {
  const components = {
    ema: professionalLiveScoreEma(ema, direction),
    macd: professionalLiveScoreMacd(macd, direction),
    rsi: professionalLiveScoreRsi(rsi, direction),
    dmiAdx: professionalLiveScoreDmi(dmiAdx, direction),
    structure: professionalLiveScoreStructure(structure, direction),
    candlePattern: professionalLiveScoreCandle(candlePattern, direction),
    volatility: professionalLiveScoreVolatility(atr),
  };

  const rawScore = Object.values(components)
    .reduce((sum, value) => sum + value, 0);
  const normalizedScore = PROFESSIONAL_LIVE_TOTAL_WEIGHT > 0
    ? rawScore / PROFESSIONAL_LIVE_TOTAL_WEIGHT * 100
    : 0;

  return {
    direction,
    components: Object.fromEntries(
      Object.entries(components).map(([key, value]) => [
        key,
        professionalLiveRound(value, 4),
      ])
    ),
    rawScore: professionalLiveRound(rawScore, 4),
    score: professionalLiveRound(
      professionalLiveClamp(normalizedScore, 0, 100),
      2
    ),
  };
}

function professionalLiveSelectDirection(buyEvidence, sellEvidence, config) {
  const buyScore = candleNumber(buyEvidence && buyEvidence.score, 0);
  const sellScore = candleNumber(sellEvidence && sellEvidence.score, 0);
  const winner = buyScore >= sellScore ? "BUY" : "SELL";
  const winningScore = Math.max(buyScore, sellScore);
  const losingScore = Math.min(buyScore, sellScore);
  const edge = winningScore - losingScore;
  const qualified =
    winningScore >= config.minimumScore &&
    edge >= config.minimumEdge;

  return {
    direction: qualified ? winner : "HOLD",
    rawDirection: winner,
    qualified,
    winningScore: professionalLiveRound(winningScore, 2),
    losingScore: professionalLiveRound(losingScore, 2),
    edge: professionalLiveRound(edge, 2),
    minimumScore: config.minimumScore,
    minimumEdge: config.minimumEdge,
    reason: qualified
      ? `${winner} confluence qualified at ${winningScore.toFixed(2)} with ${edge.toFixed(2)} edge`
      : `Confluence not qualified: best ${winningScore.toFixed(2)}, edge ${edge.toFixed(2)}`,
  };
}

function professionalLiveRecentStructureLevel(rows, direction, lookback = 80) {
  const source = (Array.isArray(rows) ? rows : []).slice(-lookback);

  if (source.length < 5) {
    return null;
  }

  const currentPrice = candleNumber(source[source.length - 1].close);
  const levels = [];

  for (let index = 2; index < source.length - 2; index += 1) {
    const current = source[index];

    if (direction === "BUY") {
      const swingLow =
        current.low <= source[index - 1].low &&
        current.low <= source[index - 2].low &&
        current.low <= source[index + 1].low &&
        current.low <= source[index + 2].low;

      if (swingLow && current.low < currentPrice) {
        levels.push(current.low);
      }
    } else {
      const swingHigh =
        current.high >= source[index - 1].high &&
        current.high >= source[index - 2].high &&
        current.high >= source[index + 1].high &&
        current.high >= source[index + 2].high;

      if (swingHigh && current.high > currentPrice) {
        levels.push(current.high);
      }
    }
  }

  if (levels.length === 0) {
    return null;
  }

  return direction === "BUY"
    ? Math.max(...levels)
    : Math.min(...levels);
}

function professionalLiveConfirmedSwingLevels(rows, lookback = 160) {
  const source = (Array.isArray(rows) ? rows : []).slice(-lookback);
  const highs = [];
  const lows = [];

  for (let index = 2; index < source.length - 2; index += 1) {
    const current = source[index];
    const high = candleNumber(current.high);
    const low = candleNumber(current.low);

    if (![high, low].every(Number.isFinite)) {
      continue;
    }

    const swingHigh =
      high > candleNumber(source[index - 1].high, -Infinity) &&
      high >= candleNumber(source[index - 2].high, -Infinity) &&
      high > candleNumber(source[index + 1].high, -Infinity) &&
      high >= candleNumber(source[index + 2].high, -Infinity);

    const swingLow =
      low < candleNumber(source[index - 1].low, Infinity) &&
      low <= candleNumber(source[index - 2].low, Infinity) &&
      low < candleNumber(source[index + 1].low, Infinity) &&
      low <= candleNumber(source[index + 2].low, Infinity);

    if (swingHigh) {
      highs.push(high);
    }

    if (swingLow) {
      lows.push(low);
    }
  }

  return {
    highs: [...new Set(highs)].sort((left, right) => left - right),
    lows: [...new Set(lows)].sort((left, right) => left - right),
  };
}

function buildLiveTradePlan({
  direction,
  price,
  atr,
  atrSnapshot,
  supportResistance,
  pair,
  timeframe = "H1",
  rows = [],
}) {
  const normalizedDirection = normalizePipelineDecision(direction);
  const currentPrice = candleNumber(price);
  const currentAtr = candleNumber(
    atrSnapshot && atrSnapshot.current,
    candleNumber(atr)
  );
  const config = professionalLiveConfigFor(timeframe);
  const timeframeKey = professionalLiveTimeframeKey(timeframe);
  const decimals = livePairPriceDecimals(pair);

  if (
    normalizedDirection === "HOLD" ||
    !Number.isFinite(currentPrice) ||
    currentPrice <= 0 ||
    !Number.isFinite(currentAtr) ||
    currentAtr <= 0
  ) {
    return null;
  }

  if (atrSnapshot && atrSnapshot.hardBlock === true) {
    return null;
  }

  const regimeFactor = candleNumber(
    atrSnapshot && atrSnapshot.regimeStopFactor,
    1
  );
  const pairModifier = professionalLivePairAtrModifier(pair);
  const baseDistance =
    currentAtr *
    config.baseStopAtr *
    pairModifier *
    regimeFactor;
  const maximumDistance = currentAtr * config.maximumStopAtr;
  const structureBuffer = currentAtr * 0.15;
  const confirmedSwingLevels = professionalLiveConfirmedSwingLevels(
    rows
  );
  const confirmedSupports = confirmedSwingLevels.lows
    .filter(level => level < currentPrice);
  const confirmedResistances = confirmedSwingLevels.highs
    .filter(level => level > currentPrice);
  const nearestSupport = confirmedSupports.length > 0
    ? Math.max(...confirmedSupports)
    : null;
  const nearestResistance = confirmedResistances.length > 0
    ? Math.min(...confirmedResistances)
    : null;
  const recentStructureLevel = professionalLiveRecentStructureLevel(
    rows,
    normalizedDirection
  );

  const candidates = [];

  if (normalizedDirection === "BUY") {
    if (Number.isFinite(nearestSupport) && nearestSupport < currentPrice) {
      candidates.push(nearestSupport);
    }

    if (
      Number.isFinite(recentStructureLevel) &&
      recentStructureLevel < currentPrice
    ) {
      candidates.push(recentStructureLevel);
    }
  } else {
    if (
      Number.isFinite(nearestResistance) &&
      nearestResistance > currentPrice
    ) {
      candidates.push(nearestResistance);
    }

    if (
      Number.isFinite(recentStructureLevel) &&
      recentStructureLevel > currentPrice
    ) {
      candidates.push(recentStructureLevel);
    }
  }

  const selectedStructureLevel = candidates.length > 0
    ? normalizedDirection === "BUY"
      ? Math.max(...candidates)
      : Math.min(...candidates)
    : null;

  let stopDistance = baseDistance;
  let structureUsed = false;
  let structureDistance = null;

  if (Number.isFinite(selectedStructureLevel)) {
    const proposedStop = normalizedDirection === "BUY"
      ? selectedStructureLevel - structureBuffer
      : selectedStructureLevel + structureBuffer;

    structureDistance = Math.abs(currentPrice - proposedStop);

    if (
      Number.isFinite(structureDistance) &&
      structureDistance > 0 &&
      structureDistance <= maximumDistance
    ) {
      stopDistance = Math.max(baseDistance, structureDistance);
      structureUsed = true;
    }
  }

  stopDistance = professionalLiveClamp(
    stopDistance,
    currentAtr * 0.75,
    maximumDistance
  );

  const rawStop = normalizedDirection === "BUY"
    ? currentPrice - stopDistance
    : currentPrice + stopDistance;

  const roundedEntry = liveRoundPrice(currentPrice, decimals);
  const roundedStop = liveRoundPrice(rawStop, decimals);
  const roundedRisk = Math.abs(roundedEntry - roundedStop);

  if (!Number.isFinite(roundedRisk) || roundedRisk <= 0) {
    return null;
  }

  const target1 = liveRoundPrice(
    normalizedDirection === "BUY"
      ? roundedEntry + roundedRisk * config.minimumRiskReward
      : roundedEntry - roundedRisk * config.minimumRiskReward,
    decimals
  );
  const target2 = liveRoundPrice(
    normalizedDirection === "BUY"
      ? roundedEntry + roundedRisk * 3
      : roundedEntry - roundedRisk * 3,
    decimals
  );
  const target3 = liveRoundPrice(
    normalizedDirection === "BUY"
      ? roundedEntry + roundedRisk * 4
      : roundedEntry - roundedRisk * 4,
    decimals
  );

  const opposingBarrier = normalizedDirection === "BUY"
    ? nearestResistance
    : nearestSupport;
  const barrierDistance =
    Number.isFinite(opposingBarrier) &&
    (normalizedDirection === "BUY"
      ? opposingBarrier > roundedEntry
      : opposingBarrier < roundedEntry)
      ? Math.abs(opposingBarrier - roundedEntry)
      : null;
  const barrierR =
    Number.isFinite(barrierDistance) && roundedRisk > 0
      ? barrierDistance / roundedRisk
      : null;

  const actualReward1 = Math.abs(target1 - roundedEntry);
  const riskReward = actualReward1 / roundedRisk;

  if (
    !Number.isFinite(riskReward) ||
    riskReward + 1e-9 < config.minimumRiskReward
  ) {
    return null;
  }

  const roundedAtr = liveRoundPrice(currentAtr, decimals);

  return {
    direction: normalizedDirection,
    entry: roundedEntry,
    entryPrice: roundedEntry,
    stop: roundedStop,
    stopLoss: roundedStop,
    sl: roundedStop,
    target1,
    target2,
    target3,
    takeProfit1: target1,
    takeProfit2: target2,
    takeProfit3: target3,
    tp1: target1,
    tp2: target2,
    tp3: target3,
    risk: liveRoundPrice(roundedRisk, decimals),
    reward: liveRoundPrice(actualReward1, decimals),
    riskReward: Number(riskReward.toFixed(2)),
    rr: Number(riskReward.toFixed(2)),
    atr: roundedAtr,
    model: "ATR_REGIME_STRUCTURE",
    timeframe: timeframeKey,
    professionalPipelineVersion: PROFESSIONAL_LIVE_PIPELINE_VERSION,
    riskDiagnostics: {
      baseStopAtr: config.baseStopAtr,
      maximumStopAtr: config.maximumStopAtr,
      pairModifier,
      atrRegime:
        atrSnapshot && atrSnapshot.regime
          ? atrSnapshot.regime
          : "UNKNOWN",
      regimeStopFactor: regimeFactor,
      stopDistance: professionalLiveRound(stopDistance, decimals),
      stopDistanceAtr: professionalLiveRound(stopDistance / currentAtr, 4),
      selectedStructureLevel,
      structureDistance,
      structureUsed,
      opposingBarrier:
        Number.isFinite(opposingBarrier)
          ? opposingBarrier
          : null,
      barrierR:
        Number.isFinite(barrierR)
          ? professionalLiveRound(barrierR, 4)
          : null,
      minimumBarrierR: config.minimumBarrierR,
    },
  };
}


// ---------------------------------------------------------------------------
// Single-timeframe analysis
// ---------------------------------------------------------------------------
function analyzeLiveTimeframe(
  rows,
  options = {}
) {
  const pair =
    options.pair ||
    options.symbol ||
    "UNKNOWN";
  const timeframe =
    options.timeframe ||
    "H1";
  const timeframeKey =
    professionalLiveTimeframeKey(timeframe);
  const config =
    professionalLiveConfigFor(timeframeKey);
  const nowMs =
    candleNumber(
      options.nowMs,
      Date.now()
    );
  const closedResult =
    professionalLiveClosedRows(
      rows,
      timeframeKey,
      nowMs
    );
  let normalizedRows =
    closedResult.rows;
  const maxRows = Math.max(
    0,
    candleInteger(
      options.maxRows,
      2000
    ) || 0
  );

  if (
    maxRows > 0 &&
    normalizedRows.length > maxRows
  ) {
    normalizedRows =
      normalizedRows.slice(-maxRows);
  }

  const steps = [];
  const minimumCandles = Math.max(
    config.minimumCandles,
    candleInteger(
      options.minimumCandles,
      config.minimumCandles
    )
  );
  const enoughData =
    normalizedRows.length >=
    minimumCandles;

  steps.push(
    livePipelineStep(
      "Data Availability",
      enoughData ? "pass" : "fail",
      `${normalizedRows.length} completed ${timeframeKey} candles available; minimum ${minimumCandles}`,
      {
        candleCount:
          normalizedRows.length,
        minimumCandles,
      }
    )
  );

  const integrity =
    closedResult.diagnostics;
  const integrityPassed =
    integrity.formingRemoved >= 0 &&
    integrity.explicitOpenRemoved >= 0 &&
    integrity.closedRows ===
      normalizedRows.length ||
    maxRows > 0;

  steps.push(
    livePipelineStep(
      "Closed Candle Integrity",
      integrityPassed
        ? "pass"
        : "fail",
      `Closed candles ${integrity.closedRows}; forming removed ${integrity.formingRemoved}; explicit open removed ${integrity.explicitOpenRemoved}; continuity ${(candleNumber(integrity.continuityRatio, 0) * 100).toFixed(1)}%`,
      {
        ...integrity,
      }
    )
  );

  if (!enoughData) {
    const latest =
      normalizedRows[
        normalizedRows.length - 1
      ] || null;

    return {
      pair,
      timeframe,
      professionalTimeframe:
        timeframeKey,
      professionalPipelineVersion:
        PROFESSIONAL_LIVE_PIPELINE_VERSION,
      engineVersion:
        ENGINE_VERSION,
      strategyVersion:
        STRATEGY_VERSION,
      decision: "HOLD",
      signal: "HOLD",
      action: "HOLD",
      direction: "HOLD",
      rawDirection: "NEUTRAL",
      confidence: 0,
      score: 0,
      price:
        latest
          ? latest.close
          : null,
      currentPrice:
        latest
          ? latest.close
          : null,
      lastPrice:
        latest
          ? latest.close
          : null,
      timestamp:
        latest
          ? latest.timestamp
          : null,
      time:
        latest
          ? latest.time
          : null,
      trend: "NEUTRAL",
      trendDirection:
        "NEUTRAL",
      tradePlan: null,
      plan: null,
      steps,
      pipeline: steps,
      candleCount:
        normalizedRows.length,
      reason:
        "Insufficient completed candle history for professional indicator warm-up",
      confluence: {
        qualified: false,
        minimumScore:
          config.minimumScore,
        minimumEdge:
          config.minimumEdge,
      },
      dataQuality:
        integrity,
    };
  }

  const closes =
    liveCloseValues(
      normalizedRows
    );
  const lastCandle =
    normalizedRows[
      normalizedRows.length - 1
    ];
  const currentPrice =
    candleNumber(
      lastCandle.close
    );
  const ema =
    professionalLiveEmaSnapshot(
      normalizedRows
    );
  const rsi =
    professionalLiveRsiSnapshot(
      closes,
      14
    );
  const macd =
    professionalLiveMacdSnapshot(
      closes
    );
  const dmiAdx =
    professionalLiveDmiAdx(
      normalizedRows,
      14
    );
  const atr =
    professionalLiveAtrSnapshot(
      normalizedRows,
      14,
      100
    );
  const structure =
    liveMarketStructure(
      normalizedRows
    );
  const supportResistance =
    liveSupportResistance(
      normalizedRows,
      currentPrice
    );
  const candlePattern =
    professionalLiveCandleSnapshot(
      normalizedRows
    );
  const buyEvidence =
    professionalLiveScoreDirection({
      direction: "BUY",
      ema,
      macd,
      rsi,
      dmiAdx,
      structure,
      candlePattern,
      atr,
    });
  const sellEvidence =
    professionalLiveScoreDirection({
      direction: "SELL",
      ema,
      macd,
      rsi,
      dmiAdx,
      structure,
      candlePattern,
      atr,
    });
  const selection =
    professionalLiveSelectDirection(
      buyEvidence,
      sellEvidence,
      config
    );
  const candidateDirection =
    selection.rawDirection;

  const emaCandidateScore =
    candidateDirection === "BUY"
      ? buyEvidence.components.ema
      : sellEvidence.components.ema;
  const macdCandidateScore =
    candidateDirection === "BUY"
      ? buyEvidence.components.macd
      : sellEvidence.components.macd;
  const rsiCandidateScore =
    candidateDirection === "BUY"
      ? buyEvidence.components.rsi
      : sellEvidence.components.rsi;
  const dmiCandidateScore =
    candidateDirection === "BUY"
      ? buyEvidence.components.dmiAdx
      : sellEvidence.components.dmiAdx;
  const structureCandidateScore =
    candidateDirection === "BUY"
      ? buyEvidence.components.structure
      : sellEvidence.components.structure;
  const candleCandidateScore =
    candidateDirection === "BUY"
      ? buyEvidence.components.candlePattern
      : sellEvidence.components.candlePattern;

  steps.push(
    livePipelineStep(
      "Trend",
      emaCandidateScore >= 14
        ? "pass"
        : emaCandidateScore >= 8
          ? "info"
          : "fail",
      `${ema.reason}; BUY checks ${ema.bullishCount}/4, SELL checks ${ema.bearishCount}/4`,
      {
        direction:
          ema.direction,
        periods:
          ema.periods,
        values:
          ema.values,
        slopes:
          ema.slopes,
        buyScore:
          buyEvidence.components.ema,
        sellScore:
          sellEvidence.components.ema,
      }
    )
  );

  steps.push(
    livePipelineStep(
      "EMA Alignment",
      ema.fullAlignment
        ? "pass"
        : ema.partialAlignment
          ? "info"
          : "fail",
      ema.fullAlignment
        ? `Full ${ema.direction} EMA stack confirmed`
        : ema.partialAlignment
          ? `Partial ${ema.direction} EMA alignment retained as weighted evidence`
          : "EMA stack is mixed; other indicators remain independently evaluated",
      {
        fullAlignment:
          ema.fullAlignment,
        partialAlignment:
          ema.partialAlignment,
        bullishCount:
          ema.bullishCount,
        bearishCount:
          ema.bearishCount,
      }
    )
  );

  steps.push(
    livePipelineStep(
      "MACD Confirmation",
      macdCandidateScore >= 10
        ? "pass"
        : macdCandidateScore > 0
          ? "info"
          : "fail",
      macd.available
        ? `MACD ${professionalLiveRound(macd.macd, 6)} vs signal ${professionalLiveRound(macd.signal, 6)}; histogram ${professionalLiveRound(macd.histogram, 6)}; slope ${professionalLiveRound(macd.histogramSlope, 6)}`
        : "MACD unavailable after standard warm-up",
      {
        macd:
          macd.macd,
        signal:
          macd.signal,
        histogram:
          macd.histogram,
        previousHistogram:
          macd.previousHistogram,
        histogramSlope:
          macd.histogramSlope,
        crossedBullish:
          macd.crossedBullish,
        crossedBearish:
          macd.crossedBearish,
        buyScore:
          buyEvidence.components.macd,
        sellScore:
          sellEvidence.components.macd,
      }
    )
  );

  steps.push(
    livePipelineStep(
      "RSI Confirmation",
      rsiCandidateScore >= 10
        ? "pass"
        : rsiCandidateScore > 0
          ? "info"
          : "fail",
      rsi.available
        ? `RSI ${professionalLiveRound(rsi.current, 2)}; previous ${professionalLiveRound(rsi.previous, 2)}; slope ${professionalLiveRound(rsi.slope, 2)}; regime ${rsi.regime}`
        : "RSI unavailable after Wilder warm-up",
      {
        rsi:
          rsi.current,
        previousRsi:
          rsi.previous,
        slope:
          rsi.slope,
        momentum3:
          rsi.momentum3,
        crossedAbove50:
          rsi.crossedAbove50,
        crossedBelow50:
          rsi.crossedBelow50,
        regime:
          rsi.regime,
        buyScore:
          buyEvidence.components.rsi,
        sellScore:
          sellEvidence.components.rsi,
      }
    )
  );

  steps.push(
    livePipelineStep(
      "ADX > 25?",
      dmiCandidateScore >= 10
        ? "pass"
        : dmiCandidateScore > 0
          ? "info"
          : "fail",
      dmiAdx.available
        ? `ADX ${professionalLiveRound(dmiAdx.adx, 2)} (${dmiAdx.regime}); +DI ${professionalLiveRound(dmiAdx.plusDI, 2)}, -DI ${professionalLiveRound(dmiAdx.minusDI, 2)}, slope ${professionalLiveRound(dmiAdx.adxSlope, 2)}`
        : "ADX/DMI unavailable after Wilder warm-up",
      {
        adx:
          dmiAdx.adx,
        previousAdx:
          dmiAdx.previousAdx,
        adxSlope:
          dmiAdx.adxSlope,
        plusDI:
          dmiAdx.plusDI,
        minusDI:
          dmiAdx.minusDI,
        direction:
          dmiAdx.direction,
        regime:
          dmiAdx.regime,
        buyScore:
          buyEvidence.components.dmiAdx,
        sellScore:
          sellEvidence.components.dmiAdx,
      }
    )
  );

  const hasMeaningfulVolume =
    normalizedRows.some(
      row =>
        candleNumber(
          row.volume,
          0
        ) > 0
    );

  steps.push(
    livePipelineStep(
      "Volume Confirmed?",
      hasMeaningfulVolume
        ? "info"
        : "na",
      hasMeaningfulVolume
        ? "Volume/tick-volume data is present and retained as context; it is not treated as centralized exchange volume"
        : "Reliable centralized volume is unavailable"
    )
  );

  steps.push(
    livePipelineStep(
      "Market Structure",
      structureCandidateScore >= 10
        ? "pass"
        : structure.direction === "NEUTRAL"
          ? "info"
          : "fail",
      structure.label,
      {
        direction:
          structure.direction,
        score:
          structure.score,
        buyScore:
          buyEvidence.components.structure,
        sellScore:
          sellEvidence.components.structure,
      }
    )
  );

  steps.push(
    livePipelineStep(
      "Candle Pattern",
      candleCandidateScore >= 4
        ? "pass"
        : candleCandidateScore > 0
          ? "info"
          : "na",
      candidateDirection === "BUY"
        ? candlePattern.buy.detail
        : candlePattern.sell.detail,
      {
        direction:
          candlePattern.candleDirection,
        bodyRatio:
          candlePattern.bodyRatio,
        bullishConfirmed:
          candlePattern.buy.confirmed,
        bearishConfirmed:
          candlePattern.sell.confirmed,
        buyScore:
          buyEvidence.components.candlePattern,
        sellScore:
          sellEvidence.components.candlePattern,
      }
    )
  );

  const hardBlocks = [];

  if (atr.available !== true) {
    hardBlocks.push(
      "ATR unavailable"
    );
  }

  if (atr.hardBlock === true) {
    hardBlocks.push(
      "Extreme ATR volatility regime"
    );
  }

  if (
    options.sourceStale === true
  ) {
    hardBlocks.push(
      "Source data is marked stale"
    );
  }

  steps.push(
    livePipelineStep(
      "ATR-style Stop Loss",
      atr.available !== true ||
      atr.hardBlock === true
        ? "fail"
        : "pass",
      atr.available
        ? `ATR ${professionalLiveRound(atr.current, livePairPriceDecimals(pair))}; ${professionalLiveRound(atr.atrPercent, 4)}% of price; percentile ${professionalLiveRound(atr.percentile, 2)}; regime ${atr.regime}; median ratio ${professionalLiveRound(atr.medianRatio, 3)}`
        : "ATR unavailable",
      {
        atr:
          atr.current,
        previousAtr:
          atr.previous,
        atrSlope:
          atr.slope,
        atrPercent:
          atr.atrPercent,
        percentile:
          atr.percentile,
        median:
          atr.median,
        medianRatio:
          atr.medianRatio,
        regime:
          atr.regime,
        hardBlock:
          atr.hardBlock,
      }
    )
  );

  steps.push(
    livePipelineStep(
      "Confluence Score",
      selection.qualified
        ? "pass"
        : "fail",
      `${selection.reason}; BUY ${buyEvidence.score}, SELL ${sellEvidence.score}`,
      {
        buyScore:
          buyEvidence.score,
        sellScore:
          sellEvidence.score,
        winningScore:
          selection.winningScore,
        edge:
          selection.edge,
        minimumScore:
          selection.minimumScore,
        minimumEdge:
          selection.minimumEdge,
      }
    )
  );

  let preliminaryDecision =
    selection.qualified &&
    hardBlocks.length === 0
      ? selection.direction
      : "HOLD";
  let tradePlan =
    preliminaryDecision !== "HOLD"
      ? buildLiveTradePlan({
          direction:
            preliminaryDecision,
          price:
            currentPrice,
          atr:
            atr.current,
          atrSnapshot:
            atr,
          supportResistance,
          pair,
          timeframe:
            timeframeKey,
          rows:
            normalizedRows,
        })
      : null;
  let finalDecision =
    preliminaryDecision;

  if (
    preliminaryDecision !== "HOLD" &&
    !tradePlan
  ) {
    finalDecision = "HOLD";
    hardBlocks.push(
      "Professional ATR/structure trade-plan geometry failed"
    );
  }

  const approximateBaseRisk =
    atr.available
      ? atr.current *
        config.baseStopAtr *
        professionalLivePairAtrModifier(pair) *
        atr.regimeStopFactor
      : null;
  const confirmedSwingLevels =
    professionalLiveConfirmedSwingLevels(
      normalizedRows
    );
  const opposingBarrier =
    candidateDirection === "BUY"
      ? confirmedSwingLevels.highs
          .filter(level => level > currentPrice)
          .sort((left, right) => left - right)[0] ?? null
      : confirmedSwingLevels.lows
          .filter(level => level < currentPrice)
          .sort((left, right) => right - left)[0] ?? null;
  const barrierDistance =
    Number.isFinite(opposingBarrier) &&
    Number.isFinite(currentPrice) &&
    (candidateDirection === "BUY"
      ? opposingBarrier > currentPrice
      : opposingBarrier < currentPrice)
      ? Math.abs(opposingBarrier - currentPrice)
      : null;
  const approximateBarrierR =
    Number.isFinite(barrierDistance) &&
    Number.isFinite(approximateBaseRisk) &&
    approximateBaseRisk > 0
      ? barrierDistance / approximateBaseRisk
      : null;

  steps.push(
    livePipelineStep(
      "Support/Resistance",
      Number.isFinite(approximateBarrierR) &&
      approximateBarrierR < config.minimumBarrierR
        ? "info"
        : "pass",
      !Number.isFinite(opposingBarrier)
        ? "No confirmed opposing swing level was identified"
        : Number.isFinite(approximateBarrierR) &&
          approximateBarrierR < config.minimumBarrierR
          ? `${candidateDirection === "BUY" ? "Resistance" : "Support"} ${professionalLiveRound(opposingBarrier, livePairPriceDecimals(pair))} is nearby at approximately ${professionalLiveRound(approximateBarrierR, 2)}R; retained as a caution, not a hard blocker`
          : `${candidateDirection === "BUY" ? "Resistance" : "Support"} ${professionalLiveRound(opposingBarrier, livePairPriceDecimals(pair))}; approximate room ${professionalLiveRound(approximateBarrierR, 2)}R`,
      {
        level:
          Number.isFinite(opposingBarrier)
            ? opposingBarrier
            : null,
        approximateBarrierR,
        minimumBarrierR:
          config.minimumBarrierR,
        supports:
          supportResistance.supports,
        resistances:
          supportResistance.resistances,
      }
    )
  );

  if (finalDecision === "HOLD") {
    steps.push(
      livePipelineStep(
        "Trade Plan + Risk:Reward",
        selection.qualified &&
        hardBlocks.length > 0
          ? "fail"
          : "skip",
        hardBlocks.length > 0
          ? hardBlocks.join("; ")
          : "No trade plan because professional confluence thresholds were not met"
      )
    );
  } else {
    steps.push(
      livePipelineStep(
        "Trade Plan + Risk:Reward",
        "pass",
        `ATR/structure plan passed at ${tradePlan.riskReward.toFixed(2)}R; stop ${tradePlan.riskDiagnostics.stopDistanceAtr} ATR`,
        {
          riskReward:
            tradePlan.riskReward,
          model:
            tradePlan.model,
          riskDiagnostics:
            tradePlan.riskDiagnostics,
        }
      )
    );
  }

  const confidence =
    finalDecision === "HOLD"
      ? professionalLiveClamp(
          Math.round(
            selection.winningScore * 0.65
          ),
          0,
          69
        )
      : professionalLiveClamp(
          Math.round(
            55 +
            (selection.winningScore - config.minimumScore) * 0.75 +
            selection.edge * 0.45
          ),
          55,
          97
        );
  const signedScore =
    finalDecision === "BUY"
      ? Math.round(selection.winningScore)
      : finalDecision === "SELL"
        ? -Math.round(selection.winningScore)
        : Math.round(
            buyEvidence.score -
            sellEvidence.score
          );
  const reason =
    finalDecision !== "HOLD"
      ? `${finalDecision} setup confirmed by professional multi-indicator confluence and ATR risk validation`
      : hardBlocks.length > 0
        ? hardBlocks.join("; ")
        : selection.reason;
  const tradePlanOutput =
    finalDecision !== "HOLD"
      ? tradePlan
      : null;
  const marketRegime =
    `${dmiAdx.regime || "UNKNOWN"}_${atr.regime || "UNKNOWN"}`;

  return {
    pair,
    timeframe,
    professionalTimeframe:
      timeframeKey,
    professionalPipelineVersion:
      PROFESSIONAL_LIVE_PIPELINE_VERSION,
    engineVersion:
      ENGINE_VERSION,
    strategyVersion:
      STRATEGY_VERSION,
    decision:
      finalDecision,
    signal:
      finalDecision,
    action:
      finalDecision,
    direction:
      finalDecision,
    rawDirection:
      candidateDirection,
    trend:
      ema.direction,
    trendDirection:
      ema.direction,
    confidence,
    score:
      signedScore,
    price:
      currentPrice,
    currentPrice,
    lastPrice:
      currentPrice,
    timestamp:
      lastCandle.timestamp,
    time:
      lastCandle.time,
    generatedAt:
      lastCandle.time,
    candleCount:
      normalizedRows.length,
    marketRegime,
    indicators: {
      rsi:
        rsi.current,
      rsiPrevious:
        rsi.previous,
      rsiSlope:
        rsi.slope,
      rsiRegime:
        rsi.regime,
      macd:
        macd.macd,
      macdSignal:
        macd.signal,
      macdHistogram:
        macd.histogram,
      macdHistogramSlope:
        macd.histogramSlope,
      atr:
        atr.current,
      atrPrevious:
        atr.previous,
      atrSlope:
        atr.slope,
      atrPercent:
        atr.atrPercent,
      atrPercentile:
        atr.percentile,
      atrMedianRatio:
        atr.medianRatio,
      atrRegime:
        atr.regime,
      adx:
        dmiAdx.adx,
      adxPrevious:
        dmiAdx.previousAdx,
      adxSlope:
        dmiAdx.adxSlope,
      plusDI:
        dmiAdx.plusDI,
      minusDI:
        dmiAdx.minusDI,
      ema20:
        ema.values.ema20,
      ema50:
        ema.values.ema50,
      ema100:
        ema.values.ema100,
      ema200:
        ema.values.ema200,
      ema20Slope:
        ema.slopes.ema20,
      ema50Slope:
        ema.slopes.ema50,
    },
    rsi:
      rsi.current,
    macd:
      macd.macd,
    macdSignal:
      macd.signal,
    macdHistogram:
      macd.histogram,
    atr:
      atr.current,
    adx:
      dmiAdx.adx,
    plusDI:
      dmiAdx.plusDI,
    minusDI:
      dmiAdx.minusDI,
    ema20:
      ema.values.ema20,
    ema50:
      ema.values.ema50,
    ema100:
      ema.values.ema100,
    ema200:
      ema.values.ema200,
    marketStructure:
      structure,
    structure,
    supportResistance,
    supports:
      supportResistance.supports,
    resistances:
      supportResistance.resistances,
    nearestSupport:
      supportResistance.nearestSupport,
    nearestResistance:
      supportResistance.nearestResistance,
    tradePlan:
      tradePlanOutput,
    plan:
      tradePlanOutput,
    entry:
      tradePlanOutput
        ? tradePlanOutput.entry
        : null,
    stop:
      tradePlanOutput
        ? tradePlanOutput.stop
        : null,
    stopLoss:
      tradePlanOutput
        ? tradePlanOutput.stopLoss
        : null,
    target1:
      tradePlanOutput
        ? tradePlanOutput.target1
        : null,
    target2:
      tradePlanOutput
        ? tradePlanOutput.target2
        : null,
    target3:
      tradePlanOutput
        ? tradePlanOutput.target3
        : null,
    tp1:
      tradePlanOutput
        ? tradePlanOutput.tp1
        : null,
    tp2:
      tradePlanOutput
        ? tradePlanOutput.tp2
        : null,
    tp3:
      tradePlanOutput
        ? tradePlanOutput.tp3
        : null,
    riskReward:
      tradePlanOutput
        ? tradePlanOutput.riskReward
        : null,
    rr:
      tradePlanOutput
        ? tradePlanOutput.rr
        : null,
    reason,
    steps,
    pipeline: steps,
    indicatorSnapshot: {
      ema,
      macd: {
        available:
          macd.available,
        macd:
          macd.macd,
        signal:
          macd.signal,
        histogram:
          macd.histogram,
        previousHistogram:
          macd.previousHistogram,
        histogramSlope:
          macd.histogramSlope,
        crossedBullish:
          macd.crossedBullish,
        crossedBearish:
          macd.crossedBearish,
      },
      rsi: {
        available:
          rsi.available,
        period:
          rsi.period,
        current:
          rsi.current,
        previous:
          rsi.previous,
        slope:
          rsi.slope,
        momentum3:
          rsi.momentum3,
        crossedAbove50:
          rsi.crossedAbove50,
        crossedBelow50:
          rsi.crossedBelow50,
        regime:
          rsi.regime,
      },
      dmiAdx: {
        available:
          dmiAdx.available,
        period:
          dmiAdx.period,
        adx:
          dmiAdx.adx,
        previousAdx:
          dmiAdx.previousAdx,
        adxSlope:
          dmiAdx.adxSlope,
        plusDI:
          dmiAdx.plusDI,
        minusDI:
          dmiAdx.minusDI,
        direction:
          dmiAdx.direction,
        regime:
          dmiAdx.regime,
      },
      atr: {
        available:
          atr.available,
        period:
          atr.period,
        current:
          atr.current,
        previous:
          atr.previous,
        slope:
          atr.slope,
        atrPercent:
          atr.atrPercent,
        percentile:
          atr.percentile,
        median:
          atr.median,
        medianRatio:
          atr.medianRatio,
        regime:
          atr.regime,
        hardBlock:
          atr.hardBlock,
      },
      structure,
      candlePattern,
    },
    confluence: {
      version:
        PROFESSIONAL_LIVE_PIPELINE_VERSION,
      qualified:
        finalDecision !== "HOLD",
      selectedDirection:
        finalDecision,
      rawDirection:
        candidateDirection,
      buy:
        buyEvidence,
      sell:
        sellEvidence,
      winningScore:
        selection.winningScore,
      losingScore:
        selection.losingScore,
      edge:
        selection.edge,
      minimumScore:
        selection.minimumScore,
      minimumEdge:
        selection.minimumEdge,
      hardBlocks,
    },
    riskDiagnostics:
      tradePlanOutput
        ? tradePlanOutput.riskDiagnostics
        : {
            model:
              "ATR_REGIME_STRUCTURE",
            atrRegime:
              atr.regime,
            atrHardBlock:
              atr.hardBlock,
            approximateBarrierR,
            minimumBarrierR:
              config.minimumBarrierR,
          },
    dataQuality:
      integrity,
    diagnostics: {
      requiredSteps:
        steps.filter(
          step =>
            step.status === "pass" ||
            step.status === "fail"
        ).length,
      passedRequiredSteps:
        steps.filter(
          step =>
            step.status === "pass"
        ).length,
      failedRequiredSteps:
        steps.filter(
          step =>
            step.status === "fail"
        ).length,
      confirmationRatio:
        professionalLiveRound(
          steps.filter(step => step.status === "pass").length /
          Math.max(
            1,
            steps.filter(
              step =>
                step.status === "pass" ||
                step.status === "fail"
            ).length
          ),
          4
        ),
    },
  };
}


// ---------------------------------------------------------------------------
// Multi-timeframe confirmation
// ---------------------------------------------------------------------------
function applyLiveHigherTimeframeConfirmation(
  lowerAnalysis,
  higherAnalysis,
  options = {}
) {
  const lower =
    lowerAnalysis &&
    typeof lowerAnalysis === "object"
      ? {
          ...lowerAnalysis,
        }
      : null;

  if (!lower) {
    return lowerAnalysis;
  }

  const higher =
    higherAnalysis &&
    typeof higherAnalysis === "object"
      ? higherAnalysis
      : null;
  const steps =
    Array.isArray(lower.steps)
      ? [
          ...lower.steps,
        ]
      : [];
  const higherTimeframe =
    options.higherTimeframe ||
    (higher && higher.timeframe) ||
    null;

  if (!higher) {
    steps.push(
      livePipelineStep(
        "Multi-Timeframe Confirmation",
        "na",
        "Higher-timeframe analysis unavailable"
      )
    );

    lower.steps = steps;
    lower.pipeline = steps;
    lower.mtfConfirmed = null;

    return lower;
  }

  const lowerDecision =
    normalizePipelineDecision(
      lower.decision ||
      lower.signal
    );
  const higherDecision =
    normalizePipelineDecision(
      higher.decision ||
      higher.signal
    );
  const higherRawDirection =
    normalizePipelineDecision(
      higher.rawDirection ||
      higher.trendDirection ||
      higher.trend
    );
  const higherDirection =
    higherDecision !== "HOLD"
      ? higherDecision
      : higherRawDirection;
  const higherWinningScore =
    candleNumber(
      higher.confluence &&
      higher.confluence.winningScore,
      Math.abs(
        candleNumber(
          higher.score,
          0
        )
      )
    );
  const higherAdx =
    candleNumber(
      higher.indicators &&
      higher.indicators.adx,
      candleNumber(
        higher.adx
      )
    );
  const higherFullEma =
    Boolean(
      higher.indicatorSnapshot &&
      higher.indicatorSnapshot.ema &&
      higher.indicatorSnapshot.ema.fullAlignment
    );

  lower.higherTimeframe = {
    timeframe:
      higherTimeframe,
    decision:
      higherDecision,
    direction:
      higherDirection,
    confidence:
      candleNumber(
        higher.confidence,
        0
      ),
    winningScore:
      higherWinningScore,
    adx:
      higherAdx,
  };

  if (lowerDecision === "HOLD") {
    steps.push(
      livePipelineStep(
        "Multi-Timeframe Confirmation",
        "info",
        `Lower timeframe has no qualified setup; ${higherTimeframe || "higher timeframe"} bias is ${higherDirection}`,
        {
          higherTimeframe,
          higherDecision,
          higherDirection,
          higherWinningScore,
          higherAdx,
        }
      )
    );

    lower.steps = steps;
    lower.pipeline = steps;
    lower.mtfConfirmed = null;

    return lower;
  }

  if (
    higherDirection === "HOLD" ||
    higherDirection === "NEUTRAL"
  ) {
    steps.push(
      livePipelineStep(
        "Multi-Timeframe Confirmation",
        "info",
        `${higherTimeframe || "Higher timeframe"} is neutral; lower-timeframe setup remains valid without a confirmation bonus`,
        {
          higherTimeframe,
          higherDecision,
          higherDirection,
          higherWinningScore,
          higherAdx,
        }
      )
    );

    lower.steps = steps;
    lower.pipeline = steps;
    lower.mtfConfirmed = false;

    return lower;
  }

  const confirmed =
    higherDirection ===
    lowerDecision;

  if (confirmed) {
    steps.push(
      livePipelineStep(
        "Multi-Timeframe Confirmation",
        "pass",
        `${higherTimeframe || "Higher timeframe"} confirms ${lowerDecision}`,
        {
          higherTimeframe,
          higherDecision,
          higherDirection,
          higherWinningScore,
          higherAdx,
        }
      )
    );

    lower.confidence =
      professionalLiveClamp(
        candleInteger(
          lower.confidence,
          0
        ) + 5,
        0,
        99
      );

    if (
      lower.confluence &&
      typeof lower.confluence === "object"
    ) {
      lower.confluence = {
        ...lower.confluence,
        higherTimeframe: {
          timeframe:
            higherTimeframe,
          status:
            "CONFIRMED",
          direction:
            higherDirection,
          score:
            higherWinningScore,
          adx:
            higherAdx,
          confidenceBonus:
            5,
        },
      };
    }

    lower.steps = steps;
    lower.pipeline = steps;
    lower.mtfConfirmed = true;

    return lower;
  }

  const strongConflict =
    (
      higherDecision ===
      higherDirection &&
      higherDecision !== "HOLD" &&
      candleNumber(
        higher.confidence,
        0
      ) >= 60
    ) ||
    (
      higherWinningScore >= 65 &&
      Number.isFinite(higherAdx) &&
      higherAdx >= 20
    ) ||
    (
      higherFullEma &&
      higherWinningScore >= 60
    );

  steps.push(
    livePipelineStep(
      "Multi-Timeframe Confirmation",
      strongConflict
        ? "fail"
        : "info",
      strongConflict
        ? `${higherTimeframe || "Higher timeframe"} has a strong ${higherDirection} conflict; ${lowerDecision} setup blocked`
        : `${higherTimeframe || "Higher timeframe"} has a weak ${higherDirection} lean; ${lowerDecision} setup retained with lower confidence`,
      {
        higherTimeframe,
        higherDecision,
        higherDirection,
        higherWinningScore,
        higherAdx,
        strongConflict,
      }
    )
  );

  if (strongConflict) {
    lower.decision = "HOLD";
    lower.signal = "HOLD";
    lower.action = "HOLD";
    lower.direction = "HOLD";
    lower.tradePlan = null;
    lower.plan = null;
    lower.entry = null;
    lower.stop = null;
    lower.stopLoss = null;
    lower.target1 = null;
    lower.target2 = null;
    lower.target3 = null;
    lower.tp1 = null;
    lower.tp2 = null;
    lower.tp3 = null;
    lower.riskReward = null;
    lower.rr = null;
    lower.confidence = Math.min(
      candleInteger(
        lower.confidence,
        0
      ),
      59
    );
    lower.reason =
      "Strong higher-timeframe conflict blocked the lower-timeframe setup";

    if (
      lower.confluence &&
      typeof lower.confluence === "object"
    ) {
      lower.confluence = {
        ...lower.confluence,
        qualified: false,
        selectedDirection: "HOLD",
        hardBlocks: [
          ...(
            Array.isArray(
              lower.confluence.hardBlocks
            )
              ? lower.confluence.hardBlocks
              : []
          ),
          "Strong higher-timeframe conflict",
        ],
        higherTimeframe: {
          timeframe:
            higherTimeframe,
          status:
            "BLOCKED",
          direction:
            higherDirection,
          score:
            higherWinningScore,
          adx:
            higherAdx,
        },
      };
    }
  } else {
    lower.confidence =
      professionalLiveClamp(
        candleInteger(
          lower.confidence,
          0
        ) - 8,
        0,
        99
      );

    if (
      lower.confluence &&
      typeof lower.confluence === "object"
    ) {
      lower.confluence = {
        ...lower.confluence,
        higherTimeframe: {
          timeframe:
            higherTimeframe,
          status:
            "CAUTION",
          direction:
            higherDirection,
          score:
            higherWinningScore,
          adx:
            higherAdx,
          confidenceAdjustment:
            -8,
        },
      };
    }
  }

  lower.steps = steps;
  lower.pipeline = steps;
  lower.mtfConfirmed = false;

  return lower;
}


// ---------------------------------------------------------------------------
// Legacy-compatible complete analysis pipeline
// ---------------------------------------------------------------------------

function runLegacyCompatibleAnalysisPipeline(
  input = {}
) {
  const pair =
    input.pair ||
    input.symbol ||
    input.pairLabel ||
    "UNKNOWN";
  const nowMs =
    candleNumber(
      input.nowMs,
      Date.now()
    );
  const frames =
    input.frames &&
    typeof input.frames === "object"
      ? input.frames
      : prepareLiveAnalysisFrames({
          ...input,
          nowMs,
        });

  const weeklyAnalysis =
    analyzeLiveTimeframe(
      frames.weekly || [],
      {
        pair,
        timeframe: "W1",
        nowMs,
        maxRows:
          input.maxWeeklyAnalysisRows ||
          300,
        sourceStale:
          input.weeklySourceStale === true,
      }
    );

  const dailyBase =
    analyzeLiveTimeframe(
      frames.daily || [],
      {
        pair,
        timeframe: "D1",
        nowMs,
        maxRows:
          input.maxDailyAnalysisRows ||
          600,
        sourceStale:
          input.dailySourceStale === true,
      }
    );

  const dailyAnalysis =
    frames.weekly &&
    frames.weekly.length > 0
      ? applyLiveHigherTimeframeConfirmation(
          dailyBase,
          weeklyAnalysis,
          {
            higherTimeframe: "W1",
          }
        )
      : dailyBase;

  const intradayBase =
    analyzeLiveTimeframe(
      frames.intraday || [],
      {
        pair,
        timeframe: "H1",
        nowMs,
        maxRows:
          input.maxIntradayAnalysisRows ||
          1000,
        sourceStale:
          input.intradaySourceStale === true ||
          input.h1SourceStale === true,
      }
    );

  const intradayAnalysis =
    frames.daily &&
    frames.daily.length > 0
      ? applyLiveHigherTimeframeConfirmation(
          intradayBase,
          dailyAnalysis,
          {
            higherTimeframe: "D1",
          }
        )
      : intradayBase;

  const scalpAnalysis =
    analyzeLiveTimeframe(
      frames.scalp || [],
      {
        pair,
        timeframe:
          input.scalpTimeframe ||
          input.timeframe ||
          "M5",
        nowMs,
        maxRows:
          input.maxScalpAnalysisRows ||
          1200,
        sourceStale:
          input.scalpSourceStale === true,
      }
    );

  const confirmedScalpAnalysis =
    frames.intraday &&
    frames.intraday.length > 0
      ? applyLiveHigherTimeframeConfirmation(
          scalpAnalysis,
          intradayAnalysis,
          {
            higherTimeframe: "H1",
          }
        )
      : scalpAnalysis;

  return {
    pair,
    generatedAt:
      new Date(nowMs).toISOString(),
    timestamp:
      nowMs,
    professionalPipelineVersion:
      PROFESSIONAL_LIVE_PIPELINE_VERSION,
    scalp:
      confirmedScalpAnalysis,
    intraday:
      intradayAnalysis,
    daily:
      dailyAnalysis,
    weekly:
      weeklyAnalysis,
    analyses: {
      scalp:
        confirmedScalpAnalysis,
      intraday:
        intradayAnalysis,
      daily:
        dailyAnalysis,
      weekly:
        weeklyAnalysis,
    },
    frames: {
      scalp:
        frames.scalp || [],
      intraday:
        frames.intraday || [],
      daily:
        frames.daily || [],
      weekly:
        frames.weekly || [],
    },
    frameMetadata:
      frames.metadata &&
      typeof frames.metadata === "object"
        ? frames.metadata
        : {
            scalpCount:
              Array.isArray(frames.scalp)
                ? frames.scalp.length
                : 0,
            intradayCount:
              Array.isArray(frames.intraday)
                ? frames.intraday.length
                : 0,
            dailyCount:
              Array.isArray(frames.daily)
                ? frames.daily.length
                : 0,
            weeklyCount:
              Array.isArray(frames.weekly)
                ? frames.weekly.length
                : 0,
          },
  };
}


// ---------------------------------------------------------------------------
// Legacy analysis aliases
// ---------------------------------------------------------------------------
//
// These wrappers preserve compatibility for callers that use older analysis
// helper names while keeping the revised implementation centralized.
// ---------------------------------------------------------------------------

function aggregateCandles(
  rows,
  timeframe,
  options = {}
) {
  return aggregateLiveCandles(
    rows,
    timeframe,
    options
  );
}

function aggregateToDaily(
  rows,
  options = {}
) {
  return aggregateDailyCandles(
    rows,
    options
  );
}

function aggregateToWeekly(
  rows,
  options = {}
) {
  return aggregateWeeklyCandles(
    rows,
    options
  );
}

function buildWeeklyCandles(
  rows,
  options = {}
) {
  return buildLegacyWeeklyCandles(
    rows,
    options
  );
}

function prepareAnalysisFrames(
  input = {}
) {
  return prepareLiveAnalysisFrames(
    input
  );
}

function analyzeLegacyCompatible(
  rows,
  options = {}
) {
  return analyzeLiveTimeframe(
    rows,
    options
  );
}

function runAnalysisPipeline(
  input = {}
) {
  return runLegacyCompatibleAnalysisPipeline(
    input
  );
}

// ============================================================================
// PART 5 — ENGINE SELECTION + MASTER CONSENSUS
//          + OUTPUT SCHEMA ASSEMBLY + HISTORY/TELEGRAM INTEGRATION
// ============================================================================
//
// This section:
// - Selects revised or legacy-compatible Scalp analysis safely.
// - Preserves data/scalp-signals.json as the primary Scalp source.
// - Uses candle-based Scalp analysis only as fallback.
// - Builds Swing, Intraday, Scalp and Master engine results.
// - Normalizes WAIT, NEUTRAL, NO_TRADE and similar states to HOLD.
// - Preserves common legacy output field aliases.
// - Appends analysis-history.json safely with deduplication.
// - Uses notify-state.json to prevent duplicate Telegram alerts.
// - Preserves Telegram as an optional, non-blocking integration.
// - Does not write live-analysis.json yet; final orchestration is in Part 6.
//
// Required from earlier parts:
// - safe JSON reading/writing helpers from Parts 1–3.
// - pair normalization helpers from Parts 1–3.
// - runLegacyCompatibleAnalysisPipeline() from Part 4.
// - TELEGRAM_TIMEOUT_MS from Part 1.
// ============================================================================


// ---------------------------------------------------------------------------
// Shared compatibility helpers
// ---------------------------------------------------------------------------
function liveIsPlainObject(value) {
  return Boolean(
    value &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function liveAsArray(value) {
  return Array.isArray(value) ? value : [];
}

function liveCloneValue(value) {
  if (value === undefined) {
    return undefined;
  }

  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    return value;
  }
}

function liveFiniteNumber(value, fallback = null) {
  if (value === null || value === undefined || value === "") {
    return fallback;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function liveBoundNumber(value, minimum, maximum, fallback = 0) {
  const parsed = liveFiniteNumber(value, fallback);

  return Math.max(
    minimum,
    Math.min(maximum, parsed)
  );
}

function liveNonEmptyString(value, fallback = "") {
  if (value === null || value === undefined) {
    return fallback;
  }

  const text = String(value).trim();
  return text || fallback;
}

function liveFirstDefined(object, keys, fallback = undefined) {
  if (!liveIsPlainObject(object)) {
    return fallback;
  }

  for (const key of keys) {
    if (
      Object.prototype.hasOwnProperty.call(object, key) &&
      object[key] !== undefined &&
      object[key] !== null &&
      object[key] !== ""
    ) {
      return object[key];
    }
  }

  return fallback;
}

function liveNowIso() {
  return new Date().toISOString();
}

function liveStableTimestamp(value, fallback = Date.now()) {
  if (typeof normalizeTimestampMs === "function") {
    const normalized = normalizeTimestampMs(value);

    if (Number.isFinite(normalized)) {
      return normalized;
    }
  }

  if (value instanceof Date) {
    const time = value.getTime();
    return Number.isFinite(time) ? time : fallback;
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return value < 10_000_000_000
      ? Math.trunc(value * 1000)
      : Math.trunc(value);
  }

  if (typeof value === "string" && value.trim()) {
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }

  return fallback;
}

function liveNormalizePairLabel(value, fallback = "UNKNOWN") {
  if (typeof normalizePairLabel === "function") {
    try {
      const normalized = normalizePairLabel(value);

      if (normalized) {
        return normalized;
      }
    } catch {
      // Continue with local fallback.
    }
  }

  if (typeof normalizePair === "function") {
    try {
      const normalized = normalizePair(value);

      if (normalized) {
        return normalized;
      }
    } catch {
      // Continue with local fallback.
    }
  }

  const raw = liveNonEmptyString(value, fallback)
    .toUpperCase()
    .replace(/\s+/g, "");

  const compact = raw.replace(/[^A-Z0-9]/g, "");

  const aliases = {
    XAUUSD: "XAU/USD",
    GOLD: "XAU/USD",
    GOLDUSD: "XAU/USD",

    GBPJPY: "GBP/JPY",
    GJ: "GBP/JPY",
  };

  if (aliases[compact]) {
    return aliases[compact];
  }

  if (/^[A-Z]{6}$/.test(compact)) {
    return `${compact.slice(0, 3)}/${compact.slice(3)}`;
  }

  return raw || fallback;
}

function liveCompactPair(value) {
  return liveNormalizePairLabel(value)
    .replace(/[^A-Z0-9]/g, "");
}

function liveNormalizeMode(value, fallback = "unknown") {
  const raw = liveNonEmptyString(value, fallback)
    .toLowerCase()
    .replace(/[\s_-]+/g, "");

  const aliases = {
    scalp: "scalp",
    scalping: "scalp",

    intraday: "intraday",
    daytrade: "intraday",
    daytrading: "intraday",
    h1: "intraday",

    swing: "swing",
    daily: "swing",
    d1: "swing",

    weekly: "weekly",
    w1: "weekly",

    master: "master",
    consensus: "master",
  };

  return aliases[raw] || fallback;
}


// ---------------------------------------------------------------------------
// Universal decision normalization
// ---------------------------------------------------------------------------

function normalizeLiveDecision(value) {
  if (typeof normalizePipelineDecision === "function") {
    try {
      return normalizePipelineDecision(value);
    } catch {
      // Continue with local compatibility rules.
    }
  }

  const normalized = liveNonEmptyString(value)
    .toUpperCase()
    .replace(/[\s_-]+/g, "");

  const buyValues = new Set([
    "BUY",
    "LONG",
    "BULL",
    "BULLISH",
    "STRONGBUY",
    "BUYSETUP",
    "UP",
  ]);

  const sellValues = new Set([
    "SELL",
    "SHORT",
    "BEAR",
    "BEARISH",
    "STRONGSELL",
    "SELLSETUP",
    "DOWN",
  ]);

  if (buyValues.has(normalized)) {
    return "BUY";
  }

  if (sellValues.has(normalized)) {
    return "SELL";
  }

  // WAIT, NEUTRAL, NONE, FLAT and unknown states intentionally become HOLD.
  return "HOLD";
}

function liveDecisionScore(decision) {
  const normalized = normalizeLiveDecision(decision);

  if (normalized === "BUY") return 1;
  if (normalized === "SELL") return -1;

  return 0;
}

function liveOppositeDecision(decision) {
  const normalized = normalizeLiveDecision(decision);

  if (normalized === "BUY") return "SELL";
  if (normalized === "SELL") return "BUY";

  return "HOLD";
}


// ---------------------------------------------------------------------------
// Confidence and price extraction
// ---------------------------------------------------------------------------

function liveNormalizeConfidence(value, fallback = 0) {
  let confidence = liveFiniteNumber(value, fallback);

  if (!Number.isFinite(confidence)) {
    confidence = fallback;
  }

  // Accept 0–1 confidence ratios as well as 0–100 percentages.
  if (confidence >= 0 && confidence <= 1) {
    confidence *= 100;
  }

  return Math.round(
    liveBoundNumber(confidence, 0, 100, fallback)
  );
}

function liveExtractDecision(source) {
  if (!liveIsPlainObject(source)) {
    return normalizeLiveDecision(source);
  }

  return normalizeLiveDecision(
    liveFirstDefined(source, [
      "decision",
      "signal",
      "action",
      "direction",
      "recommendation",
      "bias",
      "side",
      "trade",
      "result",
    ])
  );
}

function liveExtractConfidence(source, fallback = 0) {
  if (!liveIsPlainObject(source)) {
    return liveNormalizeConfidence(fallback);
  }

  return liveNormalizeConfidence(
    liveFirstDefined(source, [
      "confidence",
      "confidencePct",
      "confidencePercent",
      "probability",
      "scorePercent",
      "strength",
      "quality",
      "accuracy",
    ]),
    fallback
  );
}

function liveExtractScore(source, fallback = 0) {
  if (!liveIsPlainObject(source)) {
    return liveFiniteNumber(fallback, 0);
  }

  const raw = liveFirstDefined(source, [
    "score",
    "signalScore",
    "weightedScore",
    "netScore",
    "biasScore",
  ]);

  const parsed = liveFiniteNumber(raw);

  if (Number.isFinite(parsed)) {
    return liveBoundNumber(parsed, -100, 100, fallback);
  }

  const decision = liveExtractDecision(source);
  const confidence = liveExtractConfidence(source, fallback);

  return liveDecisionScore(decision) * confidence;
}

function liveExtractPrice(source, fallback = null) {
  if (!liveIsPlainObject(source)) {
    return liveFiniteNumber(source, fallback);
  }

  return liveFiniteNumber(
    liveFirstDefined(source, [
      "price",
      "currentPrice",
      "lastPrice",
      "entry",
      "entryPrice",
      "close",
      "marketPrice",
    ]),
    fallback
  );
}

function liveExtractTimestamp(source, fallback = Date.now()) {
  if (!liveIsPlainObject(source)) {
    return liveStableTimestamp(source, fallback);
  }

  return liveStableTimestamp(
    liveFirstDefined(source, [
      "timestamp",
      "generatedAt",
      "updatedAt",
      "createdAt",
      "time",
      "date",
      "signalTime",
    ]),
    fallback
  );
}


// ---------------------------------------------------------------------------
// Trade-plan normalization
// ---------------------------------------------------------------------------

function normalizeLiveTradePlan(source, pair, decision) {
  if (!liveIsPlainObject(source)) {
    return null;
  }

  const normalizedDecision = normalizeLiveDecision(decision);
  const decimals =
    typeof livePairPriceDecimals === "function"
      ? livePairPriceDecimals(pair)
      : liveCompactPair(pair).endsWith("JPY")
        ? 3
        : liveCompactPair(pair) === "XAUUSD"
          ? 2
          : 5;

  const roundPrice = (value) => {
    const parsed = liveFiniteNumber(value);

    if (!Number.isFinite(parsed)) {
      return null;
    }

    if (typeof liveRoundPrice === "function") {
      return liveRoundPrice(parsed, decimals);
    }

    return Number(parsed.toFixed(decimals));
  };

  const entry = roundPrice(
    liveFirstDefined(source, [
      "entry",
      "entryPrice",
      "price",
      "currentPrice",
    ])
  );

  const stopLoss = roundPrice(
    liveFirstDefined(source, [
      "stopLoss",
      "stop",
      "sl",
      "stop_price",
    ])
  );

  const takeProfit1 = roundPrice(
    liveFirstDefined(source, [
      "takeProfit1",
      "target1",
      "tp1",
      "take_profit_1",
    ])
  );

  const takeProfit2 = roundPrice(
    liveFirstDefined(source, [
      "takeProfit2",
      "target2",
      "tp2",
      "take_profit_2",
    ])
  );

  const takeProfit3 = roundPrice(
    liveFirstDefined(source, [
      "takeProfit3",
      "target3",
      "tp3",
      "take_profit_3",
    ])
  );

  if (
    normalizedDecision === "HOLD" ||
    !Number.isFinite(entry) ||
    !Number.isFinite(stopLoss) ||
    !Number.isFinite(takeProfit1)
  ) {
    return null;
  }

  const primaryGeometryValid =
    normalizedDecision === "BUY"
      ? (
          stopLoss < entry &&
          takeProfit1 > entry
        )
      : (
          stopLoss > entry &&
          takeProfit1 < entry
        );

  const orderedTargets = [
    takeProfit1,
    takeProfit2,
    takeProfit3,
  ].filter(Number.isFinite);

  const optionalTargetsValid =
    orderedTargets.every(
      (target, index) =>
        index === 0 ||
        (
          normalizedDecision === "BUY"
            ? target > orderedTargets[index - 1]
            : target < orderedTargets[index - 1]
        )
    );

  if (
    !primaryGeometryValid ||
    !optionalTargetsValid
  ) {
    return null;
  }

  const calculatedRisk =
    Math.abs(entry - stopLoss);

  const calculatedReward =
    Math.abs(takeProfit1 - entry);

  if (
    calculatedRisk <= 0 ||
    calculatedReward <= 0
  ) {
    return null;
  }

  /*
   * Risk, reward and R:R are derived from the exact normalized prices that
   * downstream consumers receive. Do not retain a supplied R:R calculated
   * from higher-precision values after pair-price rounding has changed the
   * executable geometry.
   */
  const risk =
    Number(
      calculatedRisk.toFixed(
        Math.min(12, decimals + 4)
      )
    );

  const reward =
    Number(
      calculatedReward.toFixed(
        Math.min(12, decimals + 4)
      )
    );

  const riskReward =
    Number(
      (
        calculatedReward /
        calculatedRisk
      ).toFixed(2)
    );

  return {
    direction: normalizedDecision,

    entry,
    entryPrice: entry,

    stop: stopLoss,
    stopLoss,
    sl: stopLoss,

    target1: takeProfit1,
    target2: takeProfit2,
    target3: takeProfit3,

    takeProfit1,
    takeProfit2,
    takeProfit3,

    tp1: takeProfit1,
    tp2: takeProfit2,
    tp3: takeProfit3,

    risk,
    reward,

    riskReward,
    rr: riskReward,

    atr: liveFiniteNumber(source.atr, null),

    model:
      liveNonEmptyString(
        source.model,
        null
      ),

    timeframe:
      liveNonEmptyString(
        source.timeframe,
        null
      ),

    professionalPipelineVersion:
      liveNonEmptyString(
        source.professionalPipelineVersion,
        null
      ),

    riskDiagnostics:
      liveCloneValue(
        source.riskDiagnostics ||
        null
      ),
  };
}

function liveExtractTradePlan(source, pair, decision) {
  if (!liveIsPlainObject(source)) {
    return null;
  }

  const directPlan =
    liveFirstDefined(source, [
      "tradePlan",
      "plan",
      "trade_plan",
      "setup",
    ]);

  if (liveIsPlainObject(directPlan)) {
    return normalizeLiveTradePlan(
      directPlan,
      pair,
      decision
    );
  }

  return normalizeLiveTradePlan(
    source,
    pair,
    decision
  );
}


// ---------------------------------------------------------------------------
// Canonical engine result
// ---------------------------------------------------------------------------

function buildCanonicalEngineResult(
  source,
  options = {}
) {
  const rawSource = liveIsPlainObject(source)
    ? source
    : {};

  const pair = liveNormalizePairLabel(
    options.pair ||
      rawSource.pair ||
      rawSource.symbol ||
      rawSource.pairLabel
  );

  const mode = liveNormalizeMode(
    options.mode ||
      rawSource.mode ||
      rawSource.engine ||
      rawSource.timeframe,
    options.defaultMode || "unknown"
  );

  const engineName = liveNonEmptyString(
    options.engineName ||
      rawSource.engineName ||
      rawSource.engine ||
      rawSource.source,
    mode
  );

  const timeframe =
    normalizeAIMemoryTimeframe(
      firstString(
        options.timeframe,
        rawSource.timeframe,
        rawSource.sourceTimeframe,
        rawSource.tf,
        rawSource.interval
      )
    );

  const timeframeSource =
    liveNonEmptyString(
      options.timeframeSource ||
        rawSource.timeframeSource ||
        (
          timeframe
            ? "source"
            : null
        ),
      null
    );

  let decision = liveExtractDecision(rawSource);
  let confidence = liveExtractConfidence(
    rawSource,
    decision === "HOLD" ? 0 : 50
  );

  let score = liveExtractScore(
    rawSource,
    liveDecisionScore(decision) * confidence
  );

  const price = liveExtractPrice(
    rawSource,
    liveFiniteNumber(options.price, null)
  );

  const timestamp = liveExtractTimestamp(
    rawSource,
    options.timestamp || Date.now()
  );

  const tradePlan = liveExtractTradePlan(
    rawSource,
    pair,
    decision
  );

  if (decision !== "HOLD" && !tradePlan && options.requireTradePlan) {
    decision = "HOLD";
    confidence = Math.min(confidence, 69);
  }

  if (decision === "HOLD") {
    score = liveBoundNumber(score, -69, 69, 0);
  }

  const reason = liveNonEmptyString(
    liveFirstDefined(rawSource, [
      "reason",
      "summary",
      "message",
      "explanation",
      "note",
    ]),
    decision === "HOLD"
      ? "No fully confirmed setup"
      : `${decision} setup confirmed`
  );

  const steps = liveAsArray(
    liveFirstDefined(rawSource, [
      "steps",
      "pipeline",
      "checks",
    ])
  ).map((step) => liveCloneValue(step));

  const canonical = {
    pair,
    symbol: pair,
    pairLabel: pair,

    mode,
    engine: engineName,
    engineName,

    timeframe,
    sourceTimeframe:
      timeframe,

    timeframeSource,

    decision,
    signal: decision,
    action: decision,
    direction: decision,

    confidence,
    confidencePct: confidence,

    score: Number(
      liveBoundNumber(score, -100, 100, 0).toFixed(2)
    ),

    price,
    currentPrice: price,
    lastPrice: price,

    timestamp,
    time: new Date(timestamp).toISOString(),
    generatedAt: new Date(timestamp).toISOString(),

    reason,

    tradePlan:
      decision === "HOLD" ? null : tradePlan,

    plan:
      decision === "HOLD" ? null : tradePlan,

    entry:
      decision !== "HOLD" && tradePlan
        ? tradePlan.entry
        : null,

    entryPrice:
      decision !== "HOLD" && tradePlan
        ? tradePlan.entryPrice
        : null,

    stop:
      decision !== "HOLD" && tradePlan
        ? tradePlan.stop
        : null,

    stopLoss:
      decision !== "HOLD" && tradePlan
        ? tradePlan.stopLoss
        : null,

    sl:
      decision !== "HOLD" && tradePlan
        ? tradePlan.sl
        : null,

    target1:
      decision !== "HOLD" && tradePlan
        ? tradePlan.target1
        : null,

    target2:
      decision !== "HOLD" && tradePlan
        ? tradePlan.target2
        : null,

    target3:
      decision !== "HOLD" && tradePlan
        ? tradePlan.target3
        : null,

    takeProfit1:
      decision !== "HOLD" && tradePlan
        ? tradePlan.takeProfit1
        : null,

    takeProfit2:
      decision !== "HOLD" && tradePlan
        ? tradePlan.takeProfit2
        : null,

    takeProfit3:
      decision !== "HOLD" && tradePlan
        ? tradePlan.takeProfit3
        : null,

    tp1:
      decision !== "HOLD" && tradePlan
        ? tradePlan.tp1
        : null,

    tp2:
      decision !== "HOLD" && tradePlan
        ? tradePlan.tp2
        : null,

    tp3:
      decision !== "HOLD" && tradePlan
        ? tradePlan.tp3
        : null,

    riskReward:
      decision !== "HOLD" && tradePlan
        ? tradePlan.riskReward
        : null,

    rr:
      decision !== "HOLD" && tradePlan
        ? tradePlan.rr
        : null,

    steps,
    pipeline: steps,

    status:
      decision === "HOLD"
        ? "HOLD"
        : "ACTIVE",

    source: liveNonEmptyString(
      options.source ||
        rawSource.source ||
        engineName,
      engineName
    ),

    available:
      options.available !== undefined
        ? Boolean(options.available)
        : true,
  };

  // Preserve useful fields from the source without overwriting canonical keys.
  const passthroughKeys = [
    "indicators",
    "trend",
    "trendDirection",
    "rawDirection",
    "marketStructure",
    "structure",
    "supportResistance",
    "supports",
    "resistances",
    "nearestSupport",
    "nearestResistance",
    "higherTimeframe",
    "mtfConfirmed",
    "candleCount",
    "diagnostics",
    "metadata",
    "version",
    "engineVersion",
    "strategyVersion",

    // Professional indicator / risk extension 2.0.0.
    "professionalPipelineVersion",
    "professionalTimeframe",
    "indicatorSnapshot",
    "confluence",
    "riskDiagnostics",
    "dataQuality",
    "marketRegime",
    "adx",
    "plusDI",
    "minusDI",

    // Phase 4 controlled-confidence compatibility.
    "originalConfidence",
    "aiMemoryAdjustedConfidence",
    "aiMemory",
    "confidenceExplainability",

    // Autonomous extension 1.4.0 diagnostics.
    "autonomous",
    "autonomousDecision",
    "autonomousSafety",
  ];

  for (const key of passthroughKeys) {
    if (
      rawSource[key] !== undefined &&
      canonical[key] === undefined
    ) {
      canonical[key] = liveCloneValue(rawSource[key]);
    }
  }

  return canonical;
}

// ---------------------------------------------------------------------------
// Engine selection helpers
// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// Scalp signal extraction
// ---------------------------------------------------------------------------

function liveFindPairRecord(container, pair) {
  if (!container) {
    return null;
  }

  const normalizedPair = liveNormalizePairLabel(pair);
  const compactPair = liveCompactPair(pair);

  if (Array.isArray(container)) {
    return (
      container.find((item) => {
        if (!liveIsPlainObject(item)) {
          return false;
        }

        const itemPair = liveNormalizePairLabel(
          item.pair ||
            item.symbol ||
            item.pairLabel ||
            item.instrument
        );

        return (
          itemPair === normalizedPair ||
          liveCompactPair(itemPair) === compactPair
        );
      }) || null
    );
  }

  if (!liveIsPlainObject(container)) {
    return null;
  }

  const directKeys = [
    normalizedPair,
    compactPair,
    normalizedPair.replace("/", "-"),
    normalizedPair.replace("/", "_"),
    normalizedPair.replace("/", ""),
  ];

  for (const key of directKeys) {
    if (
      Object.prototype.hasOwnProperty.call(container, key) &&
      container[key] !== null &&
      container[key] !== undefined
    ) {
      return container[key];
    }
  }

  for (const [key, value] of Object.entries(container)) {
    if (liveCompactPair(key) === compactPair) {
      return value;
    }
  }

  return null;
}

function extractPrimaryScalpSignal(
  scalpSignalsData,
  pair
) {
  if (!scalpSignalsData) {
    return null;
  }

  const candidateContainers = [
    scalpSignalsData,
    scalpSignalsData.signals,
    scalpSignalsData.results,
    scalpSignalsData.pairs,
    scalpSignalsData.data,
    scalpSignalsData.analysis,
    scalpSignalsData.scalp,
  ];

  let record = null;

  for (const container of candidateContainers) {
    record = liveFindPairRecord(container, pair);

    if (record) {
      break;
    }
  }

  if (!record && liveIsPlainObject(scalpSignalsData)) {
    const recordPair = liveNormalizePairLabel(
      scalpSignalsData.pair ||
        scalpSignalsData.symbol ||
        scalpSignalsData.pairLabel
    );

    if (
      liveCompactPair(recordPair) ===
      liveCompactPair(pair)
    ) {
      record = scalpSignalsData;
    }
  }

  if (!record) {
    return null;
  }

  const nestedSignal =
    liveIsPlainObject(record.signal)
      ? record.signal
      : liveIsPlainObject(record.analysis)
        ? record.analysis
        : liveIsPlainObject(record.result)
          ? record.result
          : record;

  return liveIsPlainObject(nestedSignal)
    ? {
        ...record,
        ...nestedSignal,
      }
    : record;
}

function isUsablePrimaryScalpSignal(
  signal,
  options = {}
) {
  if (!liveIsPlainObject(signal)) {
    return false;
  }

  const decision = liveExtractDecision(signal);
  const timestamp = liveExtractTimestamp(signal, 0);

  if (decision === "HOLD" && options.allowHold !== true) {
    return false;
  }

  const maximumAgeMs = Math.max(
    0,
    liveFiniteNumber(
      options.maximumAgeMs,
      6 * 60 * 60 * 1000
    )
  );

  if (
    maximumAgeMs > 0 &&
    timestamp > 0 &&
    Date.now() - timestamp > maximumAgeMs
  ) {
    return false;
  }

  return true;
}


// ---------------------------------------------------------------------------
// Scalp engine selection
// ---------------------------------------------------------------------------

function selectScalpEngineResult(input = {}) {
  const pair = liveNormalizePairLabel(
    input.pair ||
      input.symbol ||
      input.pairLabel
  );

  const primarySignal = extractPrimaryScalpSignal(
    input.scalpSignalsData ||
      input.scalpSignals ||
      input.primaryScalpData,
    pair
  );

  const allowPrimaryHold =
    input.allowPrimaryHold === true;

  if (
    isUsablePrimaryScalpSignal(primarySignal, {
      allowHold: allowPrimaryHold,
      maximumAgeMs:
        input.maximumPrimaryScalpAgeMs,
    })
  ) {
    const primaryResult = buildCanonicalEngineResult(
      primarySignal,
      {
        pair,
        mode: "scalp",
        engineName: "scalp-signals",
        source: "data/scalp-signals.json",
        requireTradePlan: true,
      }
    );

    return {
      ...primaryResult,

      selection: {
        selected: "primary-signal",
        primaryAvailable: true,
        fallbackAvailable: Boolean(
          input.fallbackScalpAnalysis
        ),
        reason:
          "Primary Scalp signal selected from data/scalp-signals.json",
      },
    };
  }

  const fallbackSource =
    input.fallbackScalpAnalysis ||
    input.legacyScalpAnalysis ||
    input.candleScalpAnalysis ||
    null;

  if (liveIsPlainObject(fallbackSource)) {
    const fallbackResult = buildCanonicalEngineResult(
      fallbackSource,
      {
        pair,
        mode: "scalp",
        engineName: "legacy-scalp-candles",
        source: "data/scalp-candles.json",
        requireTradePlan: true,
      }
    );

    return {
      ...fallbackResult,

      selection: {
        selected: "legacy-candle-fallback",
        primaryAvailable: Boolean(primarySignal),
        fallbackAvailable: true,
        reason: primarySignal
          ? "Primary Scalp signal was stale or unusable; candle fallback selected"
          : "Primary Scalp signal unavailable; candle fallback selected",
      },
    };
  }

  const holdResult = buildCanonicalEngineResult(
    {
      decision: "HOLD",
      confidence: 0,
      reason:
        "No usable primary or fallback Scalp analysis available",
      timestamp: Date.now(),
    },
    {
      pair,
      mode: "scalp",
      engineName: "scalp-unavailable",
      source: "none",
      available: false,
    }
  );

  return {
    ...holdResult,

    selection: {
      selected: "none",
      primaryAvailable: Boolean(primarySignal),
      fallbackAvailable: false,
      reason:
        "No usable Scalp engine result available",
    },
  };
}


// ---------------------------------------------------------------------------
// Swing and Intraday result selection
// ---------------------------------------------------------------------------

function selectSwingEngineResult(input = {}) {
  const pair = liveNormalizePairLabel(
    input.pair ||
      input.symbol ||
      input.pairLabel
  );

  const source =
    input.swingAnalysis ||
    input.dailyAnalysis ||
    input.analysisPipeline?.daily ||
    input.pipeline?.daily ||
    null;

  if (!liveIsPlainObject(source)) {
    return buildCanonicalEngineResult(
      {
        decision: "HOLD",
        confidence: 0,
        reason: "Swing analysis unavailable",
      },
      {
        pair,
        mode: "swing",
        engineName: "swing",
        source: "daily-analysis",
        available: false,
      }
    );
  }

  return buildCanonicalEngineResult(
    source,
    {
      pair,
      mode: "swing",
      engineName: "swing",
      source: "daily-analysis",
      requireTradePlan: false,
    }
  );
}

function selectIntradayEngineResult(input = {}) {
  const pair = liveNormalizePairLabel(
    input.pair ||
      input.symbol ||
      input.pairLabel
  );

  const source =
    input.intradayAnalysis ||
    input.h1Analysis ||
    input.analysisPipeline?.intraday ||
    input.pipeline?.intraday ||
    null;

  if (!liveIsPlainObject(source)) {
    return buildCanonicalEngineResult(
      {
        decision: "HOLD",
        confidence: 0,
        reason: "Intraday analysis unavailable",
      },
      {
        pair,
        mode: "intraday",
        engineName: "intraday",
        source: "data/intraday-h1.json",
        available: false,
      }
    );
  }

  return buildCanonicalEngineResult(
    source,
    {
      pair,
      mode: "intraday",
      engineName: "intraday",
      source: "data/intraday-h1.json",
      requireTradePlan: false,
    }
  );
}


// ---------------------------------------------------------------------------
// Consensus weighting
// ---------------------------------------------------------------------------

const DEFAULT_MASTER_ENGINE_WEIGHTS = Object.freeze({
  swing: 0.40,
  intraday: 0.35,
  scalp: 0.25,
});

function normalizeMasterWeights(rawWeights = {}) {
  const weights = {
    swing: Math.max(
      0,
      liveFiniteNumber(
        rawWeights.swing,
        DEFAULT_MASTER_ENGINE_WEIGHTS.swing
      )
    ),

    intraday: Math.max(
      0,
      liveFiniteNumber(
        rawWeights.intraday,
        DEFAULT_MASTER_ENGINE_WEIGHTS.intraday
      )
    ),

    scalp: Math.max(
      0,
      liveFiniteNumber(
        rawWeights.scalp,
        DEFAULT_MASTER_ENGINE_WEIGHTS.scalp
      )
    ),
  };

  const total =
    weights.swing +
    weights.intraday +
    weights.scalp;

  if (total <= 0) {
    return {
      ...DEFAULT_MASTER_ENGINE_WEIGHTS,
    };
  }

  return {
    swing: weights.swing / total,
    intraday: weights.intraday / total,
    scalp: weights.scalp / total,
  };
}

function masterEngineContribution(
  engineResult,
  weight
) {
  const result = liveIsPlainObject(engineResult)
    ? engineResult
    : {};

  const decision = liveExtractDecision(result);
  const confidence = liveExtractConfidence(result, 0);
  const availability =
    result.available === false ? 0 : 1;

  const directionalValue =
    liveDecisionScore(decision);

  const contribution =
    directionalValue *
    (confidence / 100) *
    weight *
    availability;

  return {
    decision,
    confidence,
    weight,
    available: availability === 1,
    contribution,
  };
}


// ---------------------------------------------------------------------------
// Master trade-plan selection
// ---------------------------------------------------------------------------

function selectMasterTradePlan(
  finalDecision,
  engines
) {
  const normalizedDecision =
    normalizeLiveDecision(finalDecision);

  if (normalizedDecision === "HOLD") {
    return null;
  }

  const candidates = [
    {
      name: "swing",
      priority: 3,
      result: engines.swing,
    },
    {
      name: "intraday",
      priority: 2,
      result: engines.intraday,
    },
    {
      name: "scalp",
      priority: 1,
      result: engines.scalp,
    },
  ]
    .filter((candidate) => {
      const result = candidate.result;

      return (
        liveIsPlainObject(result) &&
        liveExtractDecision(result) ===
          normalizedDecision &&
        liveIsPlainObject(result.tradePlan)
      );
    })
    .map((candidate) => ({
      ...candidate,
      confidence: liveExtractConfidence(
        candidate.result,
        0
      ),
    }))
    .sort((left, right) => {
      if (right.priority !== left.priority) {
        return right.priority - left.priority;
      }

      return right.confidence - left.confidence;
    });

  if (candidates.length === 0) {
    return null;
  }

  const selected = candidates[0];

  return {
    ...liveCloneValue(selected.result.tradePlan),

    sourceEngine: selected.name,
  };
}


// ---------------------------------------------------------------------------
// Master consensus
// ---------------------------------------------------------------------------

function buildMasterConsensus(input = {}) {
  const pair = liveNormalizePairLabel(
    input.pair ||
      input.symbol ||
      input.pairLabel ||
      input.swing?.pair ||
      input.intraday?.pair ||
      input.scalp?.pair
  );

  const engines = {
    swing: buildCanonicalEngineResult(
      input.swing || {},
      {
        pair,
        mode: "swing",
        engineName: "swing",
        available:
          input.swing?.available !== false,
      }
    ),

    intraday: buildCanonicalEngineResult(
      input.intraday || {},
      {
        pair,
        mode: "intraday",
        engineName: "intraday",
        available:
          input.intraday?.available !== false,
      }
    ),

    scalp: buildCanonicalEngineResult(
      input.scalp || {},
      {
        pair,
        mode: "scalp",
        engineName: "scalp",
        available:
          input.scalp?.available !== false,
      }
    ),
  };

  const weights = normalizeMasterWeights(
    input.weights ||
      input.engineWeights ||
      {}
  );

  const contributions = {
    swing: masterEngineContribution(
      engines.swing,
      weights.swing
    ),

    intraday: masterEngineContribution(
      engines.intraday,
      weights.intraday
    ),

    scalp: masterEngineContribution(
      engines.scalp,
      weights.scalp
    ),
  };

  const netContribution =
    contributions.swing.contribution +
    contributions.intraday.contribution +
    contributions.scalp.contribution;

  const activeDirectionalEngines = Object.values(
    contributions
  ).filter(
    (item) =>
      item.available &&
      item.decision !== "HOLD"
  );

  const buyEngines = activeDirectionalEngines.filter(
    (item) => item.decision === "BUY"
  );

  const sellEngines = activeDirectionalEngines.filter(
    (item) => item.decision === "SELL"
  );

  const directionalAgreement =
    buyEngines.length >= 2
      ? "BUY"
      : sellEngines.length >= 2
        ? "SELL"
        : "HOLD";

  const minimumNetContribution = liveBoundNumber(
    input.minimumNetContribution,
    0,
    1,
    0.18
  );

  const minimumDirectionalEngines = Math.max(
    1,
    Math.trunc(
      liveFiniteNumber(
        input.minimumDirectionalEngines,
        2
      )
    )
  );

  let decision = "HOLD";

  if (
    directionalAgreement === "BUY" &&
    buyEngines.length >= minimumDirectionalEngines &&
    netContribution >= minimumNetContribution
  ) {
    decision = "BUY";
  } else if (
    directionalAgreement === "SELL" &&
    sellEngines.length >= minimumDirectionalEngines &&
    netContribution <= -minimumNetContribution
  ) {
    decision = "SELL";
  }

  const directionalWeight = Math.abs(netContribution);
  const agreementCount =
    decision === "BUY"
      ? buyEngines.length
      : decision === "SELL"
        ? sellEngines.length
        : Math.max(
            buyEngines.length,
            sellEngines.length
          );

  const activeCount =
    activeDirectionalEngines.length;

  const agreementRatio =
    activeCount > 0
      ? agreementCount / activeCount
      : 0;

  const directionEngines =
    decision === "BUY"
      ? buyEngines
      : decision === "SELL"
        ? sellEngines
        : [];

  const directionConfidenceAverage =
    directionEngines.length > 0
      ? directionEngines.reduce(
          (sum, item) => sum + item.confidence,
          0
        ) / directionEngines.length
      : 0;

  let confidence;

  if (decision === "HOLD") {
    confidence = Math.round(
      Math.min(
        69,
        Math.abs(netContribution) * 100 +
          agreementRatio * 15
      )
    );
  } else {
    confidence = Math.round(
      Math.min(
        99,
        45 +
          directionalWeight * 35 +
          agreementRatio * 15 +
          directionConfidenceAverage * 0.15
      )
    );
  }

  const masterTradePlan = selectMasterTradePlan(
    decision,
    engines
  );

  // Without a valid source plan, retain the directional consensus but expose
  // no fabricated entry, stop or targets.
  const priceCandidates = [
    engines.intraday.price,
    engines.scalp.price,
    engines.swing.price,
  ].filter(Number.isFinite);

  const price =
    priceCandidates.length > 0
      ? priceCandidates[0]
      : null;

  const reasons = [];

  if (decision === "HOLD") {
    if (activeCount === 0) {
      reasons.push(
        "No directional engine produced an active setup"
      );
    } else if (
      buyEngines.length > 0 &&
      sellEngines.length > 0
    ) {
      reasons.push(
        "Directional engines are conflicting"
      );
    } else if (
      Math.abs(netContribution) <
      minimumNetContribution
    ) {
      reasons.push(
        "Weighted consensus is below the required threshold"
      );
    } else {
      reasons.push(
        "Insufficient multi-engine agreement"
      );
    }
  } else {
    reasons.push(
      `${agreementCount} engine(s) confirm ${decision}`
    );

    reasons.push(
      `Weighted consensus ${netContribution.toFixed(3)}`
    );
  }

  const timestamp = Date.now();

  return {
    pair,
    symbol: pair,
    pairLabel: pair,

    mode: "master",
    engine: "master-consensus",
    engineName: "master-consensus",

    decision,
    signal: decision,
    action: decision,
    direction: decision,

    confidence,
    confidencePct: confidence,

    score: Number(
      (netContribution * 100).toFixed(2)
    ),

    weightedScore: Number(
      (netContribution * 100).toFixed(2)
    ),

    netContribution: Number(
      netContribution.toFixed(6)
    ),

    price,
    currentPrice: price,
    lastPrice: price,

    timestamp,
    time: new Date(timestamp).toISOString(),
    generatedAt: new Date(timestamp).toISOString(),

    reason: reasons.join("; "),
    reasons,

    status:
      decision === "HOLD"
        ? "HOLD"
        : "ACTIVE",

    available: true,

    tradePlan:
      decision === "HOLD"
        ? null
        : masterTradePlan,

    plan:
      decision === "HOLD"
        ? null
        : masterTradePlan,

    entry:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.entry
        : null,

    entryPrice:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.entryPrice
        : null,

    stop:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.stop
        : null,

    stopLoss:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.stopLoss
        : null,

    sl:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.sl
        : null,

    target1:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.target1
        : null,

    target2:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.target2
        : null,

    target3:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.target3
        : null,

    takeProfit1:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.takeProfit1
        : null,

    takeProfit2:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.takeProfit2
        : null,

    takeProfit3:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.takeProfit3
        : null,

    tp1:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.tp1
        : null,

    tp2:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.tp2
        : null,

    tp3:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.tp3
        : null,

    riskReward:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.riskReward
        : null,

    rr:
      decision !== "HOLD" && masterTradePlan
        ? masterTradePlan.rr
        : null,

    weights,

    contributions,

    agreement: {
      direction: directionalAgreement,
      activeDirectionalEngines: activeCount,
      buyEngines: buyEngines.length,
      sellEngines: sellEngines.length,
      agreementCount,
      agreementRatio: Number(
        agreementRatio.toFixed(4)
      ),
    },

    engines: {
      swing: {
        decision: engines.swing.decision,
        confidence: engines.swing.confidence,
        score: engines.swing.score,
        available: engines.swing.available,
      },

      intraday: {
        decision: engines.intraday.decision,
        confidence: engines.intraday.confidence,
        score: engines.intraday.score,
        available: engines.intraday.available,
      },

      scalp: {
        decision: engines.scalp.decision,
        confidence: engines.scalp.confidence,
        score: engines.scalp.score,
        available: engines.scalp.available,
        source: engines.scalp.source,
      },
    },
  };
}


// ---------------------------------------------------------------------------
// Per-pair engine bundle
// ---------------------------------------------------------------------------
function attachAIMemoryAssessment(
  engineResult,
  aiMemoryState,
  context = {}
) {
  if (
    !engineResult ||
    typeof engineResult !== "object" ||
    Array.isArray(engineResult)
  ) {
    return engineResult;
  }

  const assessment =
    createAIMemoryAssessment(
      aiMemoryState,
      {
        ...context,

        pair:
          context.pair ||
          engineResult.pair ||
          engineResult.symbol ||
          engineResult.pairLabel,

        engine:
          context.engine ||
          context.mode ||
          engineResult.engineName ||
          engineResult.engine ||
          engineResult.mode,

        direction:
          engineResult.decision ||
          engineResult.signal ||
          engineResult.action ||
          engineResult.direction,

        timeframe:
          context.timeframe ||
          engineResult.timeframe ||
          engineResult.tf ||
          engineResult.interval,
      }
    );

  return applyAIMemoryConfidenceAdjustment(
    engineResult,
    assessment
  );
}

function buildPairEngineBundle(
  input = {}
) {
  const pair =
    liveNormalizePairLabel(
      input.pair ||
      input.symbol ||
      input.pairLabel
    );

  const aiMemoryState =
    input.aiMemoryState ||
    input.aiMemory ||
    createUnavailableAIMemoryState(
      "AI Memory was not supplied to the pair analysis pipeline"
    );

  const pipeline =
    liveIsPlainObject(
      input.analysisPipeline
    )
      ? input.analysisPipeline
      : liveIsPlainObject(
          input.pipeline
        )
        ? input.pipeline
        : typeof runLegacyCompatibleAnalysisPipeline ===
            "function"
          ? runLegacyCompatibleAnalysisPipeline({
              ...input,
              pair,
            })
          : {};

  // --------------------------------------------------------
  // Build original engine results first.
  //
  // These unadjusted results are used by Master consensus so
  // Phase 4 does not change the established engine weighting.
  // --------------------------------------------------------

  const baseSwing =
    selectSwingEngineResult({
      pair,

      swingAnalysis:
        input.swingAnalysis ||
        pipeline.daily,

      analysisPipeline:
        pipeline,
    });

  const baseIntraday =
    selectIntradayEngineResult({
      pair,

      intradayAnalysis:
        input.intradayAnalysis ||
        pipeline.intraday,

      analysisPipeline:
        pipeline,
    });

  const selectedBaseScalp =
    selectScalpEngineResult({
      pair,

      scalpSignalsData:
        input.scalpSignalsData ||
        input.scalpSignals,

      fallbackScalpAnalysis:
        input.fallbackScalpAnalysis ||
        input.legacyScalpAnalysis ||
        pipeline.scalp,

      allowPrimaryHold:
        input.allowPrimaryScalpHold,

      maximumPrimaryScalpAgeMs:
        input.maximumPrimaryScalpAgeMs,
    });

  /*
   * The dedicated Scalp pipeline uses the 15-minute anchor whenever its
   * aggregated pair result does not carry an explicit component timeframe.
   * Persist that policy in the canonical result so the history resolver does
   * not have to guess later.
   */
  const scalpTimeframe =
    normalizeAIMemoryTimeframe(
      firstString(
        selectedBaseScalp.timeframe,
        selectedBaseScalp.sourceTimeframe,
        selectedBaseScalp.tf,
        selectedBaseScalp.interval,

        selectedBaseScalp.sourceData &&
          selectedBaseScalp.sourceData.timeframe,

        selectedBaseScalp.raw &&
          selectedBaseScalp.raw.timeframe
      )
    ) ||
    "15m";

  const baseScalp = {
    ...selectedBaseScalp,

    timeframe:
      scalpTimeframe,

    sourceTimeframe:
      scalpTimeframe,

    timeframeSource:
      selectedBaseScalp.timeframe
        ? (
            selectedBaseScalp.timeframeSource ||
            "source"
          )
        : "live-analysis-scalp-anchor",
  };

  // --------------------------------------------------------
  // Master consensus intentionally uses original confidence.
  // --------------------------------------------------------

  const baseMaster =
    buildMasterConsensus({
      pair,

      swing:
        baseSwing,

      intraday:
        baseIntraday,

      scalp:
        baseScalp,

      weights:
        input.masterWeights ||
        input.engineWeights,

      minimumNetContribution:
        input.minimumNetContribution,

      minimumDirectionalEngines:
        input.minimumDirectionalEngines,
    });

  // --------------------------------------------------------
  // Apply controlled AI Memory adjustment only after the
  // original Master consensus has already been calculated.
  // --------------------------------------------------------

  const swing =
    attachAIMemoryAssessment(
      baseSwing,
      aiMemoryState,
      {
        pair,
        engine: "weekly",
        mode: "swing",
        timeframe: "D1",
      }
    );

  const intraday =
    attachAIMemoryAssessment(
      baseIntraday,
      aiMemoryState,
      {
        pair,
        engine: "daily",
        mode: "intraday",
        timeframe: "1H",
      }
    );

  const scalp =
    attachAIMemoryAssessment(
      baseScalp,
      aiMemoryState,
      {
        pair,
        engine: "scalp",
        mode: "scalp",
        timeframe:
          scalpTimeframe,
      }
    );

  const master =
    attachAIMemoryAssessment(
      baseMaster,
      aiMemoryState,
      {
        pair,
        engine: "master",
        mode: "master",
        timeframe: null,
      }
    );

  return {
    pair,
    symbol: pair,
    pairLabel: pair,

    generatedAt:
      liveNowIso(),

    timestamp:
      Date.now(),

    swing,
    intraday,
    scalp,
    master,

    engines: {
      swing,
      intraday,
      scalp,
      master,
    },

    aiMemory: {
      enabled:
        AI_MEMORY_INTEGRATION.enabled,

      available:
        Boolean(
          aiMemoryState.available
        ),

      valid:
        Boolean(
          aiMemoryState.valid
        ),

      mode:
        AI_MEMORY_INTEGRATION.mode,

      applyConfidenceAdjustment:
        AI_MEMORY_INTEGRATION
          .applyConfidenceAdjustment ===
        true,

      maximumAppliedAdjustment:
        AI_MEMORY_INTEGRATION
          .maximumAppliedAdjustment,

      minimumSamplesToApply:
        AI_MEMORY_INTEGRATION
          .minimumSamplesToApply,

      minimumReliabilityToApply:
        AI_MEMORY_INTEGRATION
          .minimumReliabilityToApply,

      generatedAt:
        aiMemoryState.generatedAt ||
        null,

      engineName:
        aiMemoryState.engineName ||
        null,

      engineVersion:
        aiMemoryState.engineVersion ||
        null,

      reason:
        aiMemoryState.reason ||
        null,
    },

    pipelineMetadata:
      liveCloneValue(
        pipeline.frameMetadata ||
        pipeline.metadata ||
        null
      ),
  };
}


// ---------------------------------------------------------------------------
// Live-analysis output schema
// ---------------------------------------------------------------------------
function buildLiveAnalysisOutput(input = {}) {
  const pairBundles = Array.isArray(input.pairs)
    ? input.pairs
    : liveIsPlainObject(input.pairs)
      ? Object.values(input.pairs)
      : [];

  const generatedTimestamp =
    liveStableTimestamp(
      input.timestamp,
      Date.now()
    );

  const generatedAt =
    input.generatedAt ||
    new Date(generatedTimestamp).toISOString();

  const byPair = {};

  for (const rawBundle of pairBundles) {
    if (!liveIsPlainObject(rawBundle)) {
      continue;
    }

    const pair = liveNormalizePairLabel(
      rawBundle.pair ||
        rawBundle.symbol ||
        rawBundle.pairLabel
    );

    if (!pair || pair === "UNKNOWN") {
      continue;
    }

    const swing = buildCanonicalEngineResult(
      rawBundle.swing ||
        rawBundle.engines?.swing ||
        {},
      {
        pair,
        mode: "swing",
        engineName: "swing",
      }
    );

    const intraday = buildCanonicalEngineResult(
      rawBundle.intraday ||
        rawBundle.engines?.intraday ||
        {},
      {
        pair,
        mode: "intraday",
        engineName: "intraday",
      }
    );

    const scalp = buildCanonicalEngineResult(
      rawBundle.scalp ||
        rawBundle.engines?.scalp ||
        {},
      {
        pair,
        mode: "scalp",
        engineName: "scalp",
      }
    );

    const master = buildCanonicalEngineResult(
      rawBundle.master ||
        rawBundle.engines?.master ||
        buildMasterConsensus({
          pair,
          swing,
          intraday,
          scalp,
        }),
      {
        pair,
        mode: "master",
        engineName: "master-consensus",
      }
    );

    const pairRecord = {
      pair,
      symbol: pair,
      pairLabel: pair,

      generatedAt,
      timestamp: generatedTimestamp,

      swing,
      intraday,
      scalp,
      master,

      engines: {
        swing,
        intraday,
        scalp,
        master,
      },

      // Legacy-compatible mode access.
      modes: {
        swing,
        intraday,
        scalp,
        master,
      },

      // Convenient top-level master aliases.
      decision: master.decision,
      signal: master.signal,
      action: master.action,
      direction: master.direction,

      confidence: master.confidence,
      score: master.score,

      price: master.price,
      currentPrice: master.currentPrice,
      lastPrice: master.lastPrice,

      tradePlan: master.tradePlan,
      plan: master.plan,

      entry: master.entry,
      stop: master.stop,
      stopLoss: master.stopLoss,

      target1: master.target1,
      target2: master.target2,
      target3: master.target3,

      tp1: master.tp1,
      tp2: master.tp2,
      tp3: master.tp3,

      riskReward: master.riskReward,
      rr: master.rr,

      reason: master.reason,
      status: master.status,

      // Preserve additive pair-level diagnostics produced by the runtime.
      aiMemory:
        liveCloneValue(
          rawBundle.aiMemory ||
          null
        ),

      pipelineMetadata:
        liveCloneValue(
          rawBundle.pipelineMetadata ||
          null
        ),

      runtime:
        liveCloneValue(
          rawBundle.runtime ||
          null
        ),
    };

    byPair[pair] = pairRecord;
  }

  const pairList = Object.values(byPair);

  const aiMemoryByPair = {};

  for (const pairRecord of pairList) {
    if (liveIsPlainObject(pairRecord.aiMemory)) {
      aiMemoryByPair[pairRecord.pair] =
        liveCloneValue(
          pairRecord.aiMemory
        );
    }
  }

  const aiMemorySummary =
    Object.values(aiMemoryByPair)[0] ||
    null;

  return {
    generatedAt,
    updatedAt: generatedAt,
    timestamp: generatedTimestamp,

    engineVersion:
      typeof ENGINE_VERSION !== "undefined"
        ? ENGINE_VERSION
        : input.engineVersion ||
          "unknown",

    strategyVersion:
      typeof STRATEGY_VERSION !== "undefined"
        ? STRATEGY_VERSION
        : input.strategyVersion ||
          "unknown",

    status: "ok",

    pairCount: pairList.length,

    // Additive integration diagnostics; existing pair/engine schemas remain intact.
    aiMemory:
      liveCloneValue(
        aiMemorySummary
      ),

    aiMemoryByPair,

    // Primary current schema.
    pairs: byPair,

    // Legacy-compatible array aliases.
    results: pairList,
    analyses: pairList,
    data: pairList,

    // Optional direct aliases for known pairs.
    xauUsd:
      byPair["XAU/USD"] || null,

    gbpJpy:
      byPair["GBP/JPY"] || null,

    "XAU/USD":
      byPair["XAU/USD"] || null,

    "GBP/JPY":
      byPair["GBP/JPY"] || null,

    metadata: {
      generatedAt,
      pairCount: pairList.length,

      engineVersion:
        typeof ENGINE_VERSION !== "undefined"
          ? ENGINE_VERSION
          : input.engineVersion ||
            "unknown",

      strategyVersion:
        typeof STRATEGY_VERSION !== "undefined"
          ? STRATEGY_VERSION
          : input.strategyVersion ||
            "unknown",
    },
  };
}


// ---------------------------------------------------------------------------
// History fingerprinting
// ---------------------------------------------------------------------------
function liveHistoryFingerprint(record) {
  const pair = liveNormalizePairLabel(
    record?.pair ||
      record?.symbol ||
      record?.pairLabel
  );

  const mode = liveNormalizeMode(
    record?.mode ||
      record?.engine ||
      "master",
    "master"
  );

  const decision = liveExtractDecision(record);

  const entry = liveFiniteNumber(
    record?.entry ??
      record?.entryPrice ??
      record?.tradePlan?.entry,
    null
  );

  const stopLoss = liveFiniteNumber(
    record?.stopLoss ??
      record?.stop ??
      record?.tradePlan?.stopLoss,
    null
  );

  const target1 = liveFiniteNumber(
    record?.target1 ??
      record?.tp1 ??
      record?.tradePlan?.target1,
    null
  );

  return [
    liveCompactPair(pair),
    mode,
    decision,
    Number.isFinite(entry) ? entry : "",
    Number.isFinite(stopLoss) ? stopLoss : "",
    Number.isFinite(target1) ? target1 : "",
  ].join("|");
}

function liveHistorySetupIdentity(record) {
  if (!liveIsPlainObject(record)) {
    return null;
  }

  const existingIdentity =
    liveNonEmptyString(
      record.setupIdentity ??
        record.setupId ??
        record.snapshot?.setupIdentity,
      null
    );

  if (existingIdentity) {
    return existingIdentity;
  }

  const pair = liveCompactPair(
    record.pair ??
      record.symbol ??
      record.pairLabel ??
      record.snapshot?.pair ??
      record.snapshot?.symbol
  );

  if (
    pair !== "XAUUSD" &&
    pair !== "GBPJPY"
  ) {
    return null;
  }

  const rawEngine = liveNonEmptyString(
    record.engine ??
      record.engineName ??
      record.mode ??
      record.strategy ??
      record.snapshot?.engine ??
      record.snapshot?.mode,
    ""
  ).toLowerCase();

  const engineAliases = {
    swing: "swing",
    weekly: "swing",
    intraday: "intraday",
    daily: "intraday",
    scalp: "scalp",
    "scalp-5m": "scalp",
    "scalp-15m": "scalp",
    "scalp-30m": "scalp",
    master: "master",
  };

  const engine =
    engineAliases[rawEngine] || null;

  const timeframe =
    normalizeAIMemoryTimeframe(
      firstString(
        record.timeframe,
        record.sourceTimeframe,
        record.tf,
        record.interval,
        record.period,
        record.snapshot?.timeframe,
        record.snapshot?.sourceTimeframe
      )
    );

  const direction =
    liveExtractDecision(record);

  const openedCandidates = [
    record.analyzedCandleAt,
    record.snapshot?.analyzedCandleAt,
    record.signalTimestamp,
    record.signalTime,
    record.openedAt,
    record.snapshot?.signalTimestamp,
    record.snapshot?.signalTime,
    record.timestamp,
    record.time,
    record.snapshot?.timestamp,
    record.snapshot?.time,
    record.generatedAt,
    record.snapshot?.generatedAt,
    record.createdAt,
    record.recordedAt,
  ];

  let openedTimestamp = null;

  for (const candidate of openedCandidates) {
    const parsed = liveStableTimestamp(
      candidate,
      null
    );

    if (Number.isFinite(parsed)) {
      openedTimestamp = parsed;
      break;
    }
  }

  if (
    !engine ||
    !timeframe ||
    (
      direction !== "BUY" &&
      direction !== "SELL"
    ) ||
    !Number.isFinite(openedTimestamp)
  ) {
    return null;
  }

  return [
    "setup-v1",
    pair,
    engine,
    timeframe,
    direction,
    new Date(openedTimestamp).toISOString(),
  ].join("|");
}

function liveHistoryRecordFromEngine(
  engineResult,
  options = {}
) {
  const canonical =
    buildCanonicalEngineResult(
      engineResult,
      {
        pair:
          options.pair ||
          engineResult?.pair,

        mode:
          options.mode ||
          engineResult?.mode ||
          "master",

        engineName:
          options.engineName ||
          engineResult?.engine ||
          engineResult?.engineName,
      }
    );

  const recordedAt =
    liveNowIso();

  const finalConfidence =
    liveNormalizeConfidence(
      canonical.confidence,
      0
    );

  const originalConfidence =
    liveNormalizeConfidence(
      canonical.originalConfidence ??
        canonical.aiMemory
          ?.originalConfidence ??
        finalConfidence,
      finalConfidence
    );

  const aiMemoryAdjustedConfidence =
    liveNormalizeConfidence(
      canonical.aiMemoryAdjustedConfidence ??
        canonical.aiMemory
          ?.adjustedConfidence ??
        finalConfidence,
      finalConfidence
    );

  const appliedConfidenceAdjustment =
    liveFiniteNumber(
      canonical.aiMemory
        ?.appliedConfidenceAdjustment ??
        canonical.aiMemory
          ?.confidenceAdjustment,
      0
    );

  const aiMemoryApplied =
    canonical.aiMemory?.applied ===
    true;

  return {
    id:
      options.id ||
      `${Date.now()}-${liveCompactPair(
        canonical.pair
      )}-${canonical.mode}`,

    recordedAt,
    createdAt: recordedAt,
    updatedAt: recordedAt,

    pair: canonical.pair,
    symbol: canonical.pair,
    pairLabel: canonical.pair,

    mode: canonical.mode,
    engine: canonical.engine,
    engineName:
      canonical.engineName,

    timeframe:
      canonical.timeframe ||
      null,

    sourceTimeframe:
      canonical.sourceTimeframe ||
      canonical.timeframe ||
      null,

    timeframeSource:
      canonical.timeframeSource ||
      null,

    engineVersion:
      canonical.engineVersion ||
      ENGINE_VERSION,

    strategyVersion:
      canonical.strategyVersion ||
      STRATEGY_VERSION,

    professionalPipelineVersion:
      canonical.professionalPipelineVersion ||
      null,

    marketRegime:
      canonical.marketRegime ||
      null,

    decision:
      canonical.decision,

    signal:
      canonical.signal,

    action:
      canonical.action,

    direction:
      canonical.direction,

    // Final confidence used by the live engine,
    // Telegram and all existing consumers.
    confidence:
      finalConfidence,

    confidencePct:
      finalConfidence,

    // Phase 4 audit fields.
    originalConfidence,

    aiMemoryAdjustedConfidence,

    appliedConfidenceAdjustment,

    aiMemoryApplied,

    score:
      canonical.score,

    price:
      canonical.price,

    currentPrice:
      canonical.currentPrice,

    entry:
      canonical.entry,

    entryPrice:
      canonical.entryPrice,

    stop:
      canonical.stop,

    stopLoss:
      canonical.stopLoss,

    sl:
      canonical.sl,

    target1:
      canonical.target1,

    target2:
      canonical.target2,

    target3:
      canonical.target3,

    takeProfit1:
      canonical.takeProfit1,

    takeProfit2:
      canonical.takeProfit2,

    takeProfit3:
      canonical.takeProfit3,

    tp1:
      canonical.tp1,

    tp2:
      canonical.tp2,

    tp3:
      canonical.tp3,

    riskReward:
      canonical.riskReward,

    rr:
      canonical.rr,

    reason:
      canonical.reason,

    source:
      canonical.source,

    signalTimestamp:
      canonical.timestamp,

    signalTime:
      canonical.time,

    status:
      canonical.decision ===
      "HOLD"
        ? "hold"
        : "open",

    outcome: null,
    resolvedAt: null,

    fingerprint:
      liveHistoryFingerprint(
        canonical
      ),

    confidenceExplainability:
      liveCloneValue(
        canonical.confidenceExplainability ||
        null
      ),

    aiMemory:
      liveCloneValue(
        canonical.aiMemory ||
        null
      ),

    snapshot:
      liveCloneValue(
        canonical
      ),
  };
}


// ---------------------------------------------------------------------------
// History normalization
// ---------------------------------------------------------------------------

function normalizeAnalysisHistory(rawHistory) {
  if (Array.isArray(rawHistory)) {
    return {
      version: 1,
      updatedAt: liveNowIso(),
      records: rawHistory,
    };
  }

  if (!liveIsPlainObject(rawHistory)) {
    return {
      version: 1,
      updatedAt: liveNowIso(),
      records: [],
    };
  }

  const records =
    liveAsArray(rawHistory.records).length > 0
      ? rawHistory.records
      : liveAsArray(rawHistory.history).length > 0
        ? rawHistory.history
        : liveAsArray(rawHistory.items).length > 0
          ? rawHistory.items
          : liveAsArray(rawHistory.signals);

  return {
    ...rawHistory,

    version:
      liveFiniteNumber(rawHistory.version, 1),

    updatedAt:
      rawHistory.updatedAt ||
      liveNowIso(),

    records,

    // Preserve common aliases.
    history: records,
    items: records,
  };
}

function shouldAppendHistoryRecord(
  history,
  record,
  options = {}
) {
  if (!liveIsPlainObject(record)) {
    return false;
  }

  const decision = liveExtractDecision(record);

  if (
    decision === "HOLD" &&
    options.includeHold !== true
  ) {
    return false;
  }

  const records = liveAsArray(history.records);

  const fingerprint =
    record.fingerprint ||
    liveHistoryFingerprint(record);

  const setupIdentity =
    liveHistorySetupIdentity(record);

  const dedupeWindowMs = Math.max(
    0,
    liveFiniteNumber(
      options.dedupeWindowMs,
      30 * 60 * 1000
    )
  );

  for (
    let index = records.length - 1;
    index >= 0;
    index -= 1
  ) {
    const existing = records[index];

    if (!liveIsPlainObject(existing)) {
      continue;
    }

    const existingSetupIdentity =
      liveHistorySetupIdentity(existing);

    if (
      setupIdentity &&
      existingSetupIdentity ===
        setupIdentity
    ) {
      return false;
    }

    const existingTimestamp =
      liveExtractTimestamp(
        existing,
        0
      );

    if (
      dedupeWindowMs > 0 &&
      existingTimestamp > 0 &&
      Date.now() - existingTimestamp >
        dedupeWindowMs
    ) {
      /*
       * Imported/legacy history is not guaranteed to be chronological.
       * Skip this old record, but continue checking earlier array entries for
       * a recent duplicate instead of terminating the scan.
       */
      continue;
    }

    const existingFingerprint =
      existing.fingerprint ||
      liveHistoryFingerprint(existing);

    if (
      existingFingerprint ===
      fingerprint
    ) {
      return false;
    }
  }

  return true;
}

function appendAnalysisHistoryRecords(
  rawHistory,
  recordsToAppend,
  options = {}
) {
  const history =
    normalizeAnalysisHistory(
      rawHistory
    );

  const existingRecords =
    liveAsArray(history.records);

  const appended = [];

  for (
    const rawRecord of
    liveAsArray(recordsToAppend)
  ) {
    const record =
      liveIsPlainObject(rawRecord)
        ? rawRecord
        : null;

    if (!record) {
      continue;
    }

    if (
      shouldAppendHistoryRecord(
        {
          records: [
            ...existingRecords,
            ...appended,
          ],
        },
        record,
        options
      )
    ) {
      appended.push(record);
    }
  }

  const maximumRecords = Math.max(
    1,
    Math.trunc(
      liveFiniteNumber(
        options.maximumRecords,
        5000
      )
    )
  );

  const records = [
    ...existingRecords,
    ...appended,
  ].slice(-maximumRecords);

  const updatedAt =
    liveNowIso();

  return {
    history: {
      ...history,

      updatedAt,

      engineVersion:
        options.engineVersion ||
        (
          typeof ENGINE_VERSION !== "undefined"
            ? ENGINE_VERSION
            : history.engineVersion
        ),

      strategyVersion:
        options.strategyVersion ||
        (
          typeof STRATEGY_VERSION !== "undefined"
            ? STRATEGY_VERSION
            : history.strategyVersion
        ),

      records,

      // Preserve aliases used by older readers.
      history: records,
      items: records,

      count: records.length,
    },

    appended,
    appendedCount:
      appended.length,
  };
}



// ---------------------------------------------------------------------------
// Dashboard Intraday / Swing history projection
// ---------------------------------------------------------------------------
function buildDashboardHistoryTracker(rawHistory) {
  const history = liveIsPlainObject(rawHistory) ? rawHistory : {};
  const records = liveAsArray(history.records).filter(liveIsPlainObject);
  const closed = liveAsArray(history.closed).filter(liveIsPlainObject);
  const pairs = ["XAUUSD", "GBPJPY"];
  const engines = ["intraday", "swing"];

  const pairOf = (record) => {
    const pair = liveCompactPair(
      record?.pair ??
      record?.symbol ??
      record?.pairLabel ??
      record?.snapshot?.pair ??
      record?.snapshot?.symbol
    );
    return pairs.includes(pair) ? pair : null;
  };

  const engineOf = (record) => {
    const raw = liveNonEmptyString(
      record?.engine ??
      record?.engineName ??
      record?.mode ??
      record?.strategy ??
      record?.snapshot?.engine ??
      record?.snapshot?.mode,
      ""
    ).toLowerCase();

    if (raw === "intraday" || raw === "daily") return "intraday";
    if (raw === "swing" || raw === "weekly") return "swing";
    return null;
  };

  const outcomeOf = (record) => {
    const outcome = liveNonEmptyString(
      record?.outcome ??
      record?.result ??
      record?.resolution?.outcome,
      ""
    ).toUpperCase();

    return ["WIN", "LOSS", "BREAKEVEN"].includes(outcome)
      ? outcome
      : null;
  };

  const numberOf = (record, fields) => {
    for (const value of fields(record)) {
      const number = liveFiniteNumber(value, null);
      if (Number.isFinite(number)) return number;
    }
    return null;
  };

  const entryOf = (record) =>
    numberOf(record, (r) => [
      r?.entry, r?.entryPrice, r?.tradePlan?.entry,
      r?.snapshot?.entry, r?.snapshot?.entryPrice,
      r?.snapshot?.tradePlan?.entry,
    ]);

  const stopOf = (record) =>
    numberOf(record, (r) => [
      r?.stop, r?.stopLoss, r?.sl,
      r?.tradePlan?.stop, r?.tradePlan?.stopLoss, r?.tradePlan?.sl,
      r?.snapshot?.stop, r?.snapshot?.stopLoss, r?.snapshot?.sl,
      r?.snapshot?.tradePlan?.stop,
    ]);

  const targetOf = (record) =>
    numberOf(record, (r) => [
      r?.target1, r?.takeProfit1, r?.tp1, r?.target,
      r?.tradePlan?.target1, r?.snapshot?.target1,
      r?.snapshot?.tp1, r?.snapshot?.tradePlan?.target1,
    ]);

  const rrOf = (record) => {
    const stored = numberOf(record, (r) => [
      r?.riskReward, r?.rr,
      r?.tradePlan?.riskReward, r?.tradePlan?.rr,
    ]);
    if (Number.isFinite(stored) && stored > 0) return stored;

    const entry = entryOf(record);
    const stop = stopOf(record);
    const target = targetOf(record);
    if (![entry, stop, target].every(Number.isFinite)) return null;

    const risk = Math.abs(entry - stop);
    return risk > 0 ? Math.abs(target - entry) / risk : null;
  };

  const timestampOf = (record, closedTime = false) => {
    const values = closedTime
      ? [record?.closedAt, record?.resolvedAt, record?.resolution?.resolvedAt]
      : [
          record?.analyzedCandleAt,
          record?.snapshot?.analyzedCandleAt,
          record?.signalTimestamp,
          record?.signalTime,
          record?.openedAt,
          record?.snapshot?.signalTimestamp,
          record?.snapshot?.signalTime,
          record?.createdAt,
          record?.recordedAt,
        ];

    for (const value of values) {
      const timestamp = liveStableTimestamp(value, null);
      if (Number.isFinite(timestamp)) return timestamp;
    }
    return null;
  };

  const resolvedSetupIds = new Set(
    records
      .filter((record) => {
        const status = liveNonEmptyString(record?.status, "").toLowerCase();
        return Boolean(
          outcomeOf(record) ||
          ["closed", "resolved", "complete", "completed"].includes(status)
        );
      })
      .map(liveHistorySetupIdentity)
      .filter(Boolean)
  );

  const openMaps = Object.fromEntries(
    pairs.map((pair) => [
      pair,
      {
        intraday: new Map(),
        swing: new Map(),
      },
    ])
  );

  for (const record of records) {
    const pair = pairOf(record);
    const engine = engineOf(record);
    const status = liveNonEmptyString(record?.status, "").toLowerCase();
    const identity = liveHistorySetupIdentity(record);

    if (
      !pair ||
      !engines.includes(engine) ||
      outcomeOf(record) ||
      ["closed", "resolved", "complete", "completed",
       "hold", "invalid", "rejected", "error"].includes(status) ||
      !identity ||
      resolvedSetupIds.has(identity) ||
      openMaps[pair][engine].has(identity)
    ) {
      continue;
    }

    const direction = liveExtractDecision(record);
    const entry = entryOf(record);
    const stop = stopOf(record);
    const target1 = targetOf(record);
    const openedAt = timestampOf(record);

    if (
      !["BUY", "SELL"].includes(direction) ||
      ![entry, stop, target1, openedAt].every(Number.isFinite)
    ) {
      continue;
    }

    openMaps[pair][engine].set(identity, {
      identity,
      pairKey: pair,
      engine,
      timeframe: engine === "intraday" ? "1H" : "D1",
      decision: direction,
      entry,
      stop,
      target1,
      rr: rrOf(record),
      confidence: liveFiniteNumber(
        record?.confidencePct ?? record?.confidence,
        null
      ),
      openedAt: new Date(openedAt).toISOString(),
      status: "OPEN",
    });
  }

  const trackerPairs = {};

  for (const pair of pairs) {
    trackerPairs[pair] = {
      pairKey: pair,
      pair: pair === "XAUUSD" ? "XAU/USD" : "GBP/JPY",
    };

    for (const engine of engines) {
      const resolvedTrades = closed.filter(
        (record) =>
          pairOf(record) === pair &&
          engineOf(record) === engine &&
          outcomeOf(record)
      );

      const wins = resolvedTrades.filter(
        (record) => outcomeOf(record) === "WIN"
      ).length;
      const losses = resolvedTrades.filter(
        (record) => outcomeOf(record) === "LOSS"
      ).length;
      const breakevens = resolvedTrades.filter(
        (record) => outcomeOf(record) === "BREAKEVEN"
      ).length;
      const resolved = wins + losses;
      const rrValues = resolvedTrades
        .map(rrOf)
        .filter((value) => Number.isFinite(value) && value > 0);

      const openTrades = Array.from(openMaps[pair][engine].values())
        .sort(
          (a, b) =>
            liveStableTimestamp(b.openedAt, 0) -
            liveStableTimestamp(a.openedAt, 0)
        );

      const recentResolved = resolvedTrades
        .map((record) => {
          const openedAt = timestampOf(record);
          const closedAt = timestampOf(record, true);
          return {
            pairKey: pair,
            engine,
            decision: liveExtractDecision(record),
            entry: entryOf(record),
            stop: stopOf(record),
            target1: targetOf(record),
            rr: rrOf(record),
            result: outcomeOf(record),
            openedAt: Number.isFinite(openedAt)
              ? new Date(openedAt).toISOString()
              : null,
            closedAt: Number.isFinite(closedAt)
              ? new Date(closedAt).toISOString()
              : null,
          };
        })
        .sort(
          (a, b) =>
            liveStableTimestamp(b.closedAt, 0) -
            liveStableTimestamp(a.closedAt, 0)
        )
        .slice(0, 10);

      trackerPairs[pair][engine] = {
        openTrades,
        stats: {
          resolved,
          wins,
          losses,
          breakevens,
          winRate: resolved
            ? Number(((wins / resolved) * 100).toFixed(2))
            : null,
          averageRR: rrValues.length
            ? Number(
                (
                  rrValues.reduce((sum, value) => sum + value, 0) /
                  rrValues.length
                ).toFixed(4)
              )
            : null,
          openCount: openTrades.length,
        },
        recentResolved,
      };
    }
  }

  return {
    schemaVersion: 1,
    updatedAt: liveNonEmptyString(history.updatedAt, "") || liveNowIso(),
    pairs: trackerPairs,
  };
}


// ---------------------------------------------------------------------------
// History collection from current output
// ---------------------------------------------------------------------------
function collectHistoryRecordsFromOutput(
  liveOutput,
  options = {}
) {
  const records = [];

  const pairRecords = liveIsPlainObject(
    liveOutput?.pairs
  )
    ? Object.values(
        liveOutput.pairs
      )
    : liveAsArray(
        liveOutput?.results
      );

  const modes =
    Array.isArray(options.modes)
      ? options.modes.map(
          (mode) =>
            liveNormalizeMode(mode)
        )
      : [
          "master",
          "swing",
          "intraday",
          "scalp",
        ];

  for (
    const pairRecord of pairRecords
  ) {
    if (
      !liveIsPlainObject(
        pairRecord
      )
    ) {
      continue;
    }

    const pair =
      liveNormalizePairLabel(
        pairRecord.pair ||
          pairRecord.symbol
      );

    for (const mode of modes) {
      const engineResult =
        pairRecord[mode] ||
        pairRecord.engines?.[mode] ||
        pairRecord.modes?.[mode];

      if (
        !liveIsPlainObject(
          engineResult
        )
      ) {
        continue;
      }

      const decision =
        liveExtractDecision(
          engineResult
        );

      if (
        decision === "HOLD" &&
        options.includeHold !== true
      ) {
        continue;
      }

      records.push(
        liveHistoryRecordFromEngine(
          engineResult,
          {
            pair,
            mode,
          }
        )
      );
    }
  }

  return records;
}


// ---------------------------------------------------------------------------
// Notify-state normalization
// ---------------------------------------------------------------------------
function normalizeNotifyState(rawState) {
  if (!liveIsPlainObject(rawState)) {
    return {
      version: 1,
      updatedAt: liveNowIso(),
      signals: {},
    };
  }

  const signals =
    liveIsPlainObject(rawState.signals)
      ? rawState.signals
      : liveIsPlainObject(rawState.notifications)
        ? rawState.notifications
        : liveIsPlainObject(rawState.state)
          ? rawState.state
          : {};

  return {
    ...rawState,

    version:
      liveFiniteNumber(
        rawState.version,
        1
      ),

    updatedAt:
      rawState.updatedAt ||
      liveNowIso(),

    signals,

    // Preserve older aliases.
    notifications: signals,
    state: signals,
  };
}

function liveNotifyStateKey(record) {
  const pair =
    liveCompactPair(
      record?.pair ||
        record?.symbol ||
        record?.pairLabel
    );

  const mode =
    liveNormalizeMode(
      record?.mode ||
        record?.engine ||
        "master",
      "master"
    );

  return `${pair}:${mode}`;
}

function liveNotifySignature(record) {
  return liveHistoryFingerprint(
    record
  );
}


// ---------------------------------------------------------------------------
// Telegram notification eligibility
// ---------------------------------------------------------------------------
function shouldSendTelegramNotification(
  rawNotifyState,
  engineResult,
  options = {}
) {
  const state =
    normalizeNotifyState(rawNotifyState);

  const canonical =
    buildCanonicalEngineResult(
      engineResult,
      {
        pair:
          options.pair ||
          engineResult?.pair,

        mode:
          options.mode ||
          engineResult?.mode ||
          "master",
      }
    );

  const decision =
    canonical.decision;

  if (
    decision === "HOLD" &&
    options.notifyHold !== true
  ) {
    return {
      shouldSend: false,
      reason: "HOLD notifications are disabled",
      state,
      canonical,
    };
  }

  const minimumConfidence =
    liveNormalizeConfidence(
      options.minimumConfidence,
      0
    );

  if (
    canonical.confidence <
    minimumConfidence
  ) {
    return {
      shouldSend: false,
      reason:
        `Confidence ${canonical.confidence}% is below ${minimumConfidence}%`,
      state,
      canonical,
    };
  }

  const key =
    liveNotifyStateKey(canonical);

  const signature =
    liveNotifySignature(canonical);

  const previous =
    liveIsPlainObject(state.signals[key])
      ? state.signals[key]
      : null;

  const cooldownMs = Math.max(
    0,
    liveFiniteNumber(
      options.cooldownMs,
      4 * 60 * 60 * 1000
    )
  );

  if (previous) {
    const previousSignature =
      liveNonEmptyString(
        previous.signature ||
          previous.fingerprint
      );

    const previousSentAt =
      liveStableTimestamp(
        previous.sentAt ||
          previous.timestamp ||
          previous.updatedAt,
        0
      );

    const stillInCooldown =
      cooldownMs > 0 &&
      previousSentAt > 0 &&
      Date.now() - previousSentAt <
        cooldownMs;

    if (
      previousSignature === signature &&
      stillInCooldown
    ) {
      return {
        shouldSend: false,
        reason:
          "An identical signal was already notified within the cooldown window",
        state,
        canonical,
        key,
        signature,
      };
    }
  }

  return {
    shouldSend: true,
    reason: "Signal is eligible for notification",
    state,
    canonical,
    key,
    signature,
  };
}

function updateNotifyStateAfterSend(
  rawNotifyState,
  engineResult,
  options = {}
) {
  const eligibility =
    shouldSendTelegramNotification(
      rawNotifyState,
      engineResult,
      {
        ...options,
        cooldownMs: 0,
      }
    );

  const state =
    eligibility.state;

  const canonical =
    eligibility.canonical;

  const key =
    eligibility.key ||
    liveNotifyStateKey(
      canonical
    );

  const signature =
    eligibility.signature ||
    liveNotifySignature(
      canonical
    );

  const sentAt =
    liveNowIso();

  const finalConfidence =
    liveNormalizeConfidence(
      canonical.confidence,
      0
    );

  const originalConfidence =
    liveNormalizeConfidence(
      canonical.originalConfidence ??
        canonical.aiMemory
          ?.originalConfidence ??
        finalConfidence,
      finalConfidence
    );

  const appliedConfidenceAdjustment =
    liveFiniteNumber(
      canonical.aiMemory
        ?.appliedConfidenceAdjustment ??
        canonical.aiMemory
          ?.confidenceAdjustment,
      0
    );

  const signals = {
    ...state.signals,

    [key]: {
      pair:
        canonical.pair,

      mode:
        canonical.mode,

      decision:
        canonical.decision,

      // Final adjusted confidence used in
      // the Telegram eligibility check.
      confidence:
        finalConfidence,

      // Additive Phase 4 audit fields.
      originalConfidence,

      aiMemoryAdjustedConfidence:
        finalConfidence,

      appliedConfidenceAdjustment,

      aiMemoryApplied:
        canonical.aiMemory
          ?.applied === true,

      signature,

      fingerprint:
        signature,

      sentAt,

      updatedAt:
        sentAt,

      timestamp:
        Date.now(),

      messageId:
        options.messageId ||
        null,
    },
  };

  return {
    ...state,

    updatedAt:
      sentAt,

    signals,

    notifications:
      signals,

    state:
      signals,
  };
}


// ---------------------------------------------------------------------------
// Telegram formatting
// ---------------------------------------------------------------------------
function liveEscapeTelegramHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function liveFormatTelegramPrice(
  value,
  pair
) {
  const parsed =
    liveFiniteNumber(value);

  if (!Number.isFinite(parsed)) {
    return "—";
  }

  const decimals =
    typeof livePairPriceDecimals ===
    "function"
      ? livePairPriceDecimals(pair)
      : liveCompactPair(pair)
          .endsWith("JPY")
        ? 3
        : liveCompactPair(pair) ===
            "XAUUSD"
          ? 2
          : 5;

  return parsed.toFixed(decimals);
}

function liveDecisionEmoji(decision) {
  const normalized =
    normalizeLiveDecision(decision);

  if (normalized === "BUY") {
    return "🟢";
  }

  if (normalized === "SELL") {
    return "🔴";
  }

  return "🟡";
}

function formatTelegramSignalMessage(
  engineResult,
  options = {}
) {
  const canonical =
    buildCanonicalEngineResult(
      engineResult,
      {
        pair:
          options.pair ||
          engineResult?.pair,

        mode:
          options.mode ||
          engineResult?.mode ||
          "master",
      }
    );

  const emoji =
    liveDecisionEmoji(
      canonical.decision
    );

  const title =
    options.title ||
    "PipSight Pro Signal";

  const lines = [
    `<b>${liveEscapeTelegramHtml(
      title
    )}</b>`,

    "",

    `${emoji} <b>${liveEscapeTelegramHtml(
      canonical.decision
    )}</b>`,

    `<b>Pair:</b> ${liveEscapeTelegramHtml(
      canonical.pair
    )}`,

    `<b>Engine:</b> ${liveEscapeTelegramHtml(
      canonical.mode.toUpperCase()
    )}`,

    `<b>Confidence:</b> ${
      canonical.confidence
    }%`,
  ];

  if (
    Number.isFinite(
      canonical.price
    )
  ) {
    lines.push(
      `<b>Market:</b> ${liveFormatTelegramPrice(
        canonical.price,
        canonical.pair
      )}`
    );
  }

  if (
    canonical.decision !== "HOLD" &&
    canonical.tradePlan
  ) {
    lines.push("");

    lines.push(
      `<b>Entry:</b> ${liveFormatTelegramPrice(
        canonical.entry,
        canonical.pair
      )}`
    );

    lines.push(
      `<b>Stop Loss:</b> ${liveFormatTelegramPrice(
        canonical.stopLoss,
        canonical.pair
      )}`
    );

    lines.push(
      `<b>TP1:</b> ${liveFormatTelegramPrice(
        canonical.target1,
        canonical.pair
      )}`
    );

    if (
      Number.isFinite(
        canonical.target2
      )
    ) {
      lines.push(
        `<b>TP2:</b> ${liveFormatTelegramPrice(
          canonical.target2,
          canonical.pair
        )}`
      );
    }

    if (
      Number.isFinite(
        canonical.target3
      )
    ) {
      lines.push(
        `<b>TP3:</b> ${liveFormatTelegramPrice(
          canonical.target3,
          canonical.pair
        )}`
      );
    }

    if (
      Number.isFinite(
        canonical.riskReward
      )
    ) {
      lines.push(
        `<b>Risk:Reward:</b> 1:${
          canonical.riskReward.toFixed(
            2
          )
        }`
      );
    }
  }

  if (canonical.reason) {
    lines.push("");

    lines.push(
      `<b>Reason:</b> ${liveEscapeTelegramHtml(
        canonical.reason
      )}`
    );
  }

  lines.push("");

  lines.push(
    `<i>${liveEscapeTelegramHtml(
      new Date(
        canonical.timestamp
      ).toISOString()
    )}</i>`
  );

  return lines.join("\n");
}


// ---------------------------------------------------------------------------
// Telegram transport
// ---------------------------------------------------------------------------
function liveTelegramConfig(options = {}) {
  const token =
    options.token ||
    options.botToken ||
    process.env.TELEGRAM_BOT_TOKEN ||
    process.env.TELEGRAM_TOKEN ||
    "";

  const chatId =
    options.chatId ||
    options.chat_id ||
    process.env.TELEGRAM_CHAT_ID ||
    "";

  return {
    token:
      liveNonEmptyString(token),

    chatId:
      liveNonEmptyString(chatId),

    enabled:
      Boolean(
        liveNonEmptyString(token) &&
        liveNonEmptyString(chatId)
      ),

    timeoutMs:
      Math.max(
        1000,
        liveFiniteNumber(
          options.timeoutMs,
          typeof TELEGRAM_TIMEOUT_MS !==
            "undefined"
            ? TELEGRAM_TIMEOUT_MS
            : 15000
        )
      ),
  };
}

async function sendTelegramMessage(
  message,
  options = {}
) {
  const config =
    liveTelegramConfig(options);

  if (!config.enabled) {
    return {
      ok: false,
      skipped: true,

      reason:
        "Telegram token or chat ID is not configured",
    };
  }

  if (
    typeof fetch !== "function"
  ) {
    return {
      ok: false,
      skipped: true,

      reason:
        "Global fetch is unavailable in this Node.js runtime",
    };
  }

  const controller =
    typeof AbortController ===
    "function"
      ? new AbortController()
      : null;

  const timeoutHandle =
    setTimeout(() => {
      if (controller) {
        controller.abort();
      }
    }, config.timeoutMs);

  try {
    const response =
      await fetch(
        `https://api.telegram.org/bot${config.token}/sendMessage`,
        {
          method: "POST",

          headers: {
            "content-type":
              "application/json",
          },

          body:
            JSON.stringify({
              chat_id:
                config.chatId,

              text:
                String(
                  message || ""
                ),

              parse_mode:
                options.parseMode ||
                "HTML",

              disable_web_page_preview:
                true,

              disable_notification:
                options
                  .disableNotification ===
                true,
            }),

          signal:
            controller
              ? controller.signal
              : undefined,
        }
      );

    let payload = null;

    try {
      payload =
        await response.json();
    } catch {
      payload = null;
    }

    if (
      !response.ok ||
      payload?.ok === false
    ) {
      return {
        ok: false,
        skipped: false,

        status:
          response.status,

        reason:
          payload?.description ||
          `Telegram HTTP ${response.status}`,

        payload,
      };
    }

    return {
      ok: true,
      skipped: false,

      status:
        response.status,

      messageId:
        payload?.result
          ?.message_id ||
        null,

      payload,
    };
  } catch (error) {
    const aborted =
      error &&
      (
        error.name ===
          "AbortError" ||
        String(
          error.message || ""
        )
          .toLowerCase()
          .includes("abort")
      );

    return {
      ok: false,
      skipped: false,

      reason:
        aborted
          ? `Telegram request timed out after ${config.timeoutMs}ms`
          : `Telegram request failed: ${
              error?.message ||
              String(error)
            }`,
    };
  } finally {
    clearTimeout(
      timeoutHandle
    );
  }
}


// ---------------------------------------------------------------------------
// Telegram processing for one engine
// ---------------------------------------------------------------------------
async function processTelegramNotification(
  rawNotifyState,
  engineResult,
  options = {}
) {
  const eligibility =
    shouldSendTelegramNotification(
      rawNotifyState,
      engineResult,
      options
    );

  if (!eligibility.shouldSend) {
    return {
      sent: false,
      skipped: true,

      reason: eligibility.reason,

      notifyState:
        eligibility.state,

      engine:
        eligibility.canonical,
    };
  }

  const message =
    options.message ||
    formatTelegramSignalMessage(
      eligibility.canonical,
      options
    );

  const sendFunction =
    typeof options.sendMessage ===
      "function"
      ? options.sendMessage
      : sendTelegramMessage;

  const sendResult =
    await sendFunction(
      message,
      options
    );

  if (!sendResult.ok) {
    return {
      sent: false,
      skipped:
        sendResult.skipped === true,

      reason:
        sendResult.reason ||
        "Telegram send failed",

      sendResult,

      notifyState:
        eligibility.state,

      engine:
        eligibility.canonical,
    };
  }

  const notifyState =
    updateNotifyStateAfterSend(
      eligibility.state,
      eligibility.canonical,
      {
        ...options,

        messageId:
          sendResult.messageId,
      }
    );

  return {
    sent: true,
    skipped: false,

    reason:
      "Telegram notification sent",

    sendResult,
    notifyState,

    engine:
      eligibility.canonical,

    message,
  };
}


// ---------------------------------------------------------------------------
// Telegram processing for complete live output
// ---------------------------------------------------------------------------

async function processLiveOutputNotifications(
  liveOutput,
  rawNotifyState,
  options = {}
) {
  let notifyState =
    normalizeNotifyState(rawNotifyState);

  const results = [];

  const modes = Array.isArray(options.modes)
    ? options.modes.map((mode) =>
        liveNormalizeMode(mode)
      )
    : ["master"];

  const pairRecords =
    liveIsPlainObject(liveOutput?.pairs)
      ? Object.values(liveOutput.pairs)
      : liveAsArray(liveOutput?.results);

  for (const pairRecord of pairRecords) {
    if (!liveIsPlainObject(pairRecord)) {
      continue;
    }

    const pair =
      liveNormalizePairLabel(
        pairRecord.pair ||
          pairRecord.symbol
      );

    for (const mode of modes) {
      const engineResult =
        pairRecord[mode] ||
        pairRecord.engines?.[mode] ||
        pairRecord.modes?.[mode];

      if (!liveIsPlainObject(engineResult)) {
        continue;
      }

      const result =
        await processTelegramNotification(
          notifyState,
          engineResult,
          {
            ...options,
            pair,
            mode,
          }
        );

      notifyState =
        result.notifyState ||
        notifyState;

      if (
        result.sent === true &&
        typeof options.persistNotifyState ===
          "function"
      ) {
        await options.persistNotifyState(
          notifyState,
          {
            pair,
            mode,
            result,
          }
        );
      }

      results.push({
        pair,
        mode,
        sent: result.sent,
        skipped: result.skipped,
        reason: result.reason,

        messageId:
          result.sendResult?.messageId ||
          null,
      });
    }
  }

  return {
    notifyState: {
      ...notifyState,
      updatedAt: liveNowIso(),
    },

    results,

    sentCount: results.filter(
      (result) => result.sent
    ).length,

    skippedCount: results.filter(
      (result) => result.skipped
    ).length,

    failedCount: results.filter(
      (result) =>
        !result.sent &&
        !result.skipped
    ).length,
  };
}


// ---------------------------------------------------------------------------
// Complete output/history/notification assembly
// ---------------------------------------------------------------------------
async function assembleLiveAnalysisArtifacts(
  input = {}
) {
  const output =
    buildLiveAnalysisOutput({
      pairs:
        input.pairBundles ||
        input.pairs ||
        [],

      timestamp:
        input.timestamp,

      generatedAt:
        input.generatedAt,

      engineVersion:
        input.engineVersion,

      strategyVersion:
        input.strategyVersion,
    });

  const historyCandidates =
    collectHistoryRecordsFromOutput(
      output,
      {
        modes:
          input.historyModes ||
          ["master", "swing", "intraday", "scalp"],

        includeHold:
          input.includeHoldHistory === true,
      }
    );

  const historyResult =
    appendAnalysisHistoryRecords(
      input.analysisHistory ||
        input.history ||
        {},
      historyCandidates,
      {
        includeHold:
          input.includeHoldHistory === true,

        dedupeWindowMs:
          input.historyDedupeWindowMs,

        maximumRecords:
          input.maximumHistoryRecords,

        engineVersion:
          output.engineVersion,

        strategyVersion:
          output.strategyVersion,
      }
    );

  let notificationResult = {
    notifyState:
      normalizeNotifyState(
        input.notifyState
      ),

    results: [],
    sentCount: 0,
    skippedCount: 0,
    failedCount: 0,
  };

  if (input.processTelegram !== false) {
    notificationResult =
      await processLiveOutputNotifications(
        output,
        input.notifyState,
        {
          modes:
            input.telegramModes ||
            ["master"],

          minimumConfidence:
            input.telegramMinimumConfidence,

          cooldownMs:
            input.telegramCooldownMs,

          notifyHold:
            input.telegramNotifyHold === true,

          token:
            input.telegramToken,

          chatId:
            input.telegramChatId,

          timeoutMs:
            input.telegramTimeoutMs,

          disableNotification:
            input.telegramSilent === true,

          title:
            input.telegramTitle ||
            "PipSight Pro Signal",
        }
      );
  }

  return {
    output,

    history:
      historyResult.history,

    appendedHistory:
      historyResult.appended,

    appendedHistoryCount:
      historyResult.appendedCount,

    notifyState:
      notificationResult.notifyState,

    telegram:
      {
        results:
          notificationResult.results,

        sentCount:
          notificationResult.sentCount,

        skippedCount:
          notificationResult.skippedCount,

        failedCount:
          notificationResult.failedCount,
      },
  };
}


