// ---------------------------------------------------------------------------
// Runtime logging
// ---------------------------------------------------------------------------

function p6Log(
  level,
  message,
  details
) {
  const timestamp =
    new Date().toISOString();

  const prefix =
    `[${timestamp}] [${level}]`;

  if (
    details === undefined
  ) {
    console.log(
      prefix,
      message
    );

    return;
  }

  console.log(
    prefix,
    message,
    details
  );
}

function p6ErrorMessage(
  error
) {
  if (!error) {
    return "Unknown error";
  }

  if (
    typeof error === "string"
  ) {
    return error;
  }

  if (
    typeof error.message ===
    "string"
  ) {
    return error.message;
  }

  try {
    return JSON.stringify(error);
  } catch {
    return String(error);
  }
}


// ---------------------------------------------------------------------------
// Path and file helpers
// ---------------------------------------------------------------------------

function p6EnsureDirectory(
  directoryPath
) {
  fs.mkdirSync(
    directoryPath,
    {
      recursive: true,
    }
  );
}

function p6ResolvePath(
  value,
  fallbackPath
) {
  if (
    typeof value !== "string" ||
    !value.trim()
  ) {
    return fallbackPath;
  }

  const trimmed =
    value.trim();

  return path.isAbsolute(trimmed)
    ? trimmed
    : path.resolve(
        __dirname,
        trimmed
      );
}

function p6PathExists(
  filePath
) {
  try {
    return fs.existsSync(
      filePath
    );
  } catch {
    return false;
  }
}

function p6ReadJsonFile(
  filePath,
  fallbackValue = null,
  options = {}
) {
  const required =
    options.required === true;

  if (!p6PathExists(filePath)) {
    if (required) {
      throw new Error(
        `Required JSON file is missing: ${filePath}`
      );
    }

    return fallbackValue;
  }

  let raw;

  try {
    raw =
      fs.readFileSync(
        filePath,
        "utf8"
      );
  } catch (error) {
    if (required) {
      throw new Error(
        `Unable to read required JSON file ${filePath}: ` +
        p6ErrorMessage(error)
      );
    }

    p6Log(
      "WARN",
      `Unable to read optional JSON file ${filePath}`,
      p6ErrorMessage(error)
    );

    return fallbackValue;
  }

  if (!raw.trim()) {
    if (required) {
      throw new Error(
        `Required JSON file is empty: ${filePath}`
      );
    }

    return fallbackValue;
  }

  try {
    return JSON.parse(raw);
  } catch (error) {
    if (required) {
      throw new Error(
        `Required JSON file contains invalid JSON ${filePath}: ` +
        p6ErrorMessage(error)
      );
    }

    p6Log(
      "WARN",
      `Optional JSON file contains invalid JSON ${filePath}`,
      p6ErrorMessage(error)
    );

    return fallbackValue;
  }
}

function p6AtomicWriteJson(
  filePath,
  value
) {
  p6EnsureDirectory(
    path.dirname(filePath)
  );

  const temporaryPath =
    `${filePath}.${process.pid}.${Date.now()}.tmp`;

  try {
    fs.writeFileSync(
      temporaryPath,
      JSON.stringify(
        value,
        null,
        2
      ),
      "utf8"
    );

    fs.renameSync(
      temporaryPath,
      filePath
    );
  } finally {
    /*
     * Clean up any temporary file left by either a partial write failure
     * or a failed rename. The destination file remains untouched unless
     * the rename succeeds.
     */
    if (
      p6PathExists(
        temporaryPath
      )
    ) {
      try {
        fs.unlinkSync(
          temporaryPath
        );
      } catch {
        // Cleanup failure must not hide the original filesystem error.
      }
    }
  }
}

function p6CreateBackupIfRequested(
  filePath,
  enabled
) {
  if (
    enabled !== true ||
    !p6PathExists(filePath)
  ) {
    return null;
  }

  const backupPath =
    `${filePath}.backup-${Date.now()}`;

  fs.copyFileSync(
    filePath,
    backupPath
  );

  return backupPath;
}


// ---------------------------------------------------------------------------
// Generic runtime object helpers
// ---------------------------------------------------------------------------

function p6IsObject(
  value
) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function p6AsArray(
  value
) {
  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined
  ) {
    return [];
  }

  return [value];
}

function p6FirstString(
  ...values
) {
  for (const value of values) {
    if (
      typeof value === "string" &&
      value.trim()
    ) {
      return value.trim();
    }
  }

  return null;
}

function p6FirstFinite(
  ...values
) {
  for (const value of values) {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      continue;
    }

    const numeric =
      Number(value);

    if (
      Number.isFinite(numeric)
    ) {
      return numeric;
    }
  }

  return null;
}

function p6NormalizeToken(
  value
) {
  if (
    typeof value !== "string"
  ) {
    return "";
  }

  return value
    .trim()
    .toUpperCase()
    .replace(
      /[^A-Z0-9]/g,
      ""
    );
}

function p6NormalizePairLabel(
  value
) {
  if (
    typeof liveNormalizePairLabel ===
    "function"
  ) {
    return liveNormalizePairLabel(
      value
    );
  }

  const token =
    p6NormalizeToken(value);

  if (token === "XAUUSD") {
    return "XAU/USD";
  }

  if (token === "GBPJPY") {
    return "GBP/JPY";
  }

  return value || "UNKNOWN";
}

function p6NormalizePairKey(
  value
) {
  const token =
    p6NormalizeToken(value);

  if (
    token === "XAUUSD" ||
    token === "GOLD"
  ) {
    return "XAUUSD";
  }

  if (token === "GBPJPY") {
    return "GBPJPY";
  }

  return null;
}

function p6Clone(
  value
) {
  if (
    typeof structuredClone ===
    "function"
  ) {
    try {
      return structuredClone(value);
    } catch {
      // Continue to JSON fallback.
    }
  }

  try {
    return JSON.parse(
      JSON.stringify(value)
    );
  } catch {
    return value;
  }
}


// ---------------------------------------------------------------------------
// Runtime option normalization
// ---------------------------------------------------------------------------

function p6BuildRuntimeOptions(
  options = {}
) {
  const merged = {
    ...P6_DEFAULT_OPTIONS,
    ...options,
  };

  return {
    ...merged,

    scalpSignalsPath:
      p6ResolvePath(
        merged.scalpSignalsPath,
        P6_SCALP_SIGNALS_PATH
      ),

    scalpCandlesPath:
      p6ResolvePath(
        merged.scalpCandlesPath,
        P6_SCALP_CANDLES_PATH
      ),

    intradayH1Path:
      p6ResolvePath(
        merged.intradayH1Path,
        P6_INTRADAY_H1_PATH
      ),

    dailyOhlcPath:
      p6ResolvePath(
        merged.dailyOhlcPath,
        P6_DAILY_OHLC_PATH
      ),

    liveAnalysisPath:
      p6ResolvePath(
        merged.liveAnalysisPath,
        P6_LIVE_ANALYSIS_PATH
      ),

    analysisHistoryPath:
      p6ResolvePath(
        merged.analysisHistoryPath,
        P6_ANALYSIS_HISTORY_PATH
      ),

    notifyStatePath:
      p6ResolvePath(
        merged.notifyStatePath,
        P6_NOTIFY_STATE_PATH
      ),

    includeActiveCandle:
      merged.includeActiveCandle !== false,

    includeHoldHistory:
      merged.includeHoldHistory === true,

    processTelegram:
      merged.processTelegram !== false,

    createBackups:
      merged.createBackups === true,

    autonomousControlEnabled:
      merged.autonomousControlEnabled !==
      false,

    autonomousPersistAudit:
      merged.autonomousPersistAudit !==
      false,

    // SHADOW is immutable: runtime options cannot promote it into live output.
    autonomousApplyShadowOutput:
      false,

    autonomousExecutionContext:
      "SIGNAL_ONLY",

    autonomousFailClosedInLiveAuthorityModes:
      merged
        .autonomousFailClosedInLiveAuthorityModes !==
      false,

    autonomousConfigPath:
      p6ResolvePath(
        merged.autonomousConfigPath,
        AUTONOMOUS_CONFIG_PATH
      ),

    aiPolicyPath:
      p6ResolvePath(
        merged.aiPolicyPath,
        AI_POLICY_PATH
      ),

    aiPolicyStatePath:
      p6ResolvePath(
        merged.aiPolicyStatePath,
        AI_POLICY_STATE_PATH
      ),

    aiDecisionEnginePath:
      p6ResolvePath(
        merged.aiDecisionEnginePath,
        AI_DECISION_ENGINE_PATH
      ),

    aiSafetyGatePath:
      p6ResolvePath(
        merged.aiSafetyGatePath,
        AI_SAFETY_GATE_PATH
      ),

    aiDecisionPreviewPath:
      p6ResolvePath(
        merged.aiDecisionPreviewPath,
        AI_DECISION_PREVIEW_PATH
      ),

    aiDecisionLogPath:
      p6ResolvePath(
        merged.aiDecisionLogPath,
        AI_DECISION_LOG_PATH
      ),

    aiDecisionStatePath:
      p6ResolvePath(
        merged.aiDecisionStatePath,
        AI_DECISION_STATE_PATH
      ),

    aiSafetyPreviewPath:
      p6ResolvePath(
        merged.aiSafetyPreviewPath,
        AI_SAFETY_PREVIEW_PATH
      ),

    aiSafetyLogPath:
      p6ResolvePath(
        merged.aiSafetyLogPath,
        AI_SAFETY_LOG_PATH
      ),

    aiSafetyStatePath:
      p6ResolvePath(
        merged.aiSafetyStatePath,
        AI_SAFETY_STATE_PATH
      ),

    aiSafetyPendingPath:
      p6ResolvePath(
        merged.aiSafetyPendingPath,
        AI_SAFETY_PENDING_PATH
      ),
  };
}


// ---------------------------------------------------------------------------
// Input structure discovery
// ---------------------------------------------------------------------------

function p6FindPairValue(
  raw,
  pairConfig
) {
  if (
    raw === null ||
    raw === undefined
  ) {
    return null;
  }

  const aliases =
    new Set(
      pairConfig.aliases.map(
        p6NormalizeToken
      )
    );

  const visited =
    new Set();

  function search(
    value,
    depth
  ) {
    if (
      value === null ||
      value === undefined ||
      depth > 8
    ) {
      return null;
    }

    if (
      typeof value === "object"
    ) {
      if (visited.has(value)) {
        return null;
      }

      visited.add(value);
    }

    if (Array.isArray(value)) {
      for (
        const item of value
      ) {
        if (
          p6IsObject(item)
        ) {
          const declaredPair =
            p6FirstString(
              item.pair,
              item.symbol,
              item.pairLabel,
              item.instrument,
              item.market
            );

          if (
            declaredPair &&
            aliases.has(
              p6NormalizeToken(
                declaredPair
              )
            )
          ) {
            return item;
          }
        }
      }

      for (
        const item of value
      ) {
        const nested =
          search(
            item,
            depth + 1
          );

        if (
          nested !== null &&
          nested !== undefined
        ) {
          return nested;
        }
      }

      return null;
    }

    if (!p6IsObject(value)) {
      return null;
    }

    for (
      const [
        key,
        nestedValue,
      ] of Object.entries(value)
    ) {
      if (
        aliases.has(
          p6NormalizeToken(key)
        )
      ) {
        return nestedValue;
      }
    }

    const declaredPair =
      p6FirstString(
        value.pair,
        value.symbol,
        value.pairLabel,
        value.instrument,
        value.market
      );

    if (
      declaredPair &&
      aliases.has(
        p6NormalizeToken(
          declaredPair
        )
      )
    ) {
      return value;
    }

    const preferredContainers = [
      value.pairs,
      value.results,
      value.data,
      value.signals,
      value.records,
      value.items,
      value.analyses,
      value.markets,
      value.instruments,
      value.payload,
    ];

    for (
      const container of
      preferredContainers
    ) {
      const nested =
        search(
          container,
          depth + 1
        );

      if (
        nested !== null &&
        nested !== undefined
      ) {
        return nested;
      }
    }

    return null;
  }

  return search(raw, 0);
}

function p6ExtractArrayCandidate(
  raw,
  preferredKeys = []
) {
  if (Array.isArray(raw)) {
    return raw;
  }

  if (!p6IsObject(raw)) {
    return [];
  }

  for (
    const key of preferredKeys
  ) {
    if (
      Array.isArray(raw[key])
    ) {
      return raw[key];
    }
  }

  const commonKeys = [
    "candles",
    "rows",
    "data",
    "records",
    "items",
    "prices",
    "ohlc",
    "history",
  ];

  for (
    const key of commonKeys
  ) {
    if (
      Array.isArray(raw[key])
    ) {
      return raw[key];
    }
  }

  return [];
}

function p6ExtractPairCandles(
  raw,
  pairConfig,
  preferredKeys = []
) {
  const pairValue =
    p6FindPairValue(
      raw,
      pairConfig
    );

  const fromPair =
    p6ExtractArrayCandidate(
      pairValue,
      preferredKeys
    );

  if (fromPair.length > 0) {
    return fromPair;
  }

  const direct =
    p6ExtractArrayCandidate(
      raw,
      preferredKeys
    );

  if (
    direct.length > 0 &&
    P6_RUNTIME_PAIRS.length === 1
  ) {
    return direct;
  }

  return [];
}

function p6ExtractPairSignal(
  raw,
  pairConfig
) {
  const pairValue =
    p6FindPairValue(
      raw,
      pairConfig
    );

  if (
    p6IsObject(pairValue)
  ) {
    return pairValue;
  }

  if (
    Array.isArray(pairValue)
  ) {
    return (
      pairValue.find(
        p6IsObject
      ) ||
      null
    );
  }

  return null;
}


// ---------------------------------------------------------------------------
// Runtime source loading
// ---------------------------------------------------------------------------

function p6LoadRuntimeSources(
  runtimeOptions
) {
  const scalpSignals =
    p6ReadJsonFile(
      runtimeOptions.scalpSignalsPath,
      {},
      {
        required: false,
      }
    );

  const scalpCandles =
    p6ReadJsonFile(
      runtimeOptions.scalpCandlesPath,
      {},
      {
        required: false,
      }
    );

  const intradayH1 =
    p6ReadJsonFile(
      runtimeOptions.intradayH1Path,
      {},
      {
        required: false,
      }
    );

  const dailyOhlc =
    p6ReadJsonFile(
      runtimeOptions.dailyOhlcPath,
      {},
      {
        required: false,
      }
    );

  const analysisHistory =
    p6ReadJsonFile(
      runtimeOptions.analysisHistoryPath,
      {},
      {
        required: false,
      }
    );

  const notifyState =
    p6ReadJsonFile(
      runtimeOptions.notifyStatePath,
      {},
      {
        required: false,
      }
    );

  return {
    scalpSignals,
    scalpCandles,
    intradayH1,
    dailyOhlc,
    analysisHistory,
    notifyState,
  };
}


// ---------------------------------------------------------------------------
// Pair input assembly
// ---------------------------------------------------------------------------

function p6BuildPairInput(
  pairConfig,
  sources,
  runtimeOptions
) {
  const dedicatedScalp =
    p6ExtractPairSignal(
      sources.scalpSignals,
      pairConfig
    );

  const scalpRows =
    p6ExtractPairCandles(
      sources.scalpCandles,
      pairConfig,
      [
        "candles",
        "rows",
        "data",
      ]
    );

  const h1Rows =
    p6ExtractPairCandles(
      sources.intradayH1,
      pairConfig,
      [
        "candles",
        "rows",
        "data",
      ]
    );

  const dailyRows =
    p6ExtractPairCandles(
      sources.dailyOhlc,
      pairConfig,
      [
        "candles",
        "rows",
        "data",
        "ohlc",
      ]
    );

  return {
    pair:
      pairConfig.label,

    symbol:
      pairConfig.label,

    pairKey:
      pairConfig.key,

    scalpSignals:
      sources.scalpSignals,

    dedicatedScalp,

    scalpRows,
    m5Rows: scalpRows,
    lowerTimeframeRows: scalpRows,

    h1Rows,
    intradayRows: h1Rows,

    dailyRows,
    dailyCandles: dailyRows,

    includeActiveCandle:
      runtimeOptions
        .includeActiveCandle,

    timestamp:
      Date.now(),
  };
}


// ---------------------------------------------------------------------------
// Runtime pair validation
// ---------------------------------------------------------------------------

function p6ValidatePairInput(
  pairInput
) {
  const warnings = [];

  if (
    !Array.isArray(
      pairInput.scalpRows
    ) ||
    pairInput.scalpRows.length === 0
  ) {
    warnings.push(
      "Scalp candle source is empty"
    );
  }

  if (
    !Array.isArray(
      pairInput.h1Rows
    ) ||
    pairInput.h1Rows.length === 0
  ) {
    warnings.push(
      "H1 candle source is empty"
    );
  }

  if (
    !Array.isArray(
      pairInput.dailyRows
    ) ||
    pairInput.dailyRows.length === 0
  ) {
    warnings.push(
      "Daily candle source is empty"
    );
  }

  if (
    !pairInput.dedicatedScalp
  ) {
    warnings.push(
      "Dedicated Scalp signal is unavailable; candle fallback may be used"
    );
  }

  return {
    valid: true,
    warnings,
  };
}


// ---------------------------------------------------------------------------
// Pair pipeline execution
// ---------------------------------------------------------------------------

function p6RunPairPipeline(
  pairInput,
  runtimeOptions
) {
  const validation =
    p6ValidatePairInput(
      pairInput
    );

  for (
    const warning of
    validation.warnings
  ) {
    p6Log(
      "WARN",
      `${pairInput.pair}: ${warning}`
    );
  }

  const bundle =
    buildPairEngineBundle({
      ...pairInput,

      includeActiveCandle:
        runtimeOptions
          .includeActiveCandle,
    });

  return {
    ...bundle,

    runtime: {
      validation,

      sourceCounts: {
        scalp:
          pairInput.scalpRows.length,

        h1:
          pairInput.h1Rows.length,

        daily:
          pairInput.dailyRows.length,
      },

      dedicatedScalpAvailable:
        Boolean(
          pairInput.dedicatedScalp
        ),
    },
  };
}


// ---------------------------------------------------------------------------
// Runtime summary
// ---------------------------------------------------------------------------

function p6BuildRuntimeSummary(
  output,
  telegramResult,
  appendedHistoryCount
) {
  const pairs =
    p6IsObject(output?.pairs)
      ? Object.values(
          output.pairs
        )
      : [];

  return {
    generatedAt:
      output?.generatedAt ||
      new Date().toISOString(),

    pairCount:
      pairs.length,

    decisions:
      pairs.map(
        (pairRecord) => ({
          pair:
            pairRecord.pair,

          swing:
            pairRecord.swing
              ?.decision ||
            "HOLD",

          intraday:
            pairRecord.intraday
              ?.decision ||
            "HOLD",

          scalp:
            pairRecord.scalp
              ?.decision ||
            "HOLD",

          master:
            pairRecord.master
              ?.decision ||
            "HOLD",
        })
      ),

    historyAppended:
      appendedHistoryCount,

    autonomous:
      p6Clone(
        output?.autonomous ||
        null
      ),

    telegram: {
      sent:
        telegramResult.sentCount,

      skipped:
        telegramResult.skippedCount,

      failed:
        telegramResult.failedCount,
    },
  };
}


// ---------------------------------------------------------------------------
// Startup validation
// ---------------------------------------------------------------------------

function p6ValidateStartup(
  runtimeOptions
) {
  const errors = [];

  if (
    typeof fs === "undefined" ||
    typeof path === "undefined"
  ) {
    errors.push(
      "Node.js fs/path modules are unavailable"
    );
  }

  if (
    typeof buildPairEngineBundle !==
    "function"
  ) {
    errors.push(
      "buildPairEngineBundle() is unavailable"
    );
  }

  if (
    typeof buildLiveAnalysisOutput !==
    "function"
  ) {
    errors.push(
      "buildLiveAnalysisOutput() is unavailable"
    );
  }

  if (
    typeof appendAnalysisHistoryRecords !==
    "function"
  ) {
    errors.push(
      "appendAnalysisHistoryRecords() is unavailable"
    );
  }

  if (
    typeof processLiveOutputNotifications !==
    "function"
  ) {
    errors.push(
      "processLiveOutputNotifications() is unavailable"
    );
  }

  const outputPaths = [
    runtimeOptions.liveAnalysisPath,
    runtimeOptions.analysisHistoryPath,
    runtimeOptions.notifyStatePath,
  ];

  for (
    const outputPath of outputPaths
  ) {
    if (
      typeof outputPath !== "string" ||
      !outputPath.trim()
    ) {
      errors.push(
        "One or more output paths are invalid"
      );

      break;
    }
  }

  return {
    valid:
      errors.length === 0,

    errors,
  };
}


// ---------------------------------------------------------------------------
// Final live-analysis runtime
// ---------------------------------------------------------------------------
async function runLiveAnalysisRuntime(
  options = {}
) {
  const runtimeOptions =
    p6BuildRuntimeOptions(
      options
    );

  const startupValidation =
    p6ValidateStartup(
      runtimeOptions
    );

  if (!startupValidation.valid) {
    throw new Error(
      "Live analysis startup validation failed: " +
      startupValidation.errors.join("; ")
    );
  }

  p6EnsureDirectory(
    P6_DATA_DIRECTORY
  );

  const sources =
    p6LoadRuntimeSources(
      runtimeOptions
    );

  const aiMemoryState =
    loadAIMemory();

  const pairBundles = [];

  for (
    const pairConfig of
    P6_RUNTIME_PAIRS
  ) {
    try {
      p6Log(
        "INFO",
        `Starting ${pairConfig.label} analysis`
      );

      const pairInput = {
        ...p6BuildPairInput(
          pairConfig,
          sources,
          runtimeOptions
        ),

        aiMemoryState,

        allowPrimaryScalpHold:
          runtimeOptions
            .allowPrimaryScalpHold,

        maximumPrimaryScalpAgeMs:
          runtimeOptions
            .maximumPrimaryScalpAgeMs,

        minimumNetContribution:
          runtimeOptions
            .minimumNetContribution,

        minimumDirectionalEngines:
          runtimeOptions
            .minimumDirectionalEngines,

        masterWeights:
          runtimeOptions
            .masterWeights,
      };

      const bundle =
        p6RunPairPipeline(
          pairInput,
          runtimeOptions
        );

      pairBundles.push(
        bundle
      );

      p6Log(
        "INFO",
        `${pairConfig.label} analysis completed`,
        {
          swing:
            bundle.swing?.decision ||
            "HOLD",

          intraday:
            bundle.intraday?.decision ||
            "HOLD",

          scalp:
            bundle.scalp?.decision ||
            "HOLD",

          master:
            bundle.master?.decision ||
            "HOLD",
        }
      );
    } catch (error) {
      p6Log(
        "ERROR",
        `${pairConfig.label} analysis failed`,
        p6ErrorMessage(error)
      );

      const reason =
        `Runtime analysis failed: ${
          p6ErrorMessage(error)
        }`;

      const failedEngine = (
        mode,
        engineName
      ) =>
        buildCanonicalEngineResult(
          {
            pair:
              pairConfig.label,

            decision:
              "HOLD",

            confidence: 0,
            score: 0,
            reason,

            timestamp:
              Date.now(),
          },
          {
            pair:
              pairConfig.label,

            mode,
            engineName,

            source:
              "runtime-error",

            available:
              false,
          }
        );

      const swing =
        failedEngine(
          "swing",
          "swing-runtime-error"
        );

      const intraday =
        failedEngine(
          "intraday",
          "intraday-runtime-error"
        );

      const scalp =
        failedEngine(
          "scalp",
          "scalp-runtime-error"
        );

      const master =
        failedEngine(
          "master",
          "master-runtime-error"
        );

      pairBundles.push({
        pair:
          pairConfig.label,

        symbol:
          pairConfig.label,

        pairLabel:
          pairConfig.label,

        generatedAt:
          liveNowIso(),

        timestamp:
          Date.now(),

        swing,
        intraday,
        scalp,
        master,

        engines: {
          swing,
          intraday,
          scalp,
          master,
        },

        runtime: {
          failed: true,
          error: reason,
        },
      });
    }
  }

  const generatedTimestamp =
    Date.now();

  const output =
    buildLiveAnalysisOutput({
      pairs:
        pairBundles,

      timestamp:
        generatedTimestamp,

      generatedAt:
        new Date(
          generatedTimestamp
        ).toISOString(),

      engineVersion:
        typeof ENGINE_VERSION !==
        "undefined"
          ? ENGINE_VERSION
          : "unknown",

      strategyVersion:
        typeof STRATEGY_VERSION !==
        "undefined"
          ? STRATEGY_VERSION
          : "unknown",
    });

  const autonomousResult =
    applyAutonomousControlToOutput(
      output,
      pairBundles,
      runtimeOptions
    );

  output.runtime = {
    generatedAt:
      output.generatedAt,

    nodeVersion:
      process.version,

    aiMemory: {
      enabled:
        AI_MEMORY_INTEGRATION.enabled,

      mode:
        AI_MEMORY_INTEGRATION.mode,

      available:
        Boolean(
          aiMemoryState &&
          aiMemoryState.available
        ),

      valid:
        Boolean(
          aiMemoryState &&
          aiMemoryState.valid
        ),

      generatedAt:
        aiMemoryState &&
        aiMemoryState.generatedAt
          ? aiMemoryState.generatedAt
          : null,

      reason:
        aiMemoryState &&
        aiMemoryState.reason
          ? aiMemoryState.reason
          : null,
    },

    autonomous:
      p6Clone(
        autonomousResult.summary
      ),

    inputs: {
      scalpSignals:
        runtimeOptions
          .scalpSignalsPath,

      scalpCandles:
        runtimeOptions
          .scalpCandlesPath,

      intradayH1:
        runtimeOptions
          .intradayH1Path,

      dailyOhlc:
        runtimeOptions
          .dailyOhlcPath,

      autonomousConfig:
        runtimeOptions
          .autonomousConfigPath,

      aiPolicy:
        runtimeOptions
          .aiPolicyPath,

      aiPolicyState:
        runtimeOptions
          .aiPolicyStatePath,
    },

    outputs: {
      liveAnalysis:
        runtimeOptions
          .liveAnalysisPath,

      analysisHistory:
        runtimeOptions
          .analysisHistoryPath,

      notifyState:
        runtimeOptions
          .notifyStatePath,

      aiDecisionLog:
        runtimeOptions
          .aiDecisionLogPath,

      aiDecisionState:
        runtimeOptions
          .aiDecisionStatePath,

      aiSafetyLog:
        runtimeOptions
          .aiSafetyLogPath,

      aiSafetyState:
        runtimeOptions
          .aiSafetyStatePath,
    },
  };

  const historyCandidates =
    collectHistoryRecordsFromOutput(
      output,
      {
        modes:
          runtimeOptions
            .historyModes,

        includeHold:
          runtimeOptions
            .includeHoldHistory,
      }
    );

  const historyResult =
    appendAnalysisHistoryRecords(
      sources.analysisHistory,
      historyCandidates,
      {
        includeHold:
          runtimeOptions
            .includeHoldHistory,

        dedupeWindowMs:
          runtimeOptions
            .historyDedupeWindowMs,

        maximumRecords:
          runtimeOptions
            .maximumHistoryRecords,

        engineVersion:
          output.engineVersion,

        strategyVersion:
          output.strategyVersion,
      }
    );

  output.historyTracker =
    buildDashboardHistoryTracker(
      historyResult.history
    );

  let telegramResult = {
    notifyState:
      normalizeNotifyState(
        sources.notifyState
      ),

    results: [],
    sentCount: 0,
    skippedCount: 0,
    failedCount: 0,
  };

  /*
   * Persist the authoritative analysis and history snapshots before any
   * external Telegram side effect. If either write fails, no notification
   * is sent and the run can safely retry without creating a duplicate alert.
   */
  output.runtime.telegram = {
    enabled:
      runtimeOptions.processTelegram ===
      true,

    status:
      runtimeOptions.processTelegram
        ? "pending"
        : "disabled",

    sentCount: 0,
    skippedCount: 0,
    failedCount: 0,
  };

  p6CreateBackupIfRequested(
    runtimeOptions
      .liveAnalysisPath,
    runtimeOptions
      .createBackups
  );

  p6CreateBackupIfRequested(
    runtimeOptions
      .analysisHistoryPath,
    runtimeOptions
      .createBackups
  );

  p6CreateBackupIfRequested(
    runtimeOptions
      .notifyStatePath,
    runtimeOptions
      .createBackups
  );

  p6AtomicWriteJson(
    runtimeOptions
      .liveAnalysisPath,
    output
  );

  p6AtomicWriteJson(
    runtimeOptions
      .analysisHistoryPath,
    historyResult.history
  );

  if (
    runtimeOptions.processTelegram
  ) {
    telegramResult =
      await processLiveOutputNotifications(
        output,
        sources.notifyState,
        {
          modes:
            runtimeOptions
              .telegramModes,

          minimumConfidence:
            runtimeOptions
              .telegramMinimumConfidence,

          cooldownMs:
            runtimeOptions
              .telegramCooldownMs,

          notifyHold:
            runtimeOptions
              .telegramNotifyHold,

          token:
            runtimeOptions
              .telegramToken,

          chatId:
            runtimeOptions
              .telegramChatId,

          timeoutMs:
            runtimeOptions
              .telegramTimeoutMs,

          disableNotification:
            runtimeOptions
              .telegramSilent,

          title:
            runtimeOptions
              .telegramTitle ||
            "PipSight Pro Signal",

          persistNotifyState:
            (nextNotifyState) => {
              p6AtomicWriteJson(
                runtimeOptions
                  .notifyStatePath,
                nextNotifyState
              );
            },
        }
      );
  }

  /*
   * Persist deduplication state immediately after Telegram processing and
   * before rewriting the optional Telegram runtime summary. This removes the
   * proven duplicate window caused by unrelated output writes occurring after
   * a successful send.
   */
  p6AtomicWriteJson(
    runtimeOptions
      .notifyStatePath,
    telegramResult.notifyState
  );

  output.runtime.telegram = {
    enabled:
      runtimeOptions.processTelegram ===
      true,

    status:
      runtimeOptions.processTelegram
        ? "completed"
        : "disabled",

    sentCount:
      telegramResult.sentCount,

    skippedCount:
      telegramResult.skippedCount,

    failedCount:
      telegramResult.failedCount,
  };

  p6AtomicWriteJson(
    runtimeOptions
      .liveAnalysisPath,
    output
  );

  const summary =
    p6BuildRuntimeSummary(
      output,
      telegramResult,
      historyResult.appendedCount
    );

  p6Log(
    "INFO",
    "Live analysis completed successfully",
    summary
  );

  return {
    ok: true,

    output,

    history:
      historyResult.history,

    notifyState:
      telegramResult.notifyState,

    telegram:
      telegramResult,

    autonomous:
      autonomousResult,

    summary,
  };
}


// ---------------------------------------------------------------------------
// Final compatibility aliases
// ---------------------------------------------------------------------------

async function runLiveAnalysis(
  options = {}
) {
  return runLiveAnalysisRuntime(
    options
  );
}

async function executeLiveAnalysis(
  options = {}
) {
  return runLiveAnalysisRuntime(
    options
  );
}

async function run(
  options = {}
) {
  return runLiveAnalysisRuntime(
    options
  );
}


// ---------------------------------------------------------------------------
// Unhandled runtime safety
// ---------------------------------------------------------------------------

function p6InstallRuntimeSafetyHandlers() {
  process.on(
    "unhandledRejection",
    (reason) => {
      p6Log(
        "ERROR",
        "Unhandled promise rejection",
        p6ErrorMessage(reason)
      );

      process.exitCode = 1;
    }
  );

  process.on(
    "uncaughtException",
    (error) => {
      p6Log(
        "ERROR",
        "Uncaught exception",
        p6ErrorMessage(error)
      );

      process.exitCode = 1;
    }
  );
}


// ---------------------------------------------------------------------------
// Direct execution
// ---------------------------------------------------------------------------

async function main() {
  p6InstallRuntimeSafetyHandlers();

  try {
    await runLiveAnalysisRuntime();
  } catch (error) {
    p6Log(
      "ERROR",
      "Live analysis runtime failed",
      p6ErrorMessage(error)
    );

    process.exitCode = 1;
  }
}

if (
  typeof require !== "undefined" &&
  typeof module !== "undefined" &&
  require.main === module
) {
  void main();
}


// ---------------------------------------------------------------------------
// Optional CommonJS exports
// ---------------------------------------------------------------------------

if (
  typeof module !== "undefined" &&
  module.exports
) {
  module.exports = {
    ENGINE_VERSION,
    AUTONOMOUS_LIVE_VERSION,
    STRATEGY_VERSION,
    PROFESSIONAL_LIVE_PIPELINE_VERSION,

    runLiveAnalysisRuntime,
    runLiveAnalysis,
    executeLiveAnalysis,
    run,

    prepareLiveAnalysisFrames,
    runLegacyCompatibleAnalysisPipeline,
    analyzeLiveTimeframe,
    aggregateLiveCandles,
    buildLiveTradePlan,
    applyLiveHigherTimeframeConfirmation,
    professionalLiveClosedRows,
    professionalLiveEmaSnapshot,
    professionalLiveRsiSnapshot,
    professionalLiveMacdSnapshot,
    professionalLiveDmiAdx,
    professionalLiveAtrSnapshot,

    selectScalpEngineResult,
    selectSwingEngineResult,
    selectIntradayEngineResult,

    buildMasterConsensus,
    buildPairEngineBundle,
    buildLiveAnalysisOutput,

    p6AutonomousLatestClosedAt,
    p6LoadAutonomousModules,
    p6BuildAutonomousDecisionInput,
    applyAutonomousControlToOutput,

    collectHistoryRecordsFromOutput,
    appendAnalysisHistoryRecords,
    buildDashboardHistoryTracker,

    normalizeNotifyState,
    processTelegramNotification,
    processLiveOutputNotifications,

    formatTelegramSignalMessage,
    sendTelegramMessage,
  };
}


